MAKE_ARGV = ['/usr/bin/make', '-j1', 'bochs']
NODE_PATH = '/opt/hostedtoolcache/node/22.23.3/x64/bin/node'
NODE_BYTES = 124827920
NODE_SHA256 = 'fde6a4bf8d0562f7751d1a2d6cb9b417c4cfe107bbcb0aa3e9a24e125e348f48'
