def bytes_ref(path, raw):
    return {'path': path, 'bytes': len(raw), 'sha256': sha256(raw)}


def configure_facts(raw, version_raw):
    need(1 <= len(raw) <= 1048576 and 1 <= len(version_raw) <= 16384,
         'bounded generated configuration/version headers')
    text = raw.decode('ascii')
    values = {}
    for name, value in re.findall(r'^#define[ \t]+(BX_[A-Z0-9_]+)[ \t]+([0-9]+)[ \t]*$', text, re.M):
        need(name not in values, 'unique generated configuration definition')
        values[name] = int(value)
    need(all(values.get(name) == number for name, number in
             (('BX_CPU_LEVEL', 3), ('BX_WITH_NOGUI', 1), ('BX_PLUGINS', 0), ('BX_DEBUGGER', 0))),
         'actual generated CPU3/nogui/no-plugin/no-debugger configuration')
    for name in ('X11', 'SDL', 'SDL2', 'WX', 'TERM', 'RFB', 'VNCSRV'):
        need(values.get('BX_WITH_' + name, 0) == 0, 'no additional generated display library')
    version = version_raw.decode('ascii')
    expected = {'VERSION': '"2.7"', 'VER_SVNFLAG': '0',
                'REL_STRING': '"Built from SVN snapshot on August  1, 2021"',
                'REL_TIMESTAMP': '"Sun Aug  1 10:07:00 CEST 2021"'}
    definitions = re.findall(r'^#define[ \t]+(VERSION|VER_SVNFLAG|REL_STRING|REL_TIMESTAMP)[ \t]+(.+?)[ \t]*$',
                             version, re.M)
    need(len(definitions) == 4 and dict(definitions) == expected, 'exact source-derived generated version header')
    return {'definitions': values, 'version': expected,
            'headerSha256': sha256(expected_header())}


def compact_build_manifest(request, manifest_raw, runtime_raw, manifest):
    def compact_ref(raw):
        return {'bytes': len(raw), 'sha256': sha256(raw)}
    binary = next(row for row in manifest['runtimeMembers'] if row['path'] == 'bin/bochs')
    value = {'schema': 'bw.bochs-ring3.build-manifest-compact.v1',
             'sourceHead': request['source']['head'], 'sourceTree': request['source']['tree'],
             'sourceFilesSha256': sha256(canonical(request['source']['files'])),
             'bochsCommit': UPSTREAM_COMMIT, 'bochsTree': UPSTREAM_TREE,
             'policySha256': request['policySha256'],
             'fullManifest': compact_ref(manifest_raw),
             'runtimeZip': compact_ref(runtime_raw),
             'binary': {name: binary[name] for name in ('bytes', 'sha256')},
             'configHeader': {name: manifest['configHeader'][name] for name in ('bytes', 'sha256')},
             'runtimeMembersSha256': sha256(canonical(manifest['runtimeMembers'])),
             'noticesSha256': sha256(canonical(manifest['notices'])),
             'buildCompleted': True, 'guestExecuted': False}
    encoded = canonical(value)
    need(len(encoded) <= 16384 and len(COMPACT_MARKER) + len(base64.b64encode(encoded)) <= 32768,
         'bounded complete Build log manifest')
    return value


def runtime_rows(files, modes):
    result = []
    for path, raw in sorted(files.items()):
        if path == 'bin/bochs':
            role = 'executable'
        elif path.startswith('lib/'):
            role = 'library'
        elif path.startswith('notices/'):
            role = 'notice'
        elif path == 'config/bochsrc.template':
            role = 'config'
        elif path == 'inputs/fixture.rom':
            role = 'rom'
        elif path == 'inputs/fixture.json':
            role = 'fixture'
        elif path == 'resources/vgabios.bin':
            role = 'vga'
        elif path == 'asset-manifest.json':
            role = 'manifest'
        else:
            raise Refusal('unassigned runtime member role')
        need(path in modes and modes[path] in (0o444, 0o555), 'explicit readonly runtime member mode')
        result.append({'path': path, 'role': role, 'mode': stat.S_IFREG | modes[path],
                       'bytes': len(raw), 'sha256': sha256(raw)})
    return result


def assemble_runtime(source, binary, rom, fixture_raw, vga, *, host_node,
                     libraries, notices):
    """Pure packaging of already observed bytes. No executable is run here."""
    need(type(binary) is bytes and 1 <= len(binary) <= 33554432, 'bounded nonempty compiled binary')
    facts = elf_facts(binary)
    need(facts['rpath'] is None and facts['runpath'] is None, 'no Bochs RPATH/RUNPATH')
    need(type(rom) is bytes and len(rom) == ROM_BYTES and sha256(rom) == ROM_SHA256,
         'unchanged authored fixture ROM')
    fixture = raw_object(fixture_raw, 1048576)
    need(fixture.get('schema') == 'bw.ring3.fixture.v1' and fixture.get('romSha256') == ROM_SHA256 and
         fixture.get('romBytes') == ROM_BYTES and fixture.get('wireBytes') == WIRE_BYTES and
         fixture.get('cpuProfile') == 'strict386' and fixture.get('deliverFaults') is False,
         'unchanged fixture generation profile')
    need(len(vga) == VGA_BYTES and sha256(vga) == VGA_SHA256 and
         hashlib.sha1(b'blob ' + str(len(vga)).encode('ascii') + b'\0' + vga).hexdigest() == VGA_BLOB,
         'exact source-selected nonempty LGPL VGA resource')
    closed(host_node, ('cachePath', 'bytes', 'sha256', 'elf', 'stageMode', 'stageUid', 'stageGid'),
           'closed cache-DATA to owned executable Node observation')
    need(host_node['cachePath'] == NODE_PATH and host_node['bytes'] == NODE_BYTES and
         host_node['sha256'] == NODE_SHA256 and host_node['stageMode'] == stat.S_IFREG | 0o555 and
         host_node['stageUid'] == host_node['stageGid'] == 0,
         'source-fixed Node cache identity and immutable executable stage')
    files = {'bin/bochs': binary, 'inputs/fixture.rom': rom, 'inputs/fixture.json': fixture_raw,
             'resources/vgabios.bin': vga, 'config/bochsrc.template': BOCHSRC_TEMPLATE}
    modes = {name: 0o555 if name == 'bin/bochs' else 0o444 for name in files}
    bindings = {}
    loader = None
    need(type(libraries) is dict and 1 <= len(libraries) <= 128, 'finite retained ELF closure')
    for original_path, item in sorted(libraries.items()):
        selected_tool_path(original_path)
        closed(item, ('members', 'raw'), 'closed observed library payload')
        library = item['raw']
        observed = elf_facts(library)
        need(observed['rpath'] is None and observed['runpath'] is None and
             type(item['members']) is list and 1 <= len(item['members']) <= 8 and
             len(set(item['members'])) == len(item['members']), 'finite exact library member bindings')
        members = []
        for name in item['members']:
            need(re.fullmatch(r'lib/[A-Za-z0-9+_.-]+', name) and name not in files,
                 'unique ordinary source-selected SONAME member')
            files[name] = library
            modes[name] = 0o555 if name == 'lib/ld-linux-x86-64.so.2' else 0o444
            members.append(name)
            if name == 'lib/ld-linux-x86-64.so.2':
                need(loader is None, 'one retained staged loader')
                loader = {'path': original_path, 'member': name, 'bytes': len(library),
                          'sha256': sha256(library), 'elf': observed}
        bindings[original_path] = {'members': members, 'bytes': len(library),
                                   'sha256': sha256(library), 'elf': observed}
    need(loader is not None, 'retained selected loader')
    library_by_member = {member: item['elf'] for item in bindings.values() for member in item['members']}
    pending = ['lib/' + name for name in facts['needed'] + host_node['elf']['needed']]
    pending.append('lib/ld-linux-x86-64.so.2')
    reached = set()
    while pending:
        member = pending.pop()
        if member in reached:
            continue
        need(member in library_by_member, 'every selected DT_NEEDED has retained bytes')
        reached.add(member)
        pending.extend('lib/' + name for name in library_by_member[member]['needed'])
    need(reached == set(library_by_member), 'exact needed ELF closure, no extraneous library executable')
    notice_rows = []
    need(type(notices) is dict and notices, 'closed retained source/runtime notice graph')
    for name, raw in sorted(notices.items()):
        member_name(name)
        need(name.startswith('notices/') and name not in files and type(raw) is bytes and
             1 <= len(raw) <= 33554432, 'nonempty selected notice/source member')
        files[name], modes[name] = raw, 0o444
        notice_rows.append({'path': name, 'role': 'notice', 'mode': stat.S_IFREG | 0o444,
                            'bytes': len(raw), 'sha256': sha256(raw)})
    need('notices/vgabios-corresponding-source.tar.gz' in files and
         len(files['notices/vgabios-corresponding-source.tar.gz']) == VGA_SOURCE_BYTES and
         sha256(files['notices/vgabios-corresponding-source.tar.gz']) == VGA_SOURCE_SHA256,
         'retained exact complete VGA corresponding source TAR')
    asset = {'schema': 'bw.bochs-ring3.runtime-assets.v1',
             'source': {'head': source['head'], 'tree': source['tree'],
                        'filesSha256': sha256(canonical(source['files']))},
             'bochsSource': {'commit': UPSTREAM_COMMIT, 'tree': UPSTREAM_TREE,
                             'sourceSelectionSha256': SOURCE_SELECTION_SHA256},
             'hostNode': host_node, 'loader': loader, 'bindings': bindings,
             'files': runtime_rows(files, modes)}
    files['asset-manifest.json'] = canonical(asset)
    modes['asset-manifest.json'] = 0o444
    need(sum(map(len, files.values())) <= 67108864 and len(files) <= 256,
         'bounded complete runtime package')
    return {'files': files, 'modes': modes, 'notices': notice_rows}



def resolve_projection(path, selected, aliases=None, directories=None):
    selected_tool_path(path)
    aliases = {} if aliases is None else aliases
    directories = {} if directories is None else directories
    current, seen = path, set()
    for _ in range(16):
        need(current not in seen, 'finite selected alias graph without cycle')
        seen.add(current)
        parts = current.lstrip('/').split('/')
        changed = False
        for index in range(len(parts)):
            candidate = '/' + '/'.join(parts[:index + 1])
            table = selected['aliases'] if index == len(parts) - 1 else selected['directoryAliases']
            if candidate in table:
                row = table[candidate]
                closed(row, ('linkText', 'target'), 'selected alias projection')
                target = posixpath.normpath(row['linkText'] if row['linkText'].startswith('/') else
                    posixpath.join(posixpath.dirname(candidate), row['linkText']))
                need(target == row['target'], 'selected lexical alias target')
                (aliases if index == len(parts) - 1 else directories)[candidate] = row
                current = posixpath.join(target, *parts[index + 1:])
                selected_tool_path(current)
                changed = True; break
        if not changed:
            need(current in selected['files'], 'selected resolved file exists')
            return current
    raise Refusal('selected alias depth exceeded')


def host_runtime_selection(selected, structural, binary_elf, node_elf):
    aliases, directories, files = {}, {}, {}
    interpreters = [row['interpreter'] for row in (binary_elf, node_elf) if row['interpreter']]
    need(interpreters and all(path == '/lib64/ld-linux-x86-64.so.2' for path in interpreters),
         'selected dynamic runtime interpreter')
    pending = list(interpreters)
    pending += ['/usr/lib/x86_64-linux-gnu/' + name for row in (binary_elf, node_elf)
                for name in row['needed']]
    while pending:
        original = resolve_projection(pending.pop(), selected, aliases, directories)
        if original in files:
            continue
        row = selected['files'][original]
        need(original in structural['files'] and row['elf'] is not None and
             row['uid'] == row['gid'] == 0 and row['mode'] & 0o022 == 0 and
             row['elf']['rpath'] is None and row['elf']['runpath'] is None,
             'closed admitted current host runtime file')
        sparse = structural['files'][original]
        need(sparse['fileBytes'] == row['bytes'] and sparse['fileSha256'] == row['sha256'] and
             {key: item for key, item in sparse['structure'].items() if key != 'soname'} == row['elf'],
             'selected structural runtime metadata')
        files[original] = row
        pending.extend('/usr/lib/x86_64-linux-gnu/' + name for name in row['elf']['needed'])
        if row['elf']['interpreter']:
            pending.append(row['elf']['interpreter'])
        need(len(files) <= 128, 'finite runtime host closure')
    loader = resolve_projection(interpreters[0], selected, aliases, directories)
    metadata_files = {path: structural['files'][path] for path in sorted(files)}
    metadata_files[NODE_PATH] = structural['files'][NODE_PATH]
    metadata = {'schema': 'bw.bochs-ring3.runtime-elf-metadata.v1', 'files': metadata_files,
        'rawBytes': sum(row['bytes'] for item in metadata_files.values() for row in item['ranges'])}
    return {'loaderPath': loader, 'files': files, 'aliases': aliases,
            'directoryAliases': directories, 'elfMetadata': metadata}


def assemble_runtime_v2(source, binary, rom, fixture_raw, vga, *, host_node,
                        selected, structural, notices):
    """Current distribution boundary: no host library/Node body in the ZIP."""
    need(type(binary) is bytes and 64 <= len(binary) <= 33554432, 'bounded compiled Bochs original')
    observed = sparse_elf(binary)['structure']
    binary_elf = {key: item for key, item in observed.items() if key != 'soname'}
    need(binary_elf['rpath'] is None and binary_elf['runpath'] is None, 'no built Bochs injected search path')
    fixed_rom, fixed_fixture = authored_inputs()
    need(rom == fixed_rom and fixture_raw == fixed_fixture, 'exact unchanged generated authored inputs')
    need(len(vga) == VGA_BYTES and sha256(vga) == VGA_SHA256 and
         hashlib.sha1(b'blob ' + str(len(vga)).encode() + b'\0' + vga).hexdigest() == VGA_BLOB,
         'exact source-selected LGPL VGA resource')
    runtime = host_runtime_selection(selected, structural, binary_elf, host_node['elf'])
    files = {'bin/bochs': binary, 'inputs/fixture.rom': rom, 'inputs/fixture.json': fixture_raw,
             'resources/vgabios.bin': vga, 'config/bochsrc.template': BOCHSRC_TEMPLATE}
    modes = {name: 0o555 if name == 'bin/bochs' else 0o444 for name in files}
    rows = []
    need(type(notices) is dict and 'notices/bochs-selected-corresponding-source.tar.gz' in notices and
         'notices/vgabios-corresponding-source.tar.gz' in notices, 'complete Bochs and VGA corresponding source')
    for name, raw in sorted(notices.items()):
        member_name(name)
        need(name.startswith('notices/') and type(raw) is bytes and 1 <= len(raw) <= 33554432,
             'closed nonempty source/notice member')
        files[name] = raw; modes[name] = 0o444
        rows.append({'path': name, 'role': 'notice', 'mode': stat.S_IFREG | 0o444,
                     'bytes': len(raw), 'sha256': sha256(raw)})
    raw = notices['notices/vgabios-corresponding-source.tar.gz']
    need(len(raw) == VGA_SOURCE_BYTES and sha256(raw) == VGA_SOURCE_SHA256,
         'complete reviewed VGA corresponding-source bytes')
    asset = {'schema': 'bw.bochs-ring3.runtime-assets.v2',
        'source': {'head': source['head'], 'tree': source['tree'],
                   'filesSha256': sha256(canonical(source['files']))},
        'bochsSource': {'commit': UPSTREAM_COMMIT, 'tree': UPSTREAM_TREE,
                        'sourceSelectionSha256': SOURCE_SELECTION_SHA256},
        'hostNode': host_node, 'hostRuntime': runtime, 'files': runtime_rows(files, modes)}
    files['asset-manifest.json'] = canonical(asset); modes['asset-manifest.json'] = 0o444
    need(not any(name.startswith('lib/') or name.endswith('/node') for name in files) and
         len(files) <= 256 and sum(map(len, files.values())) <= 67108864,
         'current runtime closed distribution and byte/member bounds')
    return {'files': files, 'modes': modes, 'notices': rows}


NODE_METADATA_FIELDS = ('dev', 'ino', 'mode', 'uid', 'gid', 'nlink', 'size', 'mtime_ns', 'ctime_ns')


def node_stage_directory(route, env):
    need(route in ROUTES and re.fullmatch(r'[1-9][0-9]{0,19}', env.get('GITHUB_RUN_ID', '')) and
         env.get('GITHUB_RUN_ATTEMPT') == '1', 'source-derived first-attempt Node stage path')
    return Path('/run/bw-bochs-' + route + '-v1-' + env['GITHUB_RUN_ID'] + '-1-node')


class NodeStageCopy:
    """Adapted from the held MIT NodeStageCopy: cache DATA never executes.

    Exactly one copy, exclusive private root destination, full independent
    reopen/hash, then readonly publication. No actual copy runs in controls.
    """
    def __init__(self, route, env, invoker):
        self.path = node_stage_directory(route, env)
        self.invoker = tuple(invoker)
        need(len(self.invoker) == 2 and all(type(x) is int and 1 <= x < 2 ** 31 for x in self.invoker),
             'source-authenticated nonroot Node cache invoker identity')
        self.fds, self.bindings = {}, {}
        self.sparse_node = None
        self.attempted = False
        self.facts = {'schema': 'bw.bochs-ring3.node-stage.v1', 'sourcePath': NODE_PATH,
            'stagePath': str(self.path / 'node'), 'recordPath': str(self.path / 'stage.json'),
            'invoker': {'uid': invoker[0], 'gid': invoker[1]},
            'metadataFields': list(NODE_METADATA_FIELDS), 'created': [],
            'sourceBefore': None, 'sourceAfter': None, 'sourceNamedAfter': None,
            'sourceBytesRead': 0, 'bytesCopied': 0, 'writeUncertain': False,
            'copiedSha256': None, 'readbackBytes': 0, 'readbackSha256': None,
            'elfReadBytes': 0, 'elf': None, 'fileBeforePublication': None,
            'parents': {}, 'directoryInitial': None, 'fileInitial': None,
            'targetAfterFailure': None, 'directoryAfterFailure': None,
            'lastOperation': None,
            'file': None, 'fileNamed': None, 'directoryBeforePublication': None,
            'directory': None, 'directoryNamed': None,
            'filePublicationAttempted': False, 'directoryPublicationAttempted': False,
            'filePublished': False, 'directoryPublished': False, 'record': None,
            'checkedAfter': None,
            'firstFailure': None, 'secondary': []}
    @staticmethod
    def metadata(info):
        return [getattr(info, 'st_' + name) for name in NODE_METADATA_FIELDS]
    def error(self, exc, phase):
        current = self.facts['lastOperation'] or {}
        item = failure(exc, phase, current.get('role'), current.get('path'))
        if self.facts['firstFailure'] is None:
            self.facts['firstFailure'] = item
        elif len(self.facts['secondary']) < SECONDARY_LIMIT:
            self.facts['secondary'].append(item)
    def directory(self, path):
        self.facts['lastOperation'] = {'role': 'node-stage-directory', 'path': str(path), 'operation': 'open/readback'}
        parent = self.fds.get(path.parent)
        fd = os.open(path if parent is None else path.name,
                     os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_NONBLOCK | os.O_CLOEXEC,
                     **({} if parent is None else {'dir_fd': parent}))
        self.fds[path] = fd
        held, named = self.metadata(os.fstat(fd)), self.metadata(path.lstat())
        need(path.resolve(strict=True) == path and held == named and stat.S_ISDIR(held[2]) and
             held[3:5] == [0, 0] and held[2] & 0o022 == 0, 'held root-owned Node-stage directory')
        self.bindings[path] = held
        if path == self.path:
            self.facts['directoryInitial'] = held
        else:
            self.facts['parents'][str(path)] = {'before': held, 'namedBefore': named,
                                               'after': None, 'namedAfter': None}
        return fd
    def recheck(self):
        for path, fd in self.fds.items():
            self.facts['lastOperation'] = {'role': 'node-stage-directory', 'path': str(path), 'operation': 'held/named readback'}
            held, named = self.metadata(os.fstat(fd)), self.metadata(path.lstat())
            need(held[:5] == named[:5] == self.bindings[path][:5] and
                 path.resolve(strict=True) == path, 'Node-stage parent first-five identity')
            if str(path) in self.facts['parents']:
                self.facts['parents'][str(path)]['after'] = held
                self.facts['parents'][str(path)]['namedAfter'] = named
    def close_fd(self, fd, phase, role=None, path=None):
        if fd is not None:
            self.facts['lastOperation'] = {'role': role, 'path': path, 'operation': 'close-held'}
            try:
                os.close(fd)
            except BaseException as exc:
                self.error(exc, phase)
    def copy(self):
        need(not self.attempted, 'Node stage consumed; no copy retry')
        try:
            return self._copy()
        except BaseException as exc:
            if self.facts['firstFailure'] is None:
                self.error(exc, 'node-stage')
            exc.bochs_partial = {'nodeStage': self.facts}
            exc.bochs_first = self.facts['firstFailure']
            exc.bochs_secondary = self.facts['secondary']
            raise
    def _copy(self):
        need(not self.attempted, 'Node stage consumed; no copy retry')
        self.attempted = True
        source_fd = target_fd = None
        try:
            need(os.getresuid() == (0, 0, 0) and os.getresgid() == (0, 0, 0), 'root-only Node data staging')
            self.directory(Path('/'))
            parent = self.directory(Path('/run'))
            self.recheck()
            os.mkdir(self.path.name, 0o700, dir_fd=parent)
            self.facts['created'].append(str(self.path))
            directory = self.directory(self.path)
            need(stat.S_IMODE(self.bindings[self.path][2]) == 0o700, 'private unpublished Node stage')
            source = Path(NODE_PATH)
            self.facts['lastOperation'] = {'role': 'node-cache-data', 'path': NODE_PATH, 'operation': 'open/readback'}
            need(source.resolve(strict=True) == source, 'canonical fixed Node cache DATA path')
            source_fd = os.open(NODE_PATH, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK | os.O_CLOEXEC)
            before = self.metadata(os.fstat(source_fd))
            self.facts['sourceBefore'] = before
            need(before == self.metadata(source.lstat()) and stat.S_ISREG(before[2]) and
                 before[5] == 1 and before[6] == NODE_BYTES and before[2] & 0o6000 == 0 and
                 tuple(before[3:5]) in ((0, 0), self.invoker),
                 'bounded single-link Node cache DATA, not executable authority')
            self.facts['lastOperation'] = {'role': 'node-staged-executable', 'path': str(self.path / 'node'), 'operation': 'exclusive create'}
            target_fd = os.open('node', os.O_RDWR | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW |
                                os.O_NONBLOCK | os.O_CLOEXEC, 0o600, dir_fd=directory)
            self.facts['created'].append(str(self.path / 'node'))
            first = self.metadata(os.fstat(target_fd))
            self.facts['fileInitial'] = first
            need(stat.S_ISREG(first[2]) and stat.S_IMODE(first[2]) == 0o600 and
                 first[3:7] == [0, 0, 1, 0], 'fresh nonexecutable root Node output')
            digest = hashlib.sha256()
            prefix = b''
            while True:
                self.facts['lastOperation'] = {'role': 'node-cache-data', 'path': NODE_PATH, 'operation': 'bounded read'}
                chunk = os.read(source_fd, min(65536, NODE_BYTES + 1 - self.facts['sourceBytesRead']))
                if not chunk:
                    break
                self.facts['sourceBytesRead'] += len(chunk)
                need(self.facts['sourceBytesRead'] <= NODE_BYTES, 'fixed Node data copy cap')
                digest.update(chunk)
                prefix = (prefix + chunk)[:4]
                try:
                    self.facts['lastOperation'] = {'role': 'node-staged-executable', 'path': str(self.path / 'node'), 'operation': 'once-only chunk write'}
                    written = os.write(target_fd, chunk)
                except BaseException:
                    self.facts['writeUncertain'] = True
                    raise
                need(type(written) is int and 0 <= written <= len(chunk), 'bounded Node chunk write')
                self.facts['bytesCopied'] += written
                need(written == len(chunk), 'complete once-only Node chunk write')
            self.facts['copiedSha256'] = digest.hexdigest()
            self.facts['lastOperation'] = {'role': 'node-cache-data', 'path': NODE_PATH, 'operation': 'held/named after readback'}
            self.facts['sourceAfter'] = self.metadata(os.fstat(source_fd))
            self.facts['sourceNamedAfter'] = self.metadata(source.lstat())
            need(self.facts['sourceBytesRead'] == self.facts['bytesCopied'] == NODE_BYTES and
                 digest.hexdigest() == NODE_SHA256 and prefix == b'\x7fELF' and
                 before == self.facts['sourceAfter'] == self.facts['sourceNamedAfter'] and
                 source.resolve(strict=True) == source, 'fixed Node bytes and source held/named stability')
            need(self.metadata(os.fstat(target_fd))[3:7] == [0, 0, 1, NODE_BYTES], 'complete private Node output')
            self.facts['lastOperation'] = {'role': 'node-staged-executable', 'path': str(self.path / 'node'), 'operation': 'fsync'}
            os.fsync(target_fd)
        except BaseException as exc:
            self.error(exc, 'node-copy')
            for key, observe in (
                ('sourceAfter', lambda: os.fstat(source_fd) if source_fd is not None else None),
                ('sourceNamedAfter', lambda: Path(NODE_PATH).lstat() if source_fd is not None else None),
                ('targetAfterFailure', lambda: os.fstat(target_fd) if target_fd is not None else None),
                ('directoryAfterFailure', lambda: os.fstat(self.fds[self.path]) if self.path in self.fds else None)):
                try:
                    info = observe()
                    if info is not None:
                        self.facts[key] = self.metadata(info)
                except BaseException as extra:
                    self.error(extra, 'node-copy-failure-stat')
        finally:
            self.close_fd(target_fd, 'node-copy-target-close', 'node-staged-executable', str(self.path / 'node'))
            self.close_fd(source_fd, 'node-copy-source-close', 'node-cache-data', NODE_PATH)
        if self.facts['firstFailure'] is not None:
            error = Refusal(self.facts['firstFailure']['message'])
            error.bochs_partial = {'nodeStage': self.facts}
            raise error
        self.recheck()
        directory = self.fds[self.path]
        fd = None
        try:
            self.facts['lastOperation'] = {'role': 'node-staged-executable', 'path': str(self.path / 'node'), 'operation': 'independent reopen/hash'}
            fd = os.open('node', os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK | os.O_CLOEXEC,
                         dir_fd=directory)
            before = self.metadata(os.fstat(fd))
            need(before == self.metadata(os.stat('node', dir_fd=directory, follow_symlinks=False)) and
                 stat.S_ISREG(before[2]) and stat.S_IMODE(before[2]) == 0o600 and
                 before[3:7] == [0, 0, 1, NODE_BYTES], 'independent root Node reopen')
            self.facts['fileBeforePublication'] = before
            digest = hashlib.sha256()
            while True:
                chunk = os.read(fd, min(65536, NODE_BYTES + 1 - self.facts['readbackBytes']))
                if not chunk:
                    break
                self.facts['readbackBytes'] += len(chunk)
                need(self.facts['readbackBytes'] <= NODE_BYTES, 'independent Node readback cap')
                digest.update(chunk)
            self.facts['readbackSha256'] = digest.hexdigest()
            need(self.facts['readbackBytes'] == NODE_BYTES and digest.hexdigest() == NODE_SHA256 and
                 before == self.metadata(os.fstat(fd)) ==
                 self.metadata(os.stat('node', dir_fd=directory, follow_symlinks=False)),
                 'independent complete Node bytes before executable publication')
            def read_at(offset, count):
                self.facts['elfReadBytes'] += count
                need(self.facts['elfReadBytes'] <= 2097152, 'bounded staged Node ELF range reads')
                return os.pread(fd, count, offset)
            self.sparse_node = sparse_elf_from_reader(NODE_BYTES, read_at, self.facts['readbackSha256'])
            self.facts['elf'] = {key: value for key, value in self.sparse_node['structure'].items()
                                 if key != 'soname'}
            need(self.facts['elf']['rpath'] is None and self.facts['elf']['runpath'] is None,
                 'staged Node has no RPATH/RUNPATH')
            self.facts['filePublicationAttempted'] = True
            os.fchmod(fd, 0o555)
            self.facts['file'] = self.metadata(os.fstat(fd))
            self.facts['fileNamed'] = self.metadata(os.stat('node', dir_fd=directory, follow_symlinks=False))
            need(stat.S_IMODE(self.facts['file'][2]) == 0o555 and
                 self.facts['file'][3:7] == [0, 0, 1, NODE_BYTES] and
                 self.facts['file'][:2] == before[:2] and self.facts['file'] == self.facts['fileNamed'],
                 'readonly root Node file publication')
            self.facts['filePublished'] = True
        except BaseException as exc:
            self.error(exc, 'node-readback-publication')
            if fd is not None:
                try:
                    self.facts['targetAfterFailure'] = self.metadata(os.fstat(fd))
                except BaseException as extra:
                    self.error(extra, 'node-publication-failed-stat')
        finally:
            self.close_fd(fd, 'node-readback-close', 'node-staged-executable', str(self.path / 'node'))
        if self.facts['firstFailure'] is not None:
            error = Refusal(self.facts['firstFailure']['message'])
            error.bochs_partial = {'nodeStage': self.facts}
            raise error
        self.recheck()
        record = canonical({'schema': 'bw.bochs-ring3.node-installation.v1', 'sourcePath': NODE_PATH,
                            'stagePath': self.facts['stagePath'], 'bytes': NODE_BYTES,
                            'sha256': NODE_SHA256, 'uid': 0, 'gid': 0, 'mode': stat.S_IFREG | 0o555})
        fd = None
        try:
            self.facts['lastOperation'] = {'role': 'node-stage-record', 'path': str(self.path / 'stage.json'), 'operation': 'exclusive create/readback'}
            fd = os.open('stage.json', os.O_RDWR | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW |
                         os.O_NONBLOCK | os.O_CLOEXEC, 0o600, dir_fd=directory)
            self.facts['created'].append(str(self.path / 'stage.json'))
            need(os.write(fd, record) == len(record), 'once-only Node installation record write')
            os.fchmod(fd, 0o444)
            os.lseek(fd, 0, os.SEEK_SET)
            before = self.metadata(os.fstat(fd))
            need(stat.S_ISREG(before[2]) and stat.S_IMODE(before[2]) == 0o444 and
                 before[3:7] == [0, 0, 1, len(record)] and os.read(fd, len(record) + 1) == record and
                 before == self.metadata(os.fstat(fd)) ==
                 self.metadata(os.stat('stage.json', dir_fd=directory, follow_symlinks=False)),
                 'root readonly exact Node installation record')
            self.facts['record'] = {'bytes': len(record), 'sha256': sha256(record),
                                    'metadata': before, 'text': record.decode('utf-8')}
        except BaseException as exc:
            self.error(exc, 'node-record')
        finally:
            self.close_fd(fd, 'node-record-close', 'node-stage-record', str(self.path / 'stage.json'))
        if self.facts['firstFailure'] is None:
            try:
                self.recheck()
                self.facts['directoryBeforePublication'] = self.metadata(os.fstat(directory))
                self.facts['directoryPublicationAttempted'] = True
                self.facts['lastOperation'] = {'role': 'node-stage-directory', 'path': str(self.path), 'operation': 'readonly publication'}
                os.fchmod(directory, 0o555)
                self.facts['directory'] = self.metadata(os.fstat(directory))
                self.facts['directoryNamed'] = self.metadata(self.path.lstat())
                need(stat.S_IMODE(self.facts['directory'][2]) == 0o555 and
                     self.facts['directory'][3:5] == [0, 0] and
                     self.facts['directory'][:2] == self.bindings[self.path][:2] and
                     self.facts['directory'] == self.facts['directoryNamed'],
                     'root readonly Node directory publication')
                self.bindings[self.path] = self.facts['directory']
                self.facts['directoryPublished'] = True
                self.recheck()
            except BaseException as exc:
                self.error(exc, 'node-directory-publication')
                try:
                    self.facts['directoryAfterFailure'] = self.metadata(os.fstat(directory))
                except BaseException as extra:
                    self.error(extra, 'node-directory-failed-stat')
        if self.facts['firstFailure'] is not None:
            error = Refusal(self.facts['firstFailure']['message'])
            error.bochs_partial = {'nodeStage': self.facts}
            raise error
        return self.facts
    def verify_after(self, *, full_hash):
        """No Node invocation in inventory: immutable identity check suffices there.

        Build/reference reread the full staged executable after work. Neither
        copies nor executes the mutable original-cache pathname again.
        """
        need(self.facts['firstFailure'] is None and self.facts['filePublished'] and
             self.facts['directoryPublished'], 'successful Node publication before verification')
        self.recheck()
        fd = None
        observed = {'hashRead': full_hash, 'bytesRead': 0, 'sha256': None,
                    'before': None, 'after': None, 'named': None, 'elf': None, 'elfReadBytes': 0}
        try:
            directory = self.fds[self.path]
            fd = os.open('node', os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK | os.O_CLOEXEC,
                         dir_fd=directory)
            observed['before'] = self.metadata(os.fstat(fd))
            need(observed['before'] == self.facts['file'], 'same readonly staged Node before after-check')
            if full_hash:
                digest = hashlib.sha256()
                while True:
                    chunk = os.read(fd, min(65536, NODE_BYTES + 1 - observed['bytesRead']))
                    if not chunk:
                        break
                    observed['bytesRead'] += len(chunk)
                    need(observed['bytesRead'] <= NODE_BYTES, 'staged Node after-read cap')
                    digest.update(chunk)
                observed['sha256'] = digest.hexdigest()
                need(observed['bytesRead'] == NODE_BYTES and digest.hexdigest() == NODE_SHA256,
                     'complete staged Node after-execution byte identity')
                def read_at(offset, count):
                    observed['elfReadBytes'] += count
                    need(observed['elfReadBytes'] <= 2097152, 'bounded Node after ELF range reads')
                    return os.pread(fd, count, offset)
                sparse_after = sparse_elf_from_reader(NODE_BYTES, read_at, observed['sha256'])
                need(sparse_after == self.sparse_node, 'same staged Node exact structural range readback')
                observed['elf'] = {key: value for key, value in sparse_after['structure'].items()
                                   if key != 'soname'}
                need(observed['elf'] == self.facts['elf'], 'staged Node after ELF identity')
            observed['after'] = self.metadata(os.fstat(fd))
            observed['named'] = self.metadata(os.stat('node', dir_fd=directory, follow_symlinks=False))
            need(observed['before'] == observed['after'] == observed['named'],
                 'staged Node complete held/named after-check')
        except BaseException as exc:
            self.error(exc, 'node-after-verification')
        finally:
            self.close_fd(fd, 'node-after-verification-close', 'node-staged-executable', str(self.path / 'node'))
            self.facts['checkedAfter'] = observed
        if self.facts['firstFailure'] is not None:
            error = Refusal(self.facts['firstFailure']['message'])
            error.bochs_partial = {'nodeStage': self.facts}
            raise error
        return self.facts
    def close(self):
        fds = list(reversed(list(self.fds.items())))
        self.fds = {}
        for path, fd in fds:
            self.close_fd(fd, 'node-stage-parent-close', 'node-stage-directory', str(path))


def node_expectation(facts):
    return {'cachePath': facts['sourcePath'], 'bytes': facts['file'][6],
            'sha256': facts['readbackSha256'], 'elf': facts['elf'],
            'stageMode': facts['file'][2], 'stageUid': facts['file'][3],
            'stageGid': facts['file'][4]}


def check_node_stage(facts, route, env, *, after=False):
    need(type(facts) is dict and facts.get('schema') == 'bw.bochs-ring3.node-stage.v1',
         'typed cache-DATA/readonly-executable Node stage')
    path = node_stage_directory(route, env)
    need(facts['sourcePath'] == NODE_PATH and facts['stagePath'] == str(path / 'node') and
         facts['recordPath'] == str(path / 'stage.json') and
         facts['metadataFields'] == list(NODE_METADATA_FIELDS), 'source-derived Node role paths')
    def meta(row):
        need(type(row) is list and len(row) == 9 and
             all(type(value) is int and value >= 0 for value in row) and row[1] > 0,
             'typed nine-field Node identity')
        return row
    invoker = facts['invoker']
    closed(invoker, ('uid', 'gid'), 'source-authenticated Node invoker')
    integer(invoker['uid'], 1, 2 ** 31 - 1, 'Node invoker UID')
    integer(invoker['gid'], 1, 2 ** 31 - 1, 'Node invoker GID')
    source = meta(facts['sourceBefore'])
    need(source == meta(facts['sourceAfter']) == meta(facts['sourceNamedAfter']) and
         stat.S_ISREG(source[2]) and source[2] & 0o6000 == 0 and source[5:7] == [1, NODE_BYTES] and
         tuple(source[3:5]) in ((0, 0), (invoker['uid'], invoker['gid'])),
         'bounded fixed Node cache DATA identity (not executable permission)')
    initial, before, final = meta(facts['fileInitial']), meta(facts['fileBeforePublication']), meta(facts['file'])
    need(initial[2:7] == [stat.S_IFREG | 0o600, 0, 0, 1, 0] and
         before[2:7] == [stat.S_IFREG | 0o600, 0, 0, 1, NODE_BYTES] and
         final[2:7] == [stat.S_IFREG | 0o555, 0, 0, 1, NODE_BYTES] and
         initial[:2] == before[:2] == final[:2] and final == meta(facts['fileNamed']),
         'fresh root0600 copy becomes same readonly0555 executable')
    first_dir = meta(facts['directoryInitial'])
    before_dir, final_dir = meta(facts['directoryBeforePublication']), meta(facts['directory'])
    need(first_dir[2:5] == before_dir[2:5] == [stat.S_IFDIR | 0o700, 0, 0] and
         final_dir[2:5] == [stat.S_IFDIR | 0o555, 0, 0] and
         first_dir[:2] == before_dir[:2] == final_dir[:2] and
         final_dir == meta(facts['directoryNamed']), 'fresh private root directory readonly publication')
    need(set(facts['parents']) == {'/', '/run'}, 'closed Node-stage parent roster')
    for row in facts['parents'].values():
        closed(row, ('before', 'namedBefore', 'after', 'namedAfter'), 'Node parent raw readbacks')
        snapshots = [meta(row[key]) for key in ('before', 'namedBefore', 'after', 'namedAfter')]
        need(all(snap[:5] == snapshots[0][:5] for snap in snapshots) and
             stat.S_ISDIR(snapshots[0][2]) and snapshots[0][3:5] == [0, 0] and
             snapshots[0][2] & 0o022 == 0, 'held/named root-parent first-five continuity')
    need(facts['created'] == [str(path), str(path / 'node'), str(path / 'stage.json')] and
         facts['sourceBytesRead'] == facts['bytesCopied'] == facts['readbackBytes'] == NODE_BYTES and
         facts['copiedSha256'] == facts['readbackSha256'] == NODE_SHA256 and
         facts['writeUncertain'] is False and facts['filePublicationAttempted'] is True and
         facts['directoryPublicationAttempted'] is True and facts['filePublished'] is True and
         facts['directoryPublished'] is True and facts['firstFailure'] is None and facts['secondary'] == [],
         'once-only complete independent Node hash/publication observations')
    integer(facts['elfReadBytes'], 1, 2097152, 'bounded staged Node ELF range reads')
    need(type(facts['elf']) is dict and facts['elf']['class'] == 'ELF64' and
         facts['elf']['machine'] == 'x86-64' and facts['elf']['rpath'] is None and
         facts['elf']['runpath'] is None, 'source-observed staged Node ELF')
    record = facts['record']
    closed(record, ('bytes', 'sha256', 'metadata', 'text'), 'closed readonly Node installation record')
    expected = canonical({'schema': 'bw.bochs-ring3.node-installation.v1', 'sourcePath': NODE_PATH,
                          'stagePath': str(path / 'node'), 'bytes': NODE_BYTES,
                          'sha256': NODE_SHA256, 'uid': 0, 'gid': 0, 'mode': stat.S_IFREG | 0o555})
    need(record['text'].encode('utf-8') == expected and record['bytes'] == len(expected) and
         record['sha256'] == sha256(expected) and
         meta(record['metadata'])[2:7] == [stat.S_IFREG | 0o444, 0, 0, 1, len(expected)],
         'exact readonly source-bound Node record bytes')
    if after:
        checked = facts['checkedAfter']
        closed(checked, ('hashRead', 'bytesRead', 'sha256', 'before', 'after', 'named', 'elf', 'elfReadBytes'),
               'Node after-use observations')
        need(meta(checked['before']) == meta(checked['after']) == meta(checked['named']) == final,
             'same immutable staged Node after work')
        if route == 'toolchain':
            need(checked['hashRead'] is False and checked['bytesRead'] == 0 and
                 checked['sha256'] is None and checked['elf'] is None and checked['elfReadBytes'] == 0,
                 'metadata route does not claim an unperformed after hash or Node execution')
        else:
            need(checked['hashRead'] is True and checked['bytesRead'] == NODE_BYTES and
                 checked['sha256'] == NODE_SHA256 and checked['elf'] == facts['elf'],
                 'actual staged Node after-execution complete hash/ELF')
            integer(checked['elfReadBytes'], 1, 2097152, 'bounded Node after ELF range-read count')
    return facts


def collect_build(request_raw, event_raw, env, ops):
    request = admitted_request('build', request_raw, event_raw, env)
    admit_build_inputs(request)
    value = original('build', request_raw, event_raw)
    observations = {name: None for name in ('upstream', 'sourceSelection', 'toolchainBefore',
        'toolchainAfter', 'configure', 'configHeader', 'compilerCommands', 'binary',
        'runtimeManifest', 'notices', 'compactManifest', 'correspondingSource', 'nodeStage',
        'runtimeElfMetadata', 'hostRuntime')}
    value['observations'] = observations
    roles = {'request.original.json': request_raw, 'event.original.json': event_raw}
    phase = 'source-before'
    manifest = None
    runtime_raw = None
    try:
        value['sourceBefore'] = ops.source(request['source'], env)
        roles['source.before.json'] = canonical(value['sourceBefore'])
        value['resources'] = {'before': ops.resources('build'), 'after': None}
        phase = 'node-cache-data-staging'
        observations['nodeStage'] = ops.node_stage()
        check_node_stage(observations['nodeStage'], 'build', env)
        roles['node-stage.original.json'] = canonical(observations['nodeStage'])
        phase = 'build-toolchain-before'
        observations['toolchainBefore'] = ops.toolchain()
        roles['toolchain.before.json'] = canonical(observations['toolchainBefore'])
        selected = {name: request['toolchain'][name] for name in ('files', 'aliases', 'directoryAliases')}
        match_expected_graph(observations['toolchainBefore'], selected)
        need(node_expectation(observations['nodeStage']) == request['toolchain']['node'],
             'current staged Node equals independent inventory selection')
        phase = 'current-runtime-structural-metadata'
        structural = admit_runtime_elf_metadata(ops.elf_metadata(observations['toolchainBefore']),
            observations['toolchainBefore'], observations['nodeStage'])
        roles['runtime-elf-ranges.original.json'] = canonical(structural)
        observations['runtimeElfMetadata'] = bytes_ref('runtime-elf-ranges.original.json',
            roles['runtime-elf-ranges.original.json'])
        phase = 'readonly-current-host-runtime'
        staged = ops.host_runtime_stage(observations['toolchainBefore'], structural)
        observations['hostRuntime'] = {'stageBytes': len(canonical(staged)),
                                     'stageSha256': sha256(canonical(staged))}
        roles['host-runtime.original.json'] = canonical({'schema': 'bw.bochs-ring3.host-runtime-original.v1',
                                                         'stage': staged, 'cleanup': None})
        phase = 'source-payload-acquisition'
        upstream = ops.upstream(request['bochs'])
        observations['sourceSelection'] = selected_source_rows(upstream['tree'])
        observations['upstream'] = upstream['before']
        observations['correspondingSource'] = upstream['correspondingSource']
        roles['upstream.tree.original.json'] = canonical(upstream['tree'])
        roles['source-selection.original.json'] = canonical(observations['sourceSelection'])
        roles['upstream.before.json'] = canonical(upstream['before'])
        roles['source-selected.original.tar.gz'] = upstream['sourceArchive']
        roles['notices/vgabios-corresponding-source.tar.gz'] = upstream['correspondingSourceRaw']
        need(len(upstream['correspondingSourceRaw']) == VGA_SOURCE_BYTES and
             sha256(upstream['correspondingSourceRaw']) == VGA_SOURCE_SHA256,
             'exact complete corresponding source original')
        phase = 'configure'
        value['authority']['compilerExecuted'] = None
        process, streams, _stop = run_phase(ops, value, roles, 'configure', CONFIGURE_ARGV,
                                           wall_seconds=900)
        config_raw, version_raw = ops.generated_headers()
        observations['configure'] = configure_facts(config_raw, version_raw)
        observations['configHeader'] = bytes_ref('config.h.original', config_raw)
        roles['config.h.original'], roles['bxversion.h.original'] = config_raw, version_raw
        phase = 'make'
        _process, streams, _stop = run_phase(ops, value, roles, 'make', MAKE_ARGV, wall_seconds=900)
        commands = [line for line in streams['stdout'].decode('utf-8').splitlines()
                    if TOOL_PATHS['gcc'] in line or TOOL_PATHS['g++'] in line]
        need(1 <= len(commands) <= 8192 and all(len(line) <= 8192 for line in commands),
             'bounded retained actual compiler commands')
        need(len(canonical(commands)) <= 1048576, 'compiler command summary budget within original cap')
        observations['compilerCommands'] = commands
        phase = 'static-build-assets'
        assembled = ops.runtime_bundle(request, upstream)
        runtime_files = assembled['files']
        need('asset-manifest.json' in runtime_files and 'bin/bochs' in runtime_files,
             'closed retained runtime assets')
        binary = runtime_files['bin/bochs']
        binary_facts = {key: item for key, item in sparse_elf(binary)['structure'].items() if key != 'soname'}
        need(binary_facts['rpath'] is None and binary_facts['runpath'] is None,
             'built Bochs has no RPATH/RUNPATH')
        observations['binary'] = {**bytes_ref('bin/bochs', binary), 'elf': binary_facts}
        value['authority']['compilerExecuted'] = True
        runtime_raw = pack_zip(runtime_files, archive_cap=33554432, expanded_cap=67108864,
                               member_cap=256, modes=assembled['modes'])
        roles['runtime.original.zip'] = runtime_raw
        observations['runtimeManifest'] = raw_object(runtime_files['asset-manifest.json'], 4194304)
        observations['notices'] = assembled['notices']
        need(observations['runtimeManifest']['schema'] == 'bw.bochs-ring3.runtime-assets.v2' and
             not any(name.startswith('lib/') for name in runtime_files),
             'current asset-v2, no distributed host library body')
        phase = 'current-host-runtime-after'
        staged = ops.host_runtime_after()
        observations['hostRuntime'] = {'stageBytes': len(canonical(staged)),
                                      'stageSha256': sha256(canonical(staged))}
        roles['host-runtime.original.json'] = canonical({'schema': 'bw.bochs-ring3.host-runtime-original.v1',
                                                         'stage': staged, 'cleanup': None})
        phase = 'upstream-source-after'
        after = ops.upstream_after()
        roles['upstream.after.json'] = canonical(after)
        need(after == upstream['before'], 'selected upstream complete source before/after equality')
        phase = 'build-toolchain-after'
        observations['toolchainAfter'] = ops.toolchain()
        roles['toolchain.after.json'] = canonical(observations['toolchainAfter'])
        match_expected_graph(observations['toolchainAfter'], selected)
        need(observations['toolchainBefore'] == observations['toolchainAfter'],
             'held local tool graph before/after full identity')
        observations['nodeStage'] = ops.node_after(full_hash=True)
        check_node_stage(observations['nodeStage'], 'build', env, after=True)
        roles['node-stage.original.json'] = canonical(observations['nodeStage'])
        manifest = {'schema': 'bw.bochs-ring3.build-manifest.v1', 'source': request['source'],
            'bochsSource': upstream['before'],
            'sourceInventory': {'selection': observations['sourceSelection'],
                'before': upstream['before'], 'after': after,
                'archive': bytes_ref('source-selected.original.tar.gz', upstream['sourceArchive'])},
            'toolchainInventory': {'selected': request['toolchain'],
                'before': observations['toolchainBefore'], 'after': observations['toolchainAfter']},
            'configure': {'argv': CONFIGURE_ARGV, 'makeArgv': MAKE_ARGV,
                'facts': observations['configure'],
                'versionHeader': bytes_ref('bxversion.h.original', version_raw)},
            'configHeader': observations['configHeader'],
            'compilerCommands': commands, 'elf': binary_facts,
            'runtimeMembers': runtime_rows(runtime_files, assembled['modes']),
            'notices': assembled['notices'], 'sourceAfter': None,
            'firstFailure': None, 'secondary': [],
            'buildCompleted': True, 'guestExecuted': False}
    except BaseException as exc:
        original_error(value, exc, phase)
    finally:
        if value['sourceBefore'] is not None:
            try:
                value['sourceAfter'] = ops.source(request['source'], env)
                roles['source.after.json'] = canonical(value['sourceAfter'])
                need(value['sourceBefore'] == value['sourceAfter'], 'Build source before/after equality')
            except BaseException as exc:
                original_error(value, exc, 'source-after')
        if value['resources'] is not None:
            try:
                value['resources']['after'] = ops.resources('build')
            except BaseException as exc:
                original_error(value, exc, 'resource-after')
        close_provider(ops, value, roles)
    value['complete'] = value['firstFailure'] is None and not value['secondary']
    if value['complete']:
        try:
            manifest['sourceAfter'] = value['sourceAfter']
            manifest_raw = canonical(manifest)
            need(len(manifest_raw) <= 4194304, 'bounded full build manifest')
            roles['build-manifest.json'] = manifest_raw
            observations['compactManifest'] = compact_build_manifest(request, manifest_raw, runtime_raw, manifest)
            roles['compact-manifest.json'] = canonical(observations['compactManifest'])
        except BaseException as exc:
            original_error(value, exc, 'build-manifest')
            value['complete'] = False
    roles['build.original.json'] = canonical(value)
    roles['manifest.json'] = canonical(original_manifest(roles))
    return value, roles


def reference_js_driver(source_root, runtime_root):
    """Source-authored driver: generate/compare inputs, then run the real CPU."""
    source_root, runtime_root = Path(source_root), Path(runtime_root)
    need(source_root.is_absolute() and runtime_root.is_absolute(), 'absolute admitted driver paths')
    prefix = ('const sourceRoot = ' + json.dumps(str(source_root)) + ';\n' +
              'const runtimeRoot = ' + json.dumps(str(runtime_root)) + ';\n')
    body = r'''
import fs from 'node:fs/promises';
import path from 'node:path';
import {pathToFileURL} from 'node:url';
const require = (value, message) => { if (!value) throw Error(message); };
const stable = value => {
  if (Array.isArray(value)) return value.map(stable);
  if (value !== null && typeof value === 'object') return Object.fromEntries(
    Object.keys(value).sort().map(key => [key, stable(value[key])]));
  return value;
};
const canonical = value => Buffer.from(JSON.stringify(stable(value)) + '\n', 'utf8');
const {buildFixture} = await import(pathToFileURL(path.join(sourceRoot,
  'scripts/i80386-ring3-int-iret/fixture.mjs')).href);
const {executeFixture} = await import(pathToFileURL(path.join(sourceRoot,
  'scripts/i80386-ring3-int-iret/probe.mjs')).href);
const fixture = buildFixture();
const rom = await fs.readFile(path.join(runtimeRoot, 'inputs/fixture.rom'));
const manifest = await fs.readFile(path.join(runtimeRoot, 'inputs/fixture.json'));
require(Buffer.from(fixture.rom).equals(rom), 'fresh generated authored ROM equals selected input');
require(canonical(fixture.manifest).equals(manifest), 'fresh generated fixture manifest equals selected input');
const result = await executeFixture({fixture});
for (const [name, bytes] of [
  ['report.json', canonical(result.report)],
  ['observations.json', canonical(result.observations)],
  ['writes.json', canonical(result.writes)],
  ['memory.before.bin', result.memoryBefore],
  ['memory.after.bin', result.memoryAfter]
]) await fs.writeFile(path.join(runtimeRoot, 'outputs', name), bytes, {flag: 'wx', mode: 0o600});
await new Promise((resolve, reject) => process.stdout.write(Buffer.from(result.stdout),
  error => error ? reject(error) : resolve()));
if (!result.report.finiteRoundTripPass) process.exitCode = 1;
'''
    raw = (prefix + body).encode('utf-8')
    need(len(raw) <= 16384, 'bounded source-authored JS driver')
    return raw


def admit_reference_inputs(request):
    selected = request['build']
    closed(selected, ('runId', 'jobId', 'artifactId', 'name', 'bytes', 'sha256',
        'checkoutHead', 'checkoutTree', 'workflowCommit', 'workflowFileSha256',
        'compactManifest', 'buildLog'), 'closed independently selected Build input')
    need(type(selected['runId']) is str and re.fullmatch(r'[1-9][0-9]{0,19}', selected['runId']),
         'exact selected Build run')
    for name in ('jobId', 'artifactId'):
        integer(selected[name], 1, 2 ** 63 - 1, 'selected positive Build ID')
    integer(selected['bytes'], 1, LIMITS['build']['archiveBytes'], 'selected bounded Build archive')
    need(selected['name'] == 'i80386-bochs-ring3-build-v1-originals' and
         HEX.fullmatch(selected['sha256']) and GIT_HEX.fullmatch(selected['workflowCommit']) and
         HEX.fullmatch(selected['workflowFileSha256']) and
         selected['checkoutHead'] == request['source']['head'] and
         selected['checkoutTree'] == request['source']['tree'] and
         selected['workflowFileSha256'] == request['source']['files'][WORKFLOW]['sha256'],
         'same-source selected Build artifact and executing workflow bytes')
    closed(selected['buildLog'], ('bytes', 'sha256'), 'external once-acquired Build log binding')
    integer(selected['buildLog']['bytes'], 1, 8 * 1024 * 1024, 'bounded external Build log')
    need(HEX.fullmatch(selected['buildLog']['sha256']), 'external exact Build log SHA')
    compact = selected['compactManifest']
    closed(compact, ('schema', 'sourceHead', 'sourceTree', 'sourceFilesSha256',
        'bochsCommit', 'bochsTree', 'policySha256', 'fullManifest', 'runtimeZip',
        'binary', 'configHeader', 'runtimeMembersSha256', 'noticesSha256',
        'buildCompleted', 'guestExecuted'), 'closed selected compact Build manifest')
    need(compact['schema'] == 'bw.bochs-ring3.build-manifest-compact.v1' and
         compact['sourceHead'] == request['source']['head'] and compact['sourceTree'] == request['source']['tree'] and
         compact['sourceFilesSha256'] == sha256(canonical(request['source']['files'])) and
         compact['bochsCommit'] == UPSTREAM_COMMIT and compact['bochsTree'] == UPSTREAM_TREE and
         compact['buildCompleted'] is True and compact['guestExecuted'] is False and
         all(HEX.fullmatch(compact[key]) for key in ('policySha256', 'runtimeMembersSha256', 'noticesSha256')),
         'source-fixed externally admitted Build compact facts')
    for key, cap in (('fullManifest', 4194304), ('runtimeZip', 33554432),
                     ('binary', 33554432), ('configHeader', 1048576)):
        closed(compact[key], ('bytes', 'sha256'), 'closed compact byte reference')
        integer(compact[key]['bytes'], 1, cap, 'bounded compact reference extent')
        need(HEX.fullmatch(compact[key]['sha256']), 'compact reference hash')
    return selected


def selected_build_bytes(request, raw):
    """Recheck the sole acquired byte copy; official authentication stays external."""
    selected = admit_reference_inputs(request)
    need(type(raw) is bytes and len(raw) == selected['bytes'] and sha256(raw) == selected['sha256'],
         'sole selected Build archive exact bytes')
    files = unpack_zip(raw, archive_cap=67108864, expanded_cap=268435456, member_cap=4096)
    required = set(('request.original.json event.original.json source.before.json source.after.json '
        'node-stage.original.json upstream.tree.original.json source-selection.original.json '
        'upstream.before.json upstream.after.json toolchain.before.json toolchain.after.json '
        'build.original.json build-manifest.json compact-manifest.json runtime.original.zip '
        'source-selected.original.tar.gz config.h.original bxversion.h.original configure.stdout '
        'configure.stderr configure.process.json make.stdout make.stderr make.process.json '
        'notices/vgabios-corresponding-source.tar.gz manifest.json outside.original.json '
        'service-status.original.json cleanup.original.json runtime-elf-ranges.original.json '
        'host-runtime.original.json').split())
    need(set(files) == required, 'complete closed31-role Build original')
    need(raw_object(files['manifest.json'], 4194304) == original_manifest(
        {name: body for name, body in files.items() if name != 'manifest.json'}), 'complete nested Build delivery manifest')
    compact = raw_object(files['compact-manifest.json'], 16384)
    need(compact == selected['compactManifest'], 'retained compact equals pre-download selected log manifest')
    for key, name in (('fullManifest', 'build-manifest.json'), ('runtimeZip', 'runtime.original.zip'),
                      ('configHeader', 'config.h.original')):
        need(compact[key] == {'bytes': len(files[name]), 'sha256': sha256(files[name])},
             'nested compact reference actual bytes')
    build_request = request_object(files['request.original.json'])
    need(build_request['schema'] == 'bw.bochs-ring3.build-request.v1' and
         build_request['repository'] == REPOSITORY and build_request['pullRequest'] == request['pullRequest'] and
         build_request['policySha256'] == compact['policySha256'] and
         build_request['source'] == request['source'], 'Build and Reference same PR, policy and exact source12 graph')
    admit_build_inputs(build_request)
    inner = raw_object(files['build.original.json'], 4194304)
    outside = raw_object(files['outside.original.json'], 16384)
    before = raw_object(files['source.before.json'], 1048576)
    after = raw_object(files['source.after.json'], 1048576)
    closed(before, ('head', 'tree', 'files', 'workflowCommit', 'workflowTree', 'workflowFileSha256'),
           'closed retained actual Build source observation')
    need(before == after == inner['sourceBefore'] == inner['sourceAfter'] and
         {key: before[key] for key in ('head', 'tree', 'files')} == request['source'] and
         before['workflowCommit'] == selected['workflowCommit'] and
         before['workflowFileSha256'] == selected['workflowFileSha256'] and
         GIT_HEX.fullmatch(before['workflowTree']), 'actual Build H and frozen executing W/source byte join')
    need(inner['schema'] == 'bw.bochs-ring3.build-original.v1' and inner['complete'] is True and
         inner['firstFailure'] is None and not inner['secondary'] and
         inner['requestSha256'] == sha256(files['request.original.json']) and
         inner['eventSha256'] == sha256(files['event.original.json']) and
         inner['authority'] == {'compilerExecuted': True, 'guestExecuted': False,
             'actualRunApproved': False, 'guestApproved': False, 'wholeHostAttested': False, 'physicalTimingProved': False} and
         outside['serviceExitCode'] == outside['clientExitCode'] == outside['cleanupExitCode'] == 0 and
         outside['firstFailure'] is None and not outside['secondary'] and outside['innerComplete'] is True and
         outside['innerFirstFailure'] is None and outside['after']['exists'] is False and
         outside['after']['errno'] == 2, 'complete actual Build and terminal cleanup originals')
    manifest = raw_object(files['build-manifest.json'], 4194304)
    need(manifest['source'] == request['source'] and manifest['buildCompleted'] is True and
         manifest['guestExecuted'] is False and manifest['firstFailure'] is None and not manifest['secondary'] and
         sha256(canonical(manifest['runtimeMembers'])) == compact['runtimeMembersSha256'] and
         sha256(canonical(manifest['notices'])) == compact['noticesSha256'], 'selected full Build manifest facts')
    runtime = unpack_zip(files['runtime.original.zip'], archive_cap=33554432,
                         expanded_cap=67108864, member_cap=256)
    with zipfile.ZipFile(io.BytesIO(files['runtime.original.zip'])) as archive:
        modes = {item.filename: item.external_attr >> 16 for item in archive.infolist()}
    need(manifest['runtimeMembers'] == runtime_rows(runtime,
         {name: stat.S_IMODE(mode) for name, mode in modes.items()}), 'every exact runtime member/mode/hash')
    asset = raw_object(runtime['asset-manifest.json'], 4194304)
    closed(asset, ('schema', 'source', 'bochsSource', 'hostNode', 'hostRuntime', 'files'), 'current asset-v2 keys')
    need(asset['schema'] == 'bw.bochs-ring3.runtime-assets.v2' and
         not any(name.startswith('lib/') for name in runtime) and
         asset['source'] == {'head': request['source']['head'], 'tree': request['source']['tree'],
            'filesSha256': sha256(canonical(request['source']['files']))} and
         asset['hostNode'] == build_request['toolchain']['node'] and
         asset['files'] == [row for row in manifest['runtimeMembers'] if row['path'] != 'asset-manifest.json'],
         'selected runtime distribution graph, no library bodies')
    need(compact['binary'] == {'bytes': len(runtime['bin/bochs']), 'sha256': sha256(runtime['bin/bochs'])},
         'selected compiled binary exact bytes')
    rom, fixture = authored_inputs()
    need(runtime['inputs/fixture.rom'] == rom and runtime['inputs/fixture.json'] == fixture and
         runtime['config/bochsrc.template'] == BOCHSRC_TEMPLATE and
         len(runtime['resources/vgabios.bin']) == VGA_BYTES and sha256(runtime['resources/vgabios.bin']) == VGA_SHA256,
         'unchanged authored inputs, config and selected VGA resource')
    expanded = sum(map(len, files.values())) + sum(map(len, runtime.values()))
    need(len(raw) + expanded + 16 * 1024 * 1024 <= LIMITS['reference']['expandedBytes'],
         'cumulative nested Build/runtime plus bounded Reference-original reservation')
    return {'files': files, 'runtime': runtime, 'modes': modes, 'manifest': manifest,
            'asset': asset, 'request': build_request, 'nestedExpandedBytes': expanded}


def compare_reference_frames(js_frame, frame, fixture):
    """Compare fixed reporter bytes with the original selector-padding rule."""
    padding, frame_offsets, offset = set(), {}, len(WIRE_MAGIC)
    for row in fixture['ranges']:
        for address in (0x70c0, 0x7fec, 0x9fec):
            if row['address'] <= address and address + 20 <= row['address'] + row['bytes']:
                frame_offsets[address] = offset + address - row['address']
                padding.update(offset + address - row['address'] + index for index in (6, 7, 18, 19))
        offset += row['bytes']
    need(set(frame_offsets) == {0x70c0, 0x7fec, 0x9fec} and
         frame[frame_offsets[0x70c0]:frame_offsets[0x70c0] + 20] ==
         frame[frame_offsets[0x7fec]:frame_offsets[0x7fec] + 20],
         'all twenty original Bochs frame-copy bytes, including selector padding')
    need(len(js_frame) == len(frame) == WIRE_BYTES and
         all(a == b for index, (a, b) in enumerate(zip(frame, js_frame)) if index not in padding),
         'all unchanged defined JS/Bochs reporter bytes, only historical selector padding excluded')
    return len(padding)


def collect_reference(request_raw, event_raw, env, ops):
    request = admitted_request('reference', request_raw, event_raw, env)
    admit_reference_inputs(request)
    value = original('reference', request_raw, event_raw)
    observations = {name: None for name in ('build', 'assetsBefore', 'assetsAfter', 'fixture',
        'config', 'js', 'bochs', 'stop', 'outside', 'cleanup', 'nodeStage', 'runtimeElfMetadata', 'hostRuntime')}
    value['observations'] = observations
    roles = {'request.original.json': request_raw, 'event.original.json': event_raw}
    phase = 'source-before'
    try:
        value['sourceBefore'] = ops.source(request['source'], env)
        roles['source.before.json'] = canonical(value['sourceBefore'])
        value['resources'] = {'before': ops.resources('reference'), 'after': None}
        phase = 'sole-selected-build-intake'
        try:
            archive, official = ops.acquire_build(request['build'], pull_request=request['pullRequest'])
        except BaseException:
            observations['build'] = getattr(ops, 'build_intake_partial', None)
            raise
        roles['inputs/build.original.zip'] = archive
        observations['build'] = official
        built = selected_build_bytes(request, archive)
        phase = 'node-cache-data-staging'
        observations['nodeStage'] = ops.node_stage()
        check_node_stage(observations['nodeStage'], 'reference', env)
        need(node_expectation(observations['nodeStage']) == built['asset']['hostNode'], 'same selected current staged Node')
        phase = 'current-host-runtime'
        graph = ops.toolchain()
        match_expected_graph(graph, {key: built['request']['toolchain'][key]
                                    for key in ('files', 'aliases', 'directoryAliases')})
        structural = admit_runtime_elf_metadata(ops.elf_metadata(graph), graph, observations['nodeStage'])
        roles['runtime-elf-ranges.original.json'] = canonical(structural)
        observations['runtimeElfMetadata'] = bytes_ref('runtime-elf-ranges.original.json', roles['runtime-elf-ranges.original.json'])
        need(host_runtime_selection(expected_graph(graph), structural, built['manifest']['elf'],
              observations['nodeStage']['elf']) == built['asset']['hostRuntime'], 'same source-selected runtime closure')
        stage = ops.host_runtime_stage(graph, structural)
        observations['hostRuntime'] = {'stageBytes': len(canonical(stage)), 'stageSha256': sha256(canonical(stage))}
        phase = 'owned-runtime-preparation'
        config = ops.prepare_reference(built)
        observations['config'] = bytes_ref('bochsrc.original', config)
        roles['bochsrc.original'] = config
        for name in ('inputs/fixture.rom', 'inputs/fixture.json'):
            roles[name] = built['runtime'][name]
        observations['fixture'] = {'rom': bytes_ref('inputs/fixture.rom', roles['inputs/fixture.rom']),
            'manifest': bytes_ref('inputs/fixture.json', roles['inputs/fixture.json'])}
        observations['assetsBefore'] = ops.runtime_after(built)
        roles['asset.before.json'] = canonical(observations['assetsBefore'])
        phase = 'fresh-js'
        value['authority']['guestExecuted'] = None
        js_process, js_streams, _stop = ops.process('js', ops.reference_argv('js'),
            wall_seconds=60, stream_cap=131072, checkpoint=False)
        value['phases'].append(js_process)
        roles.update({'js/stdout': js_streams['stdout'], 'js/stderr': js_streams['stderr'],
                      'js/process.json': canonical(js_process)})
        if js_process['firstFailure'] is not None:
            exc = Refusal(js_process['firstFailure']['message'])
            exc.bochs_first, exc.bochs_secondary = js_process['firstFailure'], js_process['secondary']
            raise exc
        need(js_process['firstFailure'] is None and not js_process['secondary'] and js_process['reaped'] and
             js_process['exitCode'] == 0 and js_process['signal'] is None and not js_process['timedOut'],
             'fresh JS complete retained child')
        js = ops.js_outputs()
        roles.update(js)
        report = raw_object(js['js/report.json'], 131072)
        need(report['schema'] == 'bw.ring3.js-probe.v1' and report['finiteRoundTripPass'] is True and
             report['firstFailure'] is None and report['completed'] is True and
             report['fixtureSha256'] == ROM_SHA256 and report['outputSha256'] == sha256(js_streams['stdout']) and
             report['memoryBeforeSha256'] == sha256(js['js/memory.before.bin']) and
             report['memoryAfterSha256'] == sha256(js['js/memory.after.bin']), 'genuine fresh JS probe completion')
        observations['js'] = report
        value['authority']['guestExecuted'] = True
        phase = 'fresh-bochs'
        process, streams, stop = ops.process('bochs', ops.reference_argv('bochs'),
            wall_seconds=60, stream_cap=131072, checkpoint=True)
        value['phases'].append(process)
        roles.update({'bochs/stdout': streams['stdout'], 'bochs/stderr': streams['stderr'],
                      'bochs/process.json': canonical(process)})
        observations['stop'] = stop
        if process['firstFailure'] is not None:
            exc = Refusal(process['firstFailure']['message'])
            exc.bochs_first, exc.bochs_secondary = process['firstFailure'], process['secondary']
            raise exc
        need(process['firstFailure'] is None and not process['secondary'] and process['reaped'] and
             process['signal'] == 15 and process['exitCode'] is None and not process['timedOut'] and
             stop is not None and stop['sent'] is True and stop['signal'] == 15 and
             stop['pid'] == process['pid'] and stop['firstFailure'] is None and not stop['secondary'],
             'complete frame followed by actual owned SIGTERM15 and reap')
        frame = reporter_frame(streams['stdout'])
        roles['bochs/frame.original'] = frame
        roles['bochs/log'] = ops.bochs_log()
        output_census = ops.reference_output_census()
        need(stop['frameSha256'] == sha256(frame), 'actual captured checkpoint frame hash')
        fixture = raw_object(roles['inputs/fixture.json'], 1048576)
        padding_bytes = compare_reference_frames(js_streams['stdout'], frame, fixture)
        observations['bochs'] = {'stdout': bytes_ref('bochs/stdout', streams['stdout']),
            'frame': bytes_ref('bochs/frame.original', frame), 'log': bytes_ref('bochs/log', roles['bochs/log']),
            'definedBytesEqual': True, 'selectorPaddingBytes': padding_bytes, 'outputCensus': output_census}
        phase = 'all-assets-after'
        observations['assetsAfter'] = ops.runtime_after(built)
        roles['asset.after.json'] = canonical(observations['assetsAfter'])
        need(observations['assetsBefore'] == observations['assetsAfter'], 'all retained input asset before/after equality')
        stage = ops.host_runtime_after()
        observations['hostRuntime'] = {'stageBytes': len(canonical(stage)), 'stageSha256': sha256(canonical(stage))}
        roles['host-runtime.original.json'] = canonical({'schema': 'bw.bochs-ring3.host-runtime-original.v1', 'stage': stage, 'cleanup': None})
        observations['nodeStage'] = ops.node_after(full_hash=True)
        check_node_stage(observations['nodeStage'], 'reference', env, after=True)
    except BaseException as exc:
        original_error(value, exc, phase)
        # A failed but reaped child may already have written bounded diagnostic
        # originals. Retain those exact files without another child or intake.
        if phase == 'fresh-js' and value['phases'] and value['phases'][-1].get('reaped') is True:
            try:
                if not getattr(ops, 'js_output_attempted', False) and 'js/report.json' not in roles:
                    roles.update(ops.js_outputs())
            except BaseException as output_error:
                original_error(value, output_error, 'js-failed-output-retention')
            roles.update(getattr(ops, 'js_output_partial', {}))
        if phase == 'fresh-bochs' and value['phases'] and value['phases'][-1].get('reaped') is True:
            try:
                if not getattr(ops, 'bochs_log_attempted', False) and 'bochs/log' not in roles:
                    roles['bochs/log'] = ops.bochs_log()
            except BaseException as output_error:
                original_error(value, output_error, 'bochs-failed-log-retention')
    finally:
        if value['sourceBefore'] is not None:
            try:
                value['sourceAfter'] = ops.source(request['source'], env)
                roles['source.after.json'] = canonical(value['sourceAfter'])
                need(value['sourceBefore'] == value['sourceAfter'], 'Reference source before/after equality')
            except BaseException as exc:
                original_error(value, exc, 'source-after')
        if value['resources'] is not None:
            try:
                value['resources']['after'] = ops.resources('reference')
            except BaseException as exc:
                original_error(value, exc, 'resource-after')
        close_provider(ops, value, roles)
        if observations['nodeStage'] is not None:
            roles['node-stage.original.json'] = canonical(observations['nodeStage'])
    value['complete'] = value['firstFailure'] is None and not value['secondary']
    roles['resources.json'] = canonical(value['resources'])
    if value['complete']:
        try:
            # Cumulative decompression is a single budget, including retained
            # nested archives and every current Reference role/envelope.
            need(sum(map(len, roles.values())) + len(canonical(value)) +
                 len(canonical(original_manifest(roles))) + built['nestedExpandedBytes']
                 <= LIMITS['reference']['expandedBytes'], 'whole cumulative Reference/Build/runtime wire cap')
        except BaseException as exc:
            original_error(value, exc, 'reference-whole-wire')
            value['complete'] = False
    roles['original.json'] = canonical(value)
    roles['manifest.json'] = canonical(original_manifest(roles))
    return value, roles


def dispatch(route, request_raw, event_raw, env, ops_factory, *, current=False):
    need(route in ROUTES, 'known source-owned route')
    enabled = {'toolchain-v2': TOOLCHAIN_V2_ENABLED, 'toolchain': TOOLCHAIN_ENABLED, 'build': BUILD_ENABLED,
               'reference': REFERENCE_ENABLED}[route]
    if current and route in ('build','reference'):
        enabled={'build':BUILD_CURRENT_V2_ENABLED,'reference':REFERENCE_CURRENT_V2_ENABLED}[route]
    need(enabled is True, 'Bochs source route inactive; no host factory or input execution')
    request = selected_request(route, request_raw, event_raw, env, current=current)
    if route == 'build':
        (admit_build_inputs_v2 if current else admit_build_inputs)(request)
    ops = ops_factory(request, env)
    if route == 'toolchain-v2':
        return collect_toolchain_v2(request_raw, event_raw, env, ops)
    if route == 'toolchain':
        return collect_toolchain(request_raw, event_raw, env, ops)
    if route == 'build':
        return (collect_build_v2 if current else collect_build)(request_raw, event_raw, env, ops)
    return (collect_reference_v2 if current else collect_reference)(request_raw, event_raw, env, ops)


class ChildKernel:
    """Fixed root-owned unit/child leaf and bounded raw process observations."""

    def __init__(self, unit_path, work_root):
        self.unit = Path(unit_path)
        self.work = Path(work_root)
        self.proc_owner = None
        self.proc_group = None
        self.secondary = []
        self.delegation = None
        self.controller_pid = None
        self.partial = None

    def _close(self, fd, primary):
        try:
            os.close(fd)
        except BaseException as exc:
            if primary is None:
                raise
            item = failure(exc, 'child-edge-close')
            if len(self.secondary) < SECONDARY_LIMIT:
                self.secondary.append(item)
            extras = list(getattr(primary, 'bochs_secondary', []))
            if len(extras) < SECONDARY_LIMIT:
                extras.append(item)
                primary.bochs_secondary = extras

    @staticmethod
    def _first_five(row):
        return tuple(row[key] for key in ('dev', 'ino', 'mode', 'uid', 'gid'))

    @staticmethod
    def _directory(path):
        row = identity(os.lstat(path))
        need(stat.S_ISDIR(row['mode']) and row['uid'] == row['gid'] == 0 and
             row['mode'] & 0o022 == 0, 'root-owned nonwritable child cgroup directory')
        return row

    def _read(self, path, cap, *, owner=0, group=0, owner_pairs=None, observe=False):
        if self.partial is not None:
            self.partial['lastPath'] = os.fspath(path)
        fd = os.open(path, os.O_RDONLY | os.O_CLOEXEC | os.O_NOFOLLOW | os.O_NONBLOCK)
        primary = None
        try:
            before = identity(os.fstat(fd))
            named = identity(os.lstat(path))
            allowed = {(owner, group)} if owner_pairs is None else owner_pairs
            need(stat.S_ISREG(before['mode']) and
                 (before['uid'], before['gid']) in allowed and
                 (named['uid'], named['gid']) in allowed and
                 before['mode'] & 0o022 == 0 and
                 self._first_five(before) == self._first_five(named),
                 'owned held/named child pseudo-file')
            raw = bytearray()
            while True:
                part = os.read(fd, min(4096, cap + 1 - len(raw)))
                if not part:
                    break
                raw.extend(part)
                need(len(raw) <= cap, 'bounded raw child resource text')
            after = identity(os.fstat(fd))
            named_after = identity(os.lstat(path))
            need(self._first_five(before) == self._first_five(after) ==
                 self._first_five(named_after), 'stable held/named child pseudo-file')
            content = bytes(raw).decode('ascii')
            if observe:
                return content, {'before': before, 'after': after, 'named': named_after}
            return content
        except BaseException as exc:
            primary = exc
            raise
        finally:
            self._close(fd, primary)

    def _write(self, path, value):
        fd = os.open(path, os.O_WRONLY | os.O_CLOEXEC | os.O_NOFOLLOW)
        primary = None
        try:
            before = identity(os.fstat(fd))
            named = identity(os.lstat(path))
            need(stat.S_ISREG(before['mode']) and before['uid'] == named['uid'] == 0 and
                 before['gid'] == named['gid'] == 0 and before['mode'] & 0o022 == 0 and
                 self._first_five(before) == self._first_five(named),
                 'owned held/named child limit file')
            raw = value.encode('ascii')
            need(os.write(fd, raw) == len(raw), 'complete child cgroup limit write')
            need(self._first_five(identity(os.fstat(fd))) == self._first_five(before) ==
                 self._first_five(identity(os.lstat(path))),
                 'stable held/named child limit file')
        except BaseException as exc:
            primary = exc
            raise
        finally:
            self._close(fd, primary)

    def create_leaf(self, name, limits):
        need(self.delegation is not None, 'delegated parent controllers precede child leaf')
        unit_before = self._directory(self.unit)
        leaf = self.unit / name
        os.mkdir(leaf, 0o755)
        # The service may carry umask 077; make the selected leaf mode exact.
        leaf_fd = os.open(leaf, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC)
        primary = None
        try:
            os.fchmod(leaf_fd, 0o755)
        except BaseException as exc:
            primary = exc
            raise
        finally:
            self._close(leaf_fd, primary)
        child_before = self._directory(leaf)
        need(child_before['mode'] & 0o777 == 0o755, 'exact child leaf mode')
        for key, value in limits.items():
            self._write(leaf / key, value)
            need(self._read(leaf / key, 4096) == value,
                 'exact child resource-limit readback')
        need(self._first_five(self._directory(self.unit)) == self._first_five(unit_before),
             'held unit identity after child leaf creation')
        need(self._first_five(self._directory(leaf)) == self._first_five(child_before),
             'held child leaf identity after limit writes')
        return leaf, unit_before, child_before

    @staticmethod
    def _controllers(raw):
        names = raw.split()
        need(len(names) == len(set(names)) and
             all(name.isascii() and name.isalpha() and name.islower() for name in names),
             'closed unique controller names')
        return set(names)

    def prepare_delegation(self, pid):
        """Empty unit inner node; fixed controller sibling receives root service."""
        integer(pid, 1, 1 << 30, 'owned root service PID')
        need(self.delegation is None, 'controller enable once per source service')
        controller = self.unit / 'controller'
        unit_identity = self._directory(self.unit)
        controller_identity = self._directory(controller)
        unit_procs = self._read(self.unit / 'cgroup.procs', 4096)
        control_procs = self._read(controller / 'cgroup.procs', 4096)
        need(unit_procs == '' and control_procs == str(pid) + '\n',
             'unit empty and fixed controller contains only root service PID')
        raw_cgroup = self._read(Path('/proc') / str(pid) / 'cgroup', 16384, owner=0)
        relative = controller.relative_to(Path('/sys/fs/cgroup'))
        need(raw_cgroup == '0::/' + relative.as_posix() + '\n',
             'root service is in fixed controller subgroup')
        available_before = self._read(self.unit / 'cgroup.controllers', 4096)
        enabled_before = self._read(self.unit / 'cgroup.subtree_control', 4096)
        available = self._controllers(available_before)
        enabled = self._controllers(enabled_before)
        required = {'cpu', 'memory', 'pids'}
        need(required <= available and enabled <= available,
             'required delegated domain controllers available')
        missing = sorted(required - enabled)
        command = ''.join('+' + name + ' ' for name in missing).rstrip()
        if command:
            command += '\n'
            self._write(self.unit / 'cgroup.subtree_control', command)
        available_after = self._read(self.unit / 'cgroup.controllers', 4096)
        enabled_after = self._read(self.unit / 'cgroup.subtree_control', 4096)
        need(available_after == available_before and
             self._controllers(enabled_after) == enabled | required and
             self._first_five(self._directory(self.unit)) == self._first_five(unit_identity) and
             self._first_five(self._directory(controller)) == self._first_five(controller_identity),
             'exact delegated controller readback and stable authority')
        self.controller_pid = pid
        self.delegation = {'unitPath': os.fspath(self.unit),
            'unitIdentity': unit_identity, 'controllerPath': os.fspath(controller),
            'controllerIdentity': controller_identity, 'unitProcs': unit_procs,
            'controllerProcs': control_procs, 'availableBefore': available_before,
            'enabledBefore': enabled_before, 'write': command,
            'availableAfter': available_after, 'enabledAfter': enabled_after}
        return self.delegation

    def parent_control(self):
        need(self.delegation is not None and self.controller_pid is not None,
             'selected delegated parent admitted')
        initial = self.delegation
        controller = self.unit / 'controller'
        current = dict(initial)
        current.update(unitIdentity=self._directory(self.unit),
                       controllerIdentity=self._directory(controller),
                       unitProcs=self._read(self.unit / 'cgroup.procs', 4096),
                       controllerProcs=self._read(controller / 'cgroup.procs', 4096),
                       availableAfter=self._read(self.unit / 'cgroup.controllers', 4096),
                       enabledAfter=self._read(self.unit / 'cgroup.subtree_control', 4096))
        need(self._first_five(current['unitIdentity']) ==
             self._first_five(initial['unitIdentity']) and
             self._first_five(current['controllerIdentity']) ==
             self._first_five(initial['controllerIdentity']) and
             current['unitProcs'] == '' and
             current['controllerProcs'] == str(self.controller_pid) + '\n' and
             current['availableAfter'] == initial['availableAfter'] and
             current['enabledAfter'] == initial['enabledAfter'],
             'live delegated parent/controller readback')
        return current

    @staticmethod
    def _pids(raw, limit):
        lines = raw.splitlines()
        need(1 <= len(lines) <= limit and
             all(line.isascii() and line.isdecimal() and line == str(int(line)) and
                 1 <= int(line) <= 1 << 30 for line in lines) and
             len(set(lines)) == len(lines), 'bounded unique canonical child PID census')
        return set(lines)

    def cgroup(self, leaf, unit_identity, leaf_identity, *, own_pid=None):
        self.partial = {'path': os.fspath(leaf), 'identity': None, 'files': {},
                        'children': None, 'parentControl': None,
                        'memberProcesses': {}, 'procsAfter': None,
                        'complete': False, 'lastPath': os.fspath(leaf),
                        'attemptedPid': None, 'firstFailure': None, 'secondary': []}
        try:
            value = self._cgroup(leaf, unit_identity, leaf_identity, own_pid=own_pid)
            self.partial = None
            return value
        except BaseException as exc:
            self.partial['firstFailure'] = failure(exc, 'child-cgroup-observation',
                                                   path=self.partial['lastPath'])
            self.partial['secondary'] = self.secondary[-SECONDARY_LIMIT:]
            need(len(canonical(self.partial)) <= 262144,
                 'bounded failed child cgroup partial')
            raise

    def _cgroup(self, leaf, unit_identity, leaf_identity, *, own_pid=None):
        need(self._first_five(self._directory(self.unit)) == self._first_five(unit_identity),
             'held unit identity at child observation')
        current = self._directory(leaf)
        self.partial['identity'] = current
        need(self._first_five(current) == self._first_five(leaf_identity),
             'held leaf identity at child observation')
        names = ('cpu.max', 'memory.max', 'memory.swap.max', 'pids.max',
                 'cgroup.procs', 'cgroup.events', 'cgroup.stat', 'cpu.stat')
        files = {}
        for name in names:
            self.partial['lastPath'] = os.fspath(leaf / name)
            files[name] = self._read(leaf / name, 4096)
            self.partial['files'][name] = files[name]
        entries = []
        with os.scandir(leaf) as iterator:
            for entry in iterator:
                need(len(entries) < 64, 'bounded child cgroup directory census')
                entries.append(entry)
        need(not any(entry.is_symlink() for entry in entries),
             'no symlink in selected child cgroup leaf')
        children = sorted(entry.name for entry in entries if entry.is_dir(follow_symlinks=False))
        self.partial['children'] = children
        need(not children, 'no nested child cgroup')
        if own_pid is None:
            need(files['cgroup.procs'] == '', 'terminal child cgroup PID absence')
            members = {}
            self.partial['lastPath'] = os.fspath(leaf / 'cgroup.procs')
            procs_after = self._read(leaf / 'cgroup.procs', 4096)
            self.partial['procsAfter'] = procs_after
            need(procs_after == '', 'held terminal child cgroup PID absence')
        else:
            integer(self.member_cap, 1, 64, 'selected child task cap')
            pids = self._pids(files['cgroup.procs'], self.member_cap)
            need(str(own_pid) in pids, 'source-owned child in finite leaf census')
            members = {}
            for pid in sorted(pids, key=int):
                self.partial['attemptedPid'] = pid
                self.partial['lastPath'] = '/proc/' + pid
                members[pid] = self.proc(int(pid), phase='postexec')
                self.partial['memberProcesses'][pid] = members[pid]
                need(len(canonical(self.partial)) <= 196608,
                     'bounded completed child-member prefix')
            total = sum(len(raw.encode('ascii')) for item in members.values() for raw in
                        (item['procStat'], item['procStatus'], item['procCgroup'], item['procLimits']))
            need(total <= 131072, 'bounded aggregate raw child-member observations')
            self.partial['lastPath'] = os.fspath(leaf / 'cgroup.procs')
            procs_after = self._read(leaf / 'cgroup.procs', 4096)
            self.partial['procsAfter'] = procs_after
            need(self._pids(procs_after, self.member_cap) == pids,
                 'two exact same-set child PID censuses')
            expected_path = '0::/' + leaf.relative_to(Path('/sys/fs/cgroup')).as_posix() + '\n'
            for key, item in members.items():
                need(item['pid'] == int(key) and item['procCgroup'] == expected_path and
                     re.search(r'(?m)^Uid:\s+' + str(self.proc_owner) +
                               r'\s+' + str(self.proc_owner) + r'\s+' +
                               str(self.proc_owner) + r'\s+' + str(self.proc_owner) + r'$',
                               item['procStatus']) is not None and
                     re.search(r'(?m)^Gid:\s+' + str(self.proc_group) +
                               r'\s+' + str(self.proc_group) + r'\s+' +
                               str(self.proc_group) + r'\s+' + str(self.proc_group) + r'$',
                               item['procStatus']) is not None,
                     'selected child-member raw credentials and leaf membership')
        self.partial['lastPath'] = os.fspath(self.unit / 'cgroup.subtree_control')
        parent = self.parent_control()
        self.partial['parentControl'] = parent
        return {'path': os.fspath(leaf), 'identity': current, 'files': files,
                'children': children, 'parentControl': parent,
                'memberProcesses': members, 'procsAfter': procs_after}

    def proc(self, pid, *, phase='postexec'):
        integer(pid, 1, 1 << 30, 'owned child PID')
        integer(self.proc_owner, 1, 65534, 'selected proc owner')
        integer(self.proc_group, 1, 65534, 'selected proc group')
        need(phase in ('preexec', 'postexec'), 'closed child proc observation phase')
        base = Path('/proc') / str(pid)
        owner_pairs = {(0, 0), (self.proc_owner, self.proc_group)}
        values = {name: self._read(base / name, 16384,
                                  owner_pairs=owner_pairs, observe=True)
                  for name in ('stat', 'status', 'cgroup', 'limits')}
        return {'pid': pid, 'procStat': values['stat'][0],
                'procStatus': values['status'][0],
                'procCgroup': values['cgroup'][0],
                'procLimits': values['limits'][0],
                'fileObservations': {name: values[name][1] for name in values}}

    def receipt(self, name):
        work_identity = self._directory(self.work)
        path = self.work / (name + '.preexec.original.json')
        fd = os.open(path, os.O_RDWR | os.O_CREAT | os.O_EXCL | os.O_CLOEXEC |
                     os.O_NOFOLLOW, 0o600)
        try:
            row = identity(os.fstat(fd))
            need(stat.S_ISREG(row['mode']) and row['uid'] == row['gid'] == 0 and
                 row['mode'] & 0o777 == 0o600 and row['nlink'] == 1 and
                 self._first_five(identity(os.lstat(path))) == self._first_five(row),
                 'protected preexec original')
            need(self._first_five(self._directory(self.work)) == self._first_five(work_identity),
                 'held protected work directory')
            return fd, path, row, work_identity
        except BaseException as exc:
            self._close(fd, exc)
            raise

    def read_receipt(self, fd, path, row, work_identity):
        raw = os.pread(fd, 16385, 0)
        need(1 <= len(raw) <= 16384, 'bounded preexec original bytes')
        need(self._first_five(identity(os.fstat(fd))) == self._first_five(row) and
             self._first_five(identity(os.lstat(path))) == self._first_five(row) and
             self._first_five(self._directory(self.work)) == self._first_five(work_identity),
             'held preexec original identity')
        value = raw_object(raw, 16384)
        need(canonical(value) == raw, 'canonical preexec original')
        return value

    @staticmethod
    def close_receipt(fd):
        os.close(fd)

    def absent_proc(self, pid):
        try:
            os.stat(Path('/proc') / str(pid), follow_symlinks=False)
        except FileNotFoundError as exc:
            return {'pid': pid, 'procPresent': False, 'errno': exc.errno}
        raise Refusal('reaped child proc entry remains present')


class ChildProcessProvider:
    """One source-selected child and one selected cgroup leaf per phase."""

    kernel_factory = ChildKernel

    def __init__(self, route, env, uid, gid, work_root, unit_path):
        need(route in ('build', 'reference'), 'closed child route')
        integer(uid, 1, 65534, 'child invoker UID')
        integer(gid, 1, 65534, 'child invoker GID')
        need(type(env) is dict and all(type(k) is str and type(v) is str for k, v in env.items()),
             'closed child environment')
        need('GH_TOKEN' not in env and 'GITHUB_TOKEN' not in env,
             'no service token reaches compiler or guest child')
        self.route, self.env, self.uid, self.gid = route, dict(env), uid, gid
        self.work_root, self.unit_path = Path(work_root), Path(unit_path)
        self.kernel = self.kernel_factory(self.unit_path, self.work_root)
        self.kernel.proc_owner = uid
        self.kernel.proc_group = gid
        self.kernel.member_cap = LIMITS[route]['tasks']
        self.used = set()

    def process(self, name, argv, *, wall_seconds, stream_cap, checkpoint):
        allowed = {'build': ('configure', 'make'), 'reference': ('js', 'bochs')}
        need(name in allowed[self.route] and name not in self.used,
             'fixed unique child phase')
        integer(wall_seconds, 1, LIMITS[self.route]['childWallSeconds'],
                'selected bounded child wall')
        integer(stream_cap, 1, LIMITS[self.route]['streamBytes'],
                'selected bounded child streams')
        need(type(checkpoint) is bool and checkpoint == (name == 'bochs'),
             'selected child checkpoint policy')
        self.used.add(name)  # A failed leaf/receipt never permits a duplicate child.
        policy = LIMITS[self.route]
        edge_secondary_start = len(self.kernel.secondary)
        if self.kernel.delegation is None:
            self.kernel.prepare_delegation(os.getpid())
        texts = {'cpu.max': str(policy['cpuQuota']) + ' ' + str(policy['cpuPeriod']) + '\n',
                 'memory.max': str(policy['memoryBytes']) + '\n',
                 'memory.swap.max': str(policy['swapBytes']) + '\n',
                 'pids.max': str(policy['tasks']) + '\n'}
        leaf, unit_identity, leaf_identity = self.kernel.create_leaf(name, texts)
        receipt_fd, receipt_path, receipt_row, work_identity = self.kernel.receipt(name)
        first = None
        last_observed_pid = None

        def spawn(pid):
            nonlocal last_observed_pid
            last_observed_pid = pid
            pre = None
            before = None
            try:
                pre = self.kernel.read_receipt(receipt_fd, receipt_path, receipt_row, work_identity)
                need(set(pre) == {'pid', 'uid', 'euid', 'gid', 'egid', 'core', 'nofile', 'cpu',
                                 'fsize', 'sigtermDefault', 'sigtermBlocked', 'rawBeforeExec'} and
                     pre['pid'] == pid and pre['uid'] == pre['euid'] == self.uid and
                     pre['gid'] == pre['egid'] == self.gid and
                     pre['sigtermDefault'] is True and pre['sigtermBlocked'] is False,
                     'exact retained child preexec identity')
                before = self.kernel.cgroup(leaf, unit_identity, leaf_identity, own_pid=pid)
                need(str(pid) in self.kernel._pids(before['files']['cgroup.procs'],
                                                   self.kernel.member_cap) and
                     self.kernel._pids(before['files']['cgroup.procs'], self.kernel.member_cap) ==
                     self.kernel._pids(before['procsAfter'], self.kernel.member_cap) ==
                     set(before['memberProcesses']),
                     'exact bounded child member PID sets and owned child')
                raw = before['memberProcesses'][str(pid)]
                expected_cgroup = '0::/' + leaf.relative_to(Path('/sys/fs/cgroup')).as_posix() + '\n'
                need(raw['procCgroup'] == expected_cgroup and
                     pre['rawBeforeExec']['procCgroup'] == expected_cgroup,
                     'child before-exec and parent proc cgroup agree with fixed leaf')
                need(all(before['files'][key] == text for key, text in texts.items()),
                     'selected child limits before execution')
                need(len(canonical(before)) <= 196608,
                     'bounded finite child member/parent observation packet')
                return {'identity': {'pid': pid, 'preexec': pre},
                        'resourcesBefore': {'preexec': pre, 'parentObserved': raw},
                        'cgroupBefore': before}
            except BaseException as exc:
                partial = {'identity': {'pid': pid, 'preexec': pre} if pre is not None else None,
                           'resourcesBefore': {'preexec': pre, 'parentObserved': None}
                           if pre is not None else None,
                           'cgroupBefore': before if before is not None else self.kernel.partial}
                need(len(canonical(partial)) <= 262144,
                     'bounded child callback failure partial')
                exc.bochs_partial = partial
                raise

        def terminal(pid, reaped):
            after = None
            absent = None
            try:
                need(type(pid) is int and pid == last_observed_pid and reaped is True,
                     'terminal observation follows exact owned reap')
                after = self.kernel.cgroup(leaf, unit_identity, leaf_identity)
                need(all(after['files'][key] == text for key, text in texts.items()),
                     'selected child limits after reap')
                events = after['files']['cgroup.events'].splitlines()
                stat_rows = after['files']['cgroup.stat'].splitlines()
                need(after['files']['cgroup.procs'] == '' and
                     events.count('populated 0') == 1 and
                     not any(row.startswith('populated ') and row != 'populated 0' for row in events) and
                     stat_rows.count('nr_descendants 0') == 1 and
                     stat_rows.count('nr_dying_descendants 0') == 1 and
                     not any(row.startswith('nr_descendants ') and row != 'nr_descendants 0'
                             or row.startswith('nr_dying_descendants ') and
                             row != 'nr_dying_descendants 0' for row in stat_rows),
                     'empty terminal child leaf and nested tree')
                absent = self.kernel.absent_proc(pid)
                return {'resourcesAfter': absent, 'cgroupAfter': after}
            except BaseException as exc:
                partial = {'resourcesAfter': absent,
                           'cgroupAfter': after if after is not None else self.kernel.partial}
                need(len(canonical(partial)) <= 262144,
                     'bounded terminal child observation partial')
                exc.bochs_partial = partial
                raise

        value = None
        try:
            prepare = preexec_policy(self.uid, self.gid, leaf, receipt_fd,
                                     cpu_seconds=wall_seconds,
                                     file_bytes=policy['perFileWriteBytes'],
                                     observe_before_exec=lambda pid, _uid, _gid:
                                     self.kernel.proc(pid, phase='preexec'))
            cwd = self.work_root / ('selected-source/bochs' if self.route == 'build'
                                    else 'runtime')
            value, streams, stop = child_capture(argv, cwd=cwd,
                                                 environment=self.env, name=name,
                                                 wall_seconds=wall_seconds,
                                                 stream_cap=stream_cap, preexec=prepare,
                                                 checkpoint=checkpoint,
                                                 observe_spawn=spawn,
                                                 observe_terminal=terminal,
                                                 pass_fds=(receipt_fd,))
        finally:
            try:
                self.kernel.close_receipt(receipt_fd)
            except BaseException as exc:
                if value is None:
                    raise
                item = failure(exc, 'preexec-receipt-close')
                if value['firstFailure'] is None:
                    value['firstFailure'] = item
                elif len(value['secondary']) < SECONDARY_LIMIT:
                    value['secondary'].append(item)
        if len(self.kernel.secondary) > edge_secondary_start:
            for item in self.kernel.secondary[edge_secondary_start:]:
                if value['firstFailure'] is None:
                    value['firstFailure'] = item
                elif len(value['secondary']) < SECONDARY_LIMIT:
                    value['secondary'].append(item)
        return value, streams, stop


CONTEXT_ENV = ('GITHUB_ACTIONS', 'GITHUB_REPOSITORY', 'GITHUB_ACTOR', 'GITHUB_EVENT_NAME',
    'GITHUB_RUN_ID', 'GITHUB_RUN_ATTEMPT', 'GITHUB_JOB', 'GITHUB_WORKFLOW_SHA',
    'GITHUB_WORKFLOW_REF', 'GITHUB_EVENT_PATH', 'GITHUB_WORKSPACE', 'BW_EXPECTED_HEAD')
SERVICE_SHOW_PROPERTIES = 'Id,Result,ExecMainCode,ExecMainStatus,ActiveState,ControlGroup'


def route_enabled(route, *, current=False):
    need(route in ROUTES, 'known source-owned route')
    if current and route in ('build','reference'):
        need({'build':BUILD_CURRENT_V2_ENABLED,'reference':REFERENCE_CURRENT_V2_ENABLED}[route] is True,
             'Bochs current source route inactive; no input or execution edge')
        return
    need({'toolchain-v2': TOOLCHAIN_V2_ENABLED, 'toolchain': TOOLCHAIN_ENABLED, 'build': BUILD_ENABLED,
          'reference': REFERENCE_ENABLED}[route] is True,
         'Bochs source route inactive; no host factory or input execution')


def route_paths(route, env):
    need(route in ROUTES and re.fullmatch(r'[1-9][0-9]{0,19}', env.get('GITHUB_RUN_ID', '')) and
         env.get('GITHUB_RUN_ATTEMPT') == '1', 'fixed first-attempt run root')
    stem = 'bw-bochs-' + ('toolchain-v2' if route == 'toolchain-v2' else route + '-v1') + '-' + env['GITHUB_RUN_ID'] + '-1'
    return {'work': Path('/run') / (stem + '-work'),
            'output': Path('/run') / (stem + '-originals'),
            'node': Path('/run') / (stem + '-node'), 'unit': stem + '.service'}


def public_context_environment(route, env):
    prefix = ROUTES[route][2]
    names = CONTEXT_ENV + (prefix + '_SHA256', prefix + '_B64')
    value = {}
    for name in names:
        item = env.get(name)
        need(type(item) is str and 1 <= len(item.encode('utf-8')) <=
             (49152 if name.endswith('_B64') else 4096) and '\0' not in item,
             'bounded required context field ' + name)
        value[name] = item
    need(value['GITHUB_ACTIONS'] == 'true', 'official Actions environment')
    # An allowlist, never dict(os.environ); secret values are not serialized.
    need('GH_TOKEN' not in value and 'GITHUB_TOKEN' not in value, 'no retained secret field')
    return value


def safe_root_directory(path, *, mode=None):
    """Exact non-link root directory; check every existing component."""
    path = Path(path)
    need(path.is_absolute() and '..' not in path.parts, 'absolute source-owned directory')
    for parent in (*reversed(path.parents), path):
        current = os.lstat(parent)
        need(stat.S_ISDIR(current.st_mode) and current.st_uid == current.st_gid == 0 and
             current.st_mode & 0o022 == 0, 'held safe root directory component')
    current = os.lstat(path)
    if mode is not None:
        need(stat.S_IMODE(current.st_mode) == mode, 'exact root directory mode')
    return identity(current)


def sealed_write(path, raw, cap):
    """New root-owned data only; no overwrite/retry of partial originals."""
    safe_root_directory(Path(path).parent)
    retain_exclusive(path, raw, cap)
    publish_root_mode(path, 0o444)
    check, _facts = read_regular(path, cap, minimum=0)
    need(check == raw, 'exact newly sealed retained original')


def publish_root_mode(path, mode, *, directory=False):
    """Publish only through a held no-follow root FD, never pathname chmod."""
    fd = None
    primary = None
    try:
        fd = os.open(os.fspath(path), os.O_RDONLY | os.O_CLOEXEC | os.O_NOFOLLOW |
                     (os.O_DIRECTORY if directory else 0))
        before = os.fstat(fd)
        need(before.st_uid == before.st_gid == 0 and
             (stat.S_ISDIR(before.st_mode) if directory else
              stat.S_ISREG(before.st_mode) and before.st_nlink == 1), 'owned mode publication FD')
        os.fchmod(fd, mode)
        after, named = os.fstat(fd), os.lstat(path)
        need(identity(after) == identity(named) and before.st_dev == after.st_dev and
             before.st_ino == after.st_ino and stat.S_IMODE(after.st_mode) == mode,
             'held and named exact published root mode')
    except BaseException as exc:
        primary = exc
    finally:
        if fd is not None:
            try:
                os.close(fd)
            except BaseException as exc:
                if primary is None:
                    primary = exc
                else:
                    primary.bochs_secondary = [failure(exc, 'publish-mode-close')]
    if primary is not None:
        raise primary


def admit_cli(route, env, workflow_root, invoker_uid, invoker_gid, *, current=False):
    route_enabled(route, current=current)  # before environment reads, paths or factories
    integer(invoker_uid, 1, 65534, 'trusted workflow invoker UID')
    integer(invoker_gid, 1, 65534, 'trusted workflow invoker GID')
    need(os.geteuid() == os.getuid() == os.getgid() == os.getegid() == 0,
         'source-owned root admission')
    need(env.get('SUDO_UID') == str(invoker_uid) and env.get('SUDO_GID') == str(invoker_gid),
         'workflow IDs joined to trusted sudo invoker')
    public = public_context_environment(route, env)
    prefix = ROUTES[route][2]
    encoded = public[prefix + '_B64']
    need(len(encoded) <= 4 * ((REQUEST_CAP + 2) // 3), 'bounded request before B64 decode')
    request_raw = base64.b64decode(encoded, validate=True)
    event_raw, _fact = read_regular(public['GITHUB_EVENT_PATH'], EVENT_CAP, minimum=1,
                                    owner=invoker_uid, group=invoker_gid)
    request = selected_request(route, request_raw, event_raw, public, current=current)
    source_root = Path(public['GITHUB_WORKSPACE']) / 'producer-source'
    workflow_root = Path(workflow_root)
    need(workflow_root == Path(public['GITHUB_WORKSPACE']) / 'workflow-source',
         'fixed data-only executing workflow checkout')
    for checkout in (source_root, workflow_root):
        info = os.lstat(checkout)
        need(stat.S_ISDIR(info.st_mode) and info.st_uid == invoker_uid and
             info.st_gid == invoker_gid and info.st_mode & 0o022 == 0,
             'trusted invoker owns checked source directory')
    observed = observe_source(source_root, request['source'], public, workflow_root)
    paths = route_paths(route, public)
    safe_root_directory('/run')
    # Creating either directory twice refuses; do not remove a preceding attempt.
    os.mkdir(paths['work'], 0o755)
    publish_root_mode(paths['work'], 0o755, directory=True)
    safe_root_directory(paths['work'], mode=0o755)
    os.mkdir(paths['output'], 0o755)
    publish_root_mode(paths['output'], 0o755, directory=True)
    safe_root_directory(paths['output'], mode=0o755)
    context = {'schema': 'bw.bochs-ring3.protected-context.v1', 'route': route,
        'env': public, 'invoker': {'uid': invoker_uid, 'gid': invoker_gid},
        'sourceRoot': str(source_root), 'workflowRoot': str(workflow_root),
        'source': observed, 'requestSha256': sha256(request_raw), 'eventSha256': sha256(event_raw)}
    if current:
        context['bootstrapCredentials'] = {'schema':'bw.bochs-ring3.bootstrap-caller.v1',
            'uidArgument':str(invoker_uid),'gidArgument':str(invoker_gid),
            'sudoUid':env['SUDO_UID'],'sudoGid':env['SUDO_GID']}
    retain_exclusive(paths['work'] / 'context.original.json', canonical(context), 131072)
    sealed_write(paths['output'] / 'request.original.json', request_raw, REQUEST_CAP)
    sealed_write(paths['output'] / 'event.original.json', event_raw, EVENT_CAP)
    return context


def load_cli_context(route, env, *, current=False):
    route_enabled(route, current=current)
    need(os.geteuid() == os.getuid() == os.getgid() == os.getegid() == 0,
         'source-owned root continuation')
    public = public_context_environment(route, env)
    paths = route_paths(route, public)
    safe_root_directory(paths['work'], mode=0o755)
    safe_root_directory(paths['output'], mode=0o755)
    raw, _fact = read_regular(paths['work'] / 'context.original.json', 131072, minimum=1)
    context = raw_object(raw, 131072)
    need(canonical(context) == raw, 'canonical protected context')
    closed(context, ('schema', 'route', 'env', 'invoker', 'sourceRoot', 'workflowRoot',
                     'source', 'requestSha256', 'eventSha256', * (('bootstrapCredentials',) if current else ())), 'closed protected context')
    need(context['schema'] == 'bw.bochs-ring3.protected-context.v1' and
         context['route'] == route and context['env'] == public, 'continuation context/event environment')
    closed(context['invoker'], ('uid', 'gid'), 'closed trusted invoker')
    integer(context['invoker']['uid'], 1, 65534, 'admitted invoker UID')
    integer(context['invoker']['gid'], 1, 65534, 'admitted invoker GID')
    need(context['sourceRoot'] == str(Path(public['GITHUB_WORKSPACE']) / 'producer-source') and
         context['workflowRoot'] == str(Path(public['GITHUB_WORKSPACE']) / 'workflow-source'),
         'source-owned checkout paths')
    if current:
        bootstrap_caller_scalars(context['bootstrapCredentials'], context['invoker'])
    request_raw, _fact = read_regular(paths['output'] / 'request.original.json', REQUEST_CAP, minimum=1)
    event_raw, _fact = read_regular(paths['output'] / 'event.original.json', EVENT_CAP, minimum=1)
    need(sha256(request_raw) == context['requestSha256'] and
         sha256(event_raw) == context['eventSha256'], 'exact protected request/event bytes')
    request = selected_request(route, request_raw, event_raw, public, current=current)
    need(observe_source(context['sourceRoot'], request['source'], public, context['workflowRoot']) ==
         context['source'], 'current source equals admitted protected context')
    return context, request_raw, event_raw, paths


def manager_arguments(route, context):
    """Fixed finite root service; no inherited pipe, quiet mode or secret value."""
    env = context['env']
    paths = route_paths(route, env)
    limits = LIMITS[route]
    argv = ['/usr/bin/systemd-run', '--wait', '--unit=' + paths['unit'],
        '--service-type=exec', '--property=CPUQuota=100%', '--property=CPUQuotaPeriodSec=100ms',
        '--property=MemoryMax=' + str(limits['memoryBytes']), '--property=MemorySwapMax=0',
        '--property=TasksMax=' + str(limits['tasks']),
        '--property=RuntimeMaxSec=' + str(limits['childWallSeconds'] if route != 'reference' else 180),
        '--property=TimeoutStopSec=5s', '--property=KillMode=control-group',
        '--property=Delegate=yes', '--property=DelegateSubgroup=controller',
        '--property=StandardOutput=null', '--property=StandardError=null',
        '--working-directory=' + context['sourceRoot']]
    child_env = {**env, 'SUDO_UID': str(context['invoker']['uid']),
                 'SUDO_GID': str(context['invoker']['gid']), 'PATH': '/usr/bin:/bin',
                 'LANG': 'C', 'LC_ALL': 'C', 'PYTHONDONTWRITEBYTECODE': '1'}
    argv.extend('--setenv=' + key + '=' + value for key, value in sorted(child_env.items()))
    if route == 'reference':
        argv.append('--setenv=GH_TOKEN')
    argv += ['/usr/bin/python3', '-I', '-S', '-B',
             str(Path(context['sourceRoot']) / 'scripts/i80386-bochs-ring3-reference/run.py'),
             '--work', '--route', route]
    need('--pipe' not in argv and '--quiet' not in argv and '--collect' not in argv and
         not any(x.startswith('--setenv=GH_TOKEN=') for x in argv),
         'unmixed manager receipt and secret name-only boundary')
    return argv


def run_service_cli(route, context, paths, *, capture=child_capture, secret=None):
    route_enabled(route)
    argv = manager_arguments(route, context)
    public_env = {**BOOTSTRAP_ENV}
    actual_env = dict(public_env)
    if route == 'reference':
        need(type(secret) is str and 1 <= len(secret) <= 4096 and '\0' not in secret,
             'reference secret supplied only to trusted manager client')
        actual_env['GH_TOKEN'] = secret
    sealed_write(paths['work'] / 'service-attempt.original.json', canonical({
        'schema': 'bw.bochs-ring3.service-attempt.v1', 'route': route,
        'unit': paths['unit'], 'requestSha256': context['requestSha256'],
        'eventSha256': context['eventSha256']}), 4096)
    process, streams, _stop = capture(argv, cwd=context['sourceRoot'], environment=actual_env,
        record_environment=public_env, name='service-client',
        wall_seconds=LIMITS[route]['outerWallSeconds'], stream_cap=65536)
    for which in ('stdout', 'stderr'):
        sealed_write(paths['work'] / ('service-client.' + which), streams[which], 65536)
    sealed_write(paths['work'] / 'service-client.original.json', canonical(process), 131072)
    return process


def capture_service_status_cli(route, context, paths, *, capture=child_capture):
    route_enabled(route)
    unit = paths['unit']
    value = {'schema': 'bw.bochs-ring3.service-status.v1', 'route': route, 'unit': unit,
        'client': None, 'receipt': None, 'postShow': None, 'firstFailure': None, 'secondary': []}
    def issue(exc, phase):
        item = failure(exc, phase)
        if value['firstFailure'] is None:
            value['firstFailure'] = item
        elif len(value['secondary']) < SECONDARY_LIMIT:
            value['secondary'].append(item)
    try:
        raw, _fact = read_regular(paths['work'] / 'service-client.original.json', 131072, minimum=1)
        process = raw_object(raw, 131072)
        stdout, _fact = read_regular(paths['work'] / 'service-client.stdout', 65536)
        stderr, _fact = read_regular(paths['work'] / 'service-client.stderr', 65536)
        for which, stream in (('stdout', stdout), ('stderr', stderr)):
            need(process[which]['bytes'] == len(stream) and process[which]['sha256'] == sha256(stream),
                 'actual manager stream identity')
        value['client'] = {'process': process,
            'stdoutBase64': base64.b64encode(stdout).decode('ascii'),
            'stderrBase64': base64.b64encode(stderr).decode('ascii')}
        value['receipt'] = service_receipt(stdout, stderr, process['exitCode'], unit)
        need(normal_manager_delivery(process), 'complete actual bounded manager client')
        need(value['receipt']['firstFailure'] is None, 'manager receipt proved normal service status')
    except BaseException as exc:
        issue(exc, 'capture-service-client')
    try:
        argv = ['/usr/bin/systemctl', 'show', unit, '--no-pager',
                '--property=' + SERVICE_SHOW_PROPERTIES]
        process, streams, _stop = capture(argv, cwd=context['sourceRoot'], environment=BOOTSTRAP_ENV,
            name='service-post-show', wall_seconds=5, stream_cap=16384)
        need(len(streams['stderr']) <= 4096, 'post-show diagnostic stderr cap')
        value['postShow'] = {'process': process,
            'stdoutBase64': base64.b64encode(streams['stdout']).decode('ascii'),
            'stderrBase64': base64.b64encode(streams['stderr']).decode('ascii')}
        # Unit unloading/failed-show is not proof of the service's exit status.
        # Its actual raw result is retained separately and may be nonzero.
        need(normal_manager_delivery(process), 'complete bounded post-show diagnostic delivery')
    except BaseException as exc:
        issue(exc, 'capture-service-post-show')
    sealed_write(paths['work'] / 'service-status.original.json', canonical(value), 524288)
    return value


def normal_manager_delivery(process):
    """A retained normal nonzero diagnostic exit is data, not an unknown exit.

    child_capture's ordinary exit0 assertion remains unchanged. Only its exact
    source-generated nonzero-status refusal is permitted here; caps, signals,
    missing reap, timeouts, callback/close failures remain delivery failures.
    """
    status = process.get('waitStatus')
    code = process.get('exitCode')
    if not (type(status) is int and type(code) is int and 0 <= code <= 255 and
            os.WIFEXITED(status) and os.WEXITSTATUS(status) == code and
            process.get('reaped') is True and process.get('timedOut') is False and
            process.get('signal') is None and process.get('secondary') == [] and
            process.get('stdout', {}).get('complete') is True and
            process.get('stderr', {}).get('complete') is True):
        return False
    expected = None if code == 0 else failure(Refusal('ordinary child completed exit0'), 'child-capture')
    return process.get('firstFailure') == expected


def write_work_roles(paths, roles, route):
    limits = LIMITS[route]
    need(type(roles) is dict and 1 <= len(roles) <= limits['members'], 'bounded authored original roster')
    need(sum(len(raw) for raw in roles.values()) <= limits['expandedBytes'], 'authored original aggregate cap')
    for name, raw in roles.items():
        member_name(name)
        need(type(raw) is bytes, 'raw original role bytes')
        target = paths['output'] / name
        current = paths['output']
        for part in Path(name).parts[:-1]:
            current = current / part
            try:
                os.mkdir(current, 0o755)
                publish_root_mode(current, 0o755, directory=True)
            except FileExistsError:
                safe_root_directory(current, mode=0o755)
        if name in ('request.original.json', 'event.original.json') and target.exists():
            existing, _fact = read_regular(target, EVENT_CAP, minimum=1)
            need(existing == raw, 'preserve admission original bytes')
        else:
            sealed_write(target, raw, limits['expandedBytes'])


def retained_output_roles(paths, route):
    """Finite root-only tree walk; never follow a link or repair missing files."""
    limits = LIMITS[route]
    result = {}
    total = 0
    visited = 0
    def visit(directory, prefix):
        nonlocal total, visited
        safe_root_directory(directory, mode=0o755)
        with os.scandir(directory) as entries:
            for item in entries:
                visited += 1
                need(visited <= limits['members'], 'retained files and directory census cap')
                name = prefix + item.name
                member_name(name)
                need(len(result) < limits['members'], 'retained partial member cap')
                info = item.stat(follow_symlinks=False)
                if stat.S_ISDIR(info.st_mode):
                    # Depth and finite path grammar bound even an empty-dir tree.
                    need(len(Path(name).parts) <= 8, 'retained role directory depth')
                    visit(Path(directory) / item.name, name + '/')
                else:
                    raw, _fact = read_regular(Path(directory) / item.name,
                        min(limits['expandedBytes'] - total, limits['expandedBytes']), minimum=0)
                    total += len(raw)
                    need(total <= limits['expandedBytes'], 'retained partial aggregate extent')
                    result[name] = raw
    visit(paths['output'], '')
    return result


def work_cli(route, context, request_raw, event_raw, paths, *, provider_factory, current=False):
    route_enabled(route, current=current)
    # Exclusive durable boundary before any data acquisition or possible execution.
    sealed_write(paths['work'] / 'work-attempt.original.json', canonical({
        'schema': 'bw.bochs-ring3.work-attempt.v1', 'route': route,
        'requestSha256': sha256(request_raw), 'eventSha256': sha256(event_raw)}), 4096)
    ops = provider_factory(route, context, paths)
    value, roles = dispatch(route, request_raw, event_raw, context['env'], lambda _request, _env: ops, current=current)
    inner_root = paths['work'] / 'inner-originals'
    os.mkdir(inner_root, 0o755)
    publish_root_mode(inner_root, 0o755, directory=True)
    write_work_roles({**paths, 'output': inner_root}, roles, route)
    return value


def finish_cli(route, context, request_raw, event_raw, paths, *, provider_factory,
               service_status, claimed_service=None, claimed_client=None, current=False):
    route_enabled(route, current=current)
    need(Path(service_status) == paths['work'] / 'service-status.original.json',
         'fixed service status original path')
    # No cleanup/finish replay even when a preceding attempt retained a failure.
    sealed_write(paths['work'] / 'finish-attempt.original.json', canonical({
        'schema': 'bw.bochs-ring3.finish-attempt.v1', 'route': route,
        'requestSha256': sha256(request_raw), 'eventSha256': sha256(event_raw)}), 4096)
    inner_root = paths['work'] / 'inner-originals'
    try:
        roles = retained_output_roles({**paths, 'output': inner_root}, route)
    except FileNotFoundError:
        roles = {name: read_regular(paths['output'] / name, EVENT_CAP, minimum=1)[0]
                 for name in ('request.original.json', 'event.original.json')}
    roles.pop('manifest.json', None)  # new final manifest is a separate phase below
    key = {'toolchain-v2': 'original.json', 'toolchain': 'original.json', 'build': 'build.original.json',
           'reference': 'original.json'}[route]
    inner = raw_object(roles[key], LIMITS[route]['expandedBytes']) if key in roles else None
    status = None
    status_raw = None
    status_error = None
    service_exit = client_exit = None
    try:
        status_raw, _fact = read_regular(service_status, 524288, minimum=1)
        status = raw_object(status_raw, 524288)
        closed(status, ('schema', 'route', 'unit', 'client', 'receipt', 'postShow',
                        'firstFailure', 'secondary'), 'closed service original')
        need(canonical(status) == status_raw and status['schema'] == 'bw.bochs-ring3.service-status.v1' and
             status['route'] == route and status['unit'] == paths['unit'], 'bound service status original')
        need(status['firstFailure'] is None and not status['secondary'], 'complete captured service status')
        client = status['client']
        stdout = base64.b64decode(client['stdoutBase64'], validate=True)
        stderr = base64.b64decode(client['stderrBase64'], validate=True)
        observed = service_receipt(stdout, stderr, client['process']['exitCode'], paths['unit'])
        need(normal_manager_delivery(client['process']) and
             client['process']['name'] == 'service-client' and
             client['process']['argv'] == manager_arguments(route, context) and
             all(client['process'][which]['bytes'] == len(raw) and
                 client['process'][which]['sha256'] == sha256(raw)
                 for which, raw in (('stdout', stdout), ('stderr', stderr))) and
             observed == status['receipt'] and observed['firstFailure'] is None,
             'independently recomputed raw manager receipt')
        service_exit = observed['serviceExitCode']
        client_exit = client['process']['exitCode']
        need(claimed_service in (None, service_exit) and claimed_client in (None, client_exit),
             'optional status arguments agree with actual retained receipt')
    except BaseException as exc:
        status_error = exc
        service_exit = client_exit = None
    if status_raw is not None:
        roles['service-status.original.json'] = status_raw
    ops = provider_factory(route, context, paths)
    input_cleanup = None
    pre_cleanup_error = None
    if route in ('build', 'reference'):
        try:
            # This phase may only observe exact sealed inputs and filesystem
            # metadata. It precedes even the first cgroup rmdir.
            input_cleanup = ops.prepare_host_cleanup(inner, roles)
        except BaseException as exc:
            pre_cleanup_error = exc
    outside, roles = finalize_original(route, request_raw, event_raw, context['env'], inner,
                                       roles, service_exit, client_exit, ops,
                                       input_cleanup=input_cleanup, pre_cleanup_error=pre_cleanup_error,
                                       status_error=status_error, current=current)
    # A separately retained Node cleanup is required even for a metadata route:
    # no positive outside verdict while its root-owned staged executable remains.
    outside['nodeCleanup'] = None
    try:
        need(outside['after'] is not None and outside['after']['exists'] is False and
             outside['after']['errno'] == 2,
             'selected service terminal absence before any staged-input removal')
        outside['nodeCleanup'] = ops.node_cleanup(inner)
        need(outside['nodeCleanup']['complete'] is True and
             outside['nodeCleanup']['firstFailure'] is None and
             not outside['nodeCleanup']['secondary'], 'complete owned Node stage cleanup')
    except BaseException as exc:
        item = failure(exc, 'outside-node-cleanup')
        if outside['firstFailure'] is None:
            outside['firstFailure'] = item
        elif len(outside['secondary']) < SECONDARY_LIMIT:
            outside['secondary'].append(item)
    if (route in ('build', 'reference') and input_cleanup is not None and
            outside['nodeCleanup'] is not None and outside['nodeCleanup']['complete'] is True):
        try:
            need(outside['nodeCleanup'] is not None and outside['nodeCleanup']['complete'] is True and
                 outside['nodeCleanup']['firstFailure'] is None and not outside['nodeCleanup']['secondary'] and
                 outside['after'] is not None and outside['after']['exists'] is False,
                 'completed Node cleanup and selected service absence before library removal')
            role_raw = ops.host_cleanup()
            need(type(role_raw) is bytes and len(role_raw) <= input_cleanup['hostRuntimePlan']['roleReservedBytes'],
                 'whole reserved host runtime role after cleanup')
            roles['host-runtime.original.json'] = role_raw
            result = raw_object(role_raw, 1048576)['cleanup']
            outside['hostRuntimeCleanup'] = {'role': 'host-runtime.original.json', 'bytes': len(role_raw),
                'sha256': sha256(role_raw)}
            need(result['complete'] is True and result['firstFailure'] is None and not result['secondary'],
                 'complete owned staged-library cleanup')
        except BaseException as exc:
            item = failure(exc, 'outside-host-runtime-cleanup')
            if outside['firstFailure'] is None:
                outside['firstFailure'] = item
            elif len(outside['secondary']) < SECONDARY_LIMIT:
                outside['secondary'].append(item)
    outside['cleanupExitCode'] = 0 if outside['firstFailure'] is None and not outside['secondary'] else 1
    if len(canonical(outside)) > 16384:
        item = failure(Refusal('complete outside cleanup envelope cap'), 'outside-final-wire')
        if outside['firstFailure'] is None:
            outside['firstFailure'] = item
        elif len(outside['secondary']) < SECONDARY_LIMIT:
            outside['secondary'].append(item)
        outside['cleanupExitCode'] = 1
    roles['outside.original.json'] = canonical(outside)
    # Work's protected tree remains immutable. Publish a separate exact retained
    # byte copy to the sole artifact root; admission's two originals stay held.
    roles['manifest.json'] = canonical(original_manifest({k: v for k, v in roles.items()
                                                         if k != 'manifest.json'}))
    write_work_roles(paths, roles, route)
    return outside, roles



def cleanup_node_stage(route, env, inner):
    """Remove only the exact source-created stage, with a bounded raw journal.

    Unknown names/identity stop before mutation. Partial staging without retained
    file identity remains an honest cleanup refusal, never guessed ownership.
    """
    paths = route_paths(route, env)
    root = paths['node']
    value = {'schema': 'bw.bochs-ring3.node-cleanup.v1', 'route': route,
        'path': str(root), 'parentBefore': None, 'parentAfter': None,
        'before': None, 'members': {}, 'journal': [], 'after': None,
        'heldBefore': None, 'heldBeforeRmdir': None, 'namedBeforeRmdir': None,
        'complete': False, 'firstFailure': None, 'secondary': []}
    directory_fd = None
    reserved = None
    def issue(exc, phase):
        row = failure(exc, phase, path=str(root))
        if value['firstFailure'] is None:
            value['firstFailure'] = row
        elif len(value['secondary']) < SECONDARY_LIMIT:
            value['secondary'].append(row)
    def first_five(row):
        return tuple(row[k] for k in ('dev', 'ino', 'mode', 'uid', 'gid'))
    def meta_row(raw):
        need(type(raw) is list and len(raw) == 9, 'retained staged identity before cleanup')
        return dict(zip(('dev', 'ino', 'mode', 'uid', 'gid', 'nlink', 'size', 'mtimeNs', 'ctimeNs'), raw))
    def absent(path):
        try:
            observed = os.lstat(path)
        except FileNotFoundError as exc:
            need(exc.errno == 2, 'actual ENOENT terminal stage observation')
            return {'exists': False, 'errno': 2, 'identity': None}
        return {'exists': True, 'errno': None, 'identity': identity(observed)}
    def mutation(operation, path, before, action):
        row = {'operation': operation, 'path': str(path), 'before': before,
               'attempted': False, 'after': None, 'firstFailure': None}
        value['journal'].append(row)
        need(reserved is not None and reserved <= 16384 and len(canonical(value)) <= 16384,
             'whole remaining bounded Node cleanup original before mutation')
        row['attempted'] = True
        try:
            action()
            row['after'] = absent(path)
        except BaseException as exc:
            row['firstFailure'] = failure(exc, 'node-cleanup-' + operation, path=str(path))
            try:
                row['after'] = absent(path)
            except BaseException as extra:
                issue(extra, 'node-cleanup-failed-after')
            raise
    try:
        value['parentBefore'] = safe_root_directory('/run')
        facts = None if inner is None else (inner.get('observations') or {}).get('nodeStage')
        if facts is None and inner is not None and type(inner.get('failurePartial')) is dict:
            facts = inner['failurePartial'].get('nodeStage')
        value['before'] = absent(root)
        if not value['before']['exists']:
            need(facts is None or str(root) not in facts.get('created', []),
                 'created staged root may not disappear before owned cleanup')
            value['after'] = value['before']
        else:
            need(type(facts) is dict and facts.get('stagePath') == str(root / 'node') and
                 str(root) in facts.get('created', []), 'bound source-created Node root')
            expected_directory = facts.get('directory') or facts.get('directoryAfterFailure') or facts.get('directoryInitial')
            expected_directory = meta_row(expected_directory)
            need(first_five(value['before']['identity']) == first_five(expected_directory),
                 'exact first-five staged directory before cleanup')
            directory_fd = os.open(root, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC)
            value['heldBefore'] = identity(os.fstat(directory_fd))
            need(first_five(value['heldBefore']) == first_five(expected_directory),
                 'held Node cleanup directory identity')
            names = []
            with os.scandir(root) as entries:
                for entry in entries:
                    names.append(entry.name)
                    need(len(names) <= 2 and entry.name in ('node', 'stage.json'),
                         'no unknown staged Node member')
            expected = {}
            if 'node' in names:
                expected['node'] = meta_row(facts.get('file') or facts.get('targetAfterFailure') or
                                            facts.get('fileBeforePublication') or facts.get('fileInitial'))
            if 'stage.json' in names:
                need(type(facts.get('record')) is dict, 'retained installation-record identity')
                expected['stage.json'] = meta_row(facts['record']['metadata'])
            for name in names:
                observed = identity(os.stat(name, dir_fd=directory_fd, follow_symlinks=False))
                need(stat.S_ISREG(observed['mode']) and observed['uid'] == observed['gid'] == 0 and
                     observed['nlink'] == 1 and first_five(observed) == first_five(expected[name]),
                     'exact owned staged member before any cleanup mutation')
                value['members'][name] = observed
            # Size-only projection, never retained as an observation. Reserve all
            # remaining rows and terminal fields before the first chmod/unlink.
            def future_metadata(row):
                return {**row, 'size': max(row['size'], 2**64 - 1),
                        'mtimeNs': max(row['mtimeNs'], 2**64 - 1),
                        'ctimeNs': max(row['ctimeNs'], 2**64 - 1)}
            private_reserved = future_metadata({**value['before']['identity'], 'mode': stat.S_IFDIR | 0o700})
            future = json.loads(canonical(value))
            future['journal'] = [{'operation': 'chmod-private', 'path': str(root),
                'before': value['before']['identity'], 'attempted': True,
                'after': {'exists': True, 'errno': None, 'identity': private_reserved}, 'firstFailure': None}]
            for name in sorted(names):
                future['journal'].append({'operation': 'unlink', 'path': str(root / name),
                    'before': value['members'][name], 'attempted': True,
                    'after': {'exists': False, 'errno': 2, 'identity': None}, 'firstFailure': None})
            future['journal'].append({'operation': 'rmdir', 'path': str(root), 'before': private_reserved,
                'attempted': True, 'after': {'exists': False, 'errno': 2, 'identity': None}, 'firstFailure': None})
            future.update(parentAfter=future_metadata(value['parentBefore']),
                heldBeforeRmdir=private_reserved, namedBeforeRmdir=private_reserved,
                after={'exists': False, 'errno': 2, 'identity': None}, complete=True)
            reserved = len(canonical(future)) + 512
            need(reserved <= 16384, 'complete prospective Node cleanup witness and close-error reserve')
            mutation('chmod-private', root, value['before']['identity'],
                     lambda: os.fchmod(directory_fd, 0o700))
            private = identity(os.fstat(directory_fd))
            need(private['mode'] == stat.S_IFDIR | 0o700 and
                 (private['dev'], private['ino'], private['uid'], private['gid']) ==
                 tuple(expected_directory[k] for k in ('dev', 'ino', 'uid', 'gid')),
                 'same privately writable cleanup root')
            for name in sorted(names):
                observed = identity(os.stat(name, dir_fd=directory_fd, follow_symlinks=False))
                need(first_five(observed) == first_five(expected[name]) and
                     first_five(identity(os.fstat(directory_fd))) == first_five(private) and
                     first_five(identity(os.lstat(root))) == first_five(private),
                     'held/named identities before each staged unlink')
                mutation('unlink', root / name, observed,
                         lambda name=name: os.unlink(name, dir_fd=directory_fd))
            with os.scandir(root) as entries:
                need(next(entries, None) is None, 'empty known staged root before rmdir')
            need(first_five(identity(os.lstat(root))) == first_five(private) and
                 first_five(identity(os.fstat(directory_fd))) == first_five(private),
                 'held/named root before final rmdir')
            value['heldBeforeRmdir'] = identity(os.fstat(directory_fd))
            value['namedBeforeRmdir'] = identity(os.lstat(root))
            mutation('rmdir', root, private, lambda: os.rmdir(root))
            value['after'] = absent(root)
            need(value['after']['exists'] is False, 'owned Node root absent after cleanup')
        value['parentAfter'] = safe_root_directory('/run')
        need(first_five(value['parentBefore']) == first_five(value['parentAfter']),
             'fixed root parent first-five after Node cleanup')
    except BaseException as exc:
        issue(exc, 'node-stage-cleanup')
    finally:
        if directory_fd is not None:
            try:
                os.close(directory_fd)
            except BaseException as exc:
                issue(exc, 'node-cleanup-directory-close')
    value['complete'] = value['firstFailure'] is None and not value['secondary']
    if value['complete'] and len(canonical(value)) > 16384:
        issue(Refusal('complete Node cleanup wire cap'), 'node-cleanup-final-wire')
        value['complete'] = False
    return value




def source_http(url, cap, *, minimum=1, token=None):
    """One bounded data GET; no acquired bytes execute before their role joins.

    Caller supplies only source-constructed upstream or owned-artifact URLs.
    Redirect credentials are stripped, signed redirect URLs never retained.
    SIGALRM bounds a blocked network read, not just checks between reads.
    """
    need(type(url) is str and url.startswith('https://') and
         (url.startswith('https://raw.githubusercontent.com/' + UPSTREAM + '/' + UPSTREAM_COMMIT + '/') or
          url == VGA_SOURCE_URL or
          url.startswith('https://api.github.com/repos/' + UPSTREAM + '/git/trees/' + UPSTREAM_TREE + '?') or
          url.startswith('https://api.github.com/repos/' + REPOSITORY + '/actions/')),
         'source-fixed HTTPS data route')
    integer(cap, 1, 67108864, 'bounded data GET cap')
    need(0 <= minimum <= cap, 'typed empty/nonempty data extent')
    class Redirect(urllib.request.HTTPRedirectHandler):
        count = 0
        def redirect_request(self, req, fp, code, msg, headers, newurl):
            self.count += 1
            need(self.count <= 3 and newurl.startswith('https://'), 'bounded HTTPS redirect transport')
            redirected = super().redirect_request(req, fp, code, msg, headers, newurl)
            if redirected is not None:
                redirected.remove_header('Authorization')
            return redirected
    def alarm(_number, _frame):
        raise TimeoutError('bounded data GET wall deadline')
    old_alarm = signal.getsignal(signal.SIGALRM)
    previous = signal.getitimer(signal.ITIMER_REAL)
    need(previous == (0.0, 0.0), 'no preexisting network deadline owner')
    response = None
    raw = bytearray()
    primary = None
    secondary = []
    started = time.monotonic_ns()
    try:
        signal.signal(signal.SIGALRM, alarm)
        signal.setitimer(signal.ITIMER_REAL, 45)
        headers = {'User-Agent': 'bw-bochs-source-v1', 'Accept': 'application/vnd.github+json'}
        if token is not None:
            need(type(token) is str and 1 <= len(token) <= 4096 and '\0' not in token,
                 'trusted owned-artifact token shape')
            headers['Authorization'] = 'Bearer ' + token
        request = urllib.request.Request(url, headers=headers, method='GET')
        response = urllib.request.build_opener(Redirect()).open(request, timeout=45)
        need(response.status == 200, 'one admitted data GET HTTP200')
        length = response.headers.get('Content-Length')
        if length is not None:
            need(re.fullmatch(r'0|[1-9][0-9]*', length) and minimum <= int(length) <= cap,
                 'bounded official data Content-Length')
        while True:
            part = response.read(min(65536, cap + 1 - len(raw)))
            if not part:
                break
            raw.extend(part)
            need(len(raw) <= cap, 'one data GET stream cap')
        need(minimum <= len(raw) <= cap and (length is None or int(length) == len(raw)),
             'complete role-typed data response')
        need(time.monotonic_ns() - started <= 45000000000, 'actual bounded data wall extent')
    except BaseException as exc:
        primary = exc
    finally:
        if response is not None:
            try:
                response.close()
            except BaseException as exc:
                if primary is None:
                    primary = exc
                else:
                    secondary.append(failure(Refusal(type(exc).__name__), 'data-response-close'))
        try:
            signal.setitimer(signal.ITIMER_REAL, 0)
            signal.signal(signal.SIGALRM, old_alarm)
        except BaseException as exc:
            if primary is None:
                primary = exc
            else:
                secondary.append(failure(Refusal(type(exc).__name__), 'data-alarm-close'))
    if primary is not None:
        # Exceptions from urllib can include signed redirect URLs; keep only a
        # source-owned phase/reason here, never its repr or response body.
        error = Refusal('bounded source/owned-artifact GET failed: ' + type(primary).__name__)
        error.bochs_partial = {'bytes': len(raw), 'sha256': sha256(raw),
                               'complete': False, 'secondary': secondary}
        raise error from None
    return bytes(raw)


def source_archive(files, modes):
    output = io.BytesIO()
    with tarfile.open(fileobj=output, mode='w', format=tarfile.USTAR_FORMAT) as archive:
        for name, raw in sorted(files.items()):
            member_name(name)
            item = tarfile.TarInfo(name)
            item.uid = item.gid = item.mtime = 0
            item.mode = modes[name]
            item.size = len(raw)
            archive.addfile(item, io.BytesIO(raw))
    return gzip.compress(output.getvalue(), compresslevel=6, mtime=0)


def caller_directory(path, uid, gid, *, mode=0o755):
    need(mode in (0o700, 0o755), 'closed owned directory mode')
    os.mkdir(path, 0o700)
    fd = os.open(path, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC)
    primary = None
    try:
        os.fchmod(fd, mode)
        os.fchown(fd, uid, gid)
        row = identity(os.fstat(fd))
        need(row['uid'] == uid and row['gid'] == gid and row['mode'] == stat.S_IFDIR | mode and
             row == identity(os.lstat(path)), 'new exact invoker-owned source directory')
    except BaseException as exc:
        primary = exc
    finally:
        try:
            os.close(fd)
        except BaseException as exc:
            if primary is None:
                primary = exc
            else:
                primary.bochs_secondary = [failure(exc, 'source-directory-close')]
    if primary is not None:
        raise primary


def caller_file(path, raw, mode, uid, gid):
    retain_exclusive(path, raw, 67108864)
    fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC)
    primary = None
    try:
        before = identity(os.fstat(fd))
        need(before['uid'] == before['gid'] == 0 and stat.S_ISREG(before['mode']) and
             before['nlink'] == 1 and before['size'] == len(raw), 'new owned raw input before publication')
        os.fchmod(fd, mode)
        os.fchown(fd, uid, gid)
        after = identity(os.fstat(fd))
        need(after['uid'] == uid and after['gid'] == gid and
             after['mode'] == stat.S_IFREG | mode and after == identity(os.lstat(path)) and
             (after['dev'], after['ino']) == (before['dev'], before['ino']),
             'new exact invoker-owned source file')
    except BaseException as exc:
        primary = exc
    finally:
        try:
            os.close(fd)
        except BaseException as exc:
            if primary is None:
                primary = exc
            else:
                primary.bochs_secondary = [failure(exc, 'source-input-close')]
    if primary is not None:
        raise primary




def node_cleanup_wire_plan(route, env, inner):
    """Read-only known-metadata projection for ALL later Node cleanup outcomes.

    Uses the protected complete work-stage record, not a guessed filesystem
    pathname or an operator-selected budget. Actual cleanup rechecks identities.
    """
    need(type(inner) is dict and type(inner.get('observations')) is dict,
         'bound inner input facts before any destructive cleanup')
    facts = inner['observations'].get('nodeStage')
    check_node_stage(facts, route, env, after=True)
    root = node_stage_directory(route, env)
    def row(raw):
        need(type(raw) is list and len(raw) == 9 and all(type(x) is int and x >= 0 for x in raw),
             'typed known Node cleanup identity')
        return dict(zip(('dev', 'ino', 'mode', 'uid', 'gid', 'nlink', 'size', 'mtimeNs', 'ctimeNs'), raw))
    def future(raw):
        # Linux stat size/nlink are64-bit; timespec64 seconds *1e9 is<2**96.
        return {**raw, 'size': max(raw['size'], 2**64 - 1), 'nlink': max(raw['nlink'], 2**64 - 1),
                'mtimeNs': max(raw['mtimeNs'], 2**96 - 1), 'ctimeNs': max(raw['ctimeNs'], 2**96 - 1)}
    parent = future(row(facts['parents']['/run']['after']))
    directory = row(facts['directory'])
    private = future({**directory, 'mode': stat.S_IFDIR | 0o700})
    node, record = row(facts['file']), row(facts['record']['metadata'])
    gone = {'exists': False, 'errno': 2, 'identity': None}
    prototype = {'schema': 'bw.bochs-ring3.node-cleanup.v1', 'route': route, 'path': str(root),
        'parentBefore': parent, 'parentAfter': parent,
        'before': {'exists': True, 'errno': None, 'identity': directory},
        'heldBefore': directory, 'heldBeforeRmdir': private, 'namedBeforeRmdir': private,
        'members': {'node': node, 'stage.json': record}, 'after': gone,
        'firstFailure': None, 'secondary': [], 'complete': True, 'journal': [
            {'operation': 'chmod-private', 'path': str(root), 'before': directory, 'attempted': True,
             'after': {'exists': True, 'errno': None, 'identity': private}, 'firstFailure': None},
            {'operation': 'unlink', 'path': str(root / 'node'), 'before': node, 'attempted': True,
             'after': gone, 'firstFailure': None},
            {'operation': 'unlink', 'path': str(root / 'stage.json'), 'before': record, 'attempted': True,
             'after': gone, 'firstFailure': None},
            {'operation': 'rmdir', 'path': str(root), 'before': private, 'attempted': True,
             'after': gone, 'firstFailure': None}]}
    success_bytes = len(canonical(prototype))
    # First failure duplicates into its journal and top-level field, with at
    # most one held directory close secondary; every JSON-encoded error<=1024.
    # A failed after-read can retain one present-directory stat instead of ENOENT.
    failure_bytes = success_bytes + 3 * 1024 + 512
    return {'schema': 'bw.bochs-ring3.node-cleanup-plan.v1', 'nodePath': str(root),
        'stageSha256': sha256(canonical(facts)), 'projectionSha256': sha256(canonical(prototype)),
        'successBytes': success_bytes, 'failureBytes': failure_bytes,
        'reservedBytes': max(success_bytes + 1024, failure_bytes)}


CLEANUP_STAT_FIELDS = ('dev', 'ino', 'mode', 'uid', 'gid', 'nlink', 'size', 'mtimeNs', 'ctimeNs')


def compact_manual_stats(value):
    """Version2 wire only: preserve all nine stat integers in fixed order."""
    if type(value) is dict:
        if set(value) == set(CLEANUP_STAT_FIELDS) and all(type(x) is int for x in value.values()):
            return [value[key] for key in CLEANUP_STAT_FIELDS]
        return {key: compact_manual_stats(item) for key, item in value.items()}
    if type(value) is list:
        return [compact_manual_stats(item) for item in value]
    return value


def cleanup_owned_cgroups(route, env, inner, kernel, *, outer_base=None, input_plan=None,
                          following_error_bytes=0,
                          clock=time.monotonic_ns, sleep=time.sleep):
    """Adapt held V3 cleanup: whole-wire reserve, per-name FDs, finite post-leaf reads.

    This new unit/controller topology is distinct from the historical manual
    root. No old producer is imported, no caller-selected path or PID is used.
    """
    paths = route_paths(route, env)
    root = Path('/sys/fs/cgroup/system.slice') / paths['unit']
    allowed = {'controller'} | ({'configure', 'make'} if route == 'build' else
                                {'js', 'bochs'} if route == 'reference' else set())
    started = clock()
    last = started
    value = {'schema': 'bw.bochs-ring3.manual-cleanup.v2', 'identityFields': list(CLEANUP_STAT_FIELDS), 'route': route,
        'unit': paths['unit'], 'rootPath': str(root),
        'limits': {'samples': 6, 'seconds': 5, 'bytes': 16384},
        'startedNs': started, 'endedNs': None, 'known': {}, 'before': {},
        'parentIdentity': None, 'parentIdentityAfter': None, 'inputPlan': input_plan,
        'samples': [], 'journal': [], 'after': None, 'lastPath': None,
        'firstFailure': None, 'secondary': [], 'complete': False}
    fds = {}
    base = {} if outer_base is None else outer_base
    # Node cleanup follows established cgroup terminality. Derive its complete
    # all-outcome wire reserve rather than deleting before service quiet.
    integer(following_error_bytes, 0, 1024, 'one bounded later staged-input failure')
    node_reserve = ((input_plan['reservedBytes'] if input_plan is not None else 4096)
                    if base.get('nodeCleanup') is None else 0) + following_error_bytes
    def whole_size():
        return len(canonical({**base, 'manual': compact_manual_stats(value)})) + node_reserve
    def issue(exc, phase):
        row = failure(exc, phase, path=value['lastPath'])
        if value['firstFailure'] is None:
            value['firstFailure'] = row
        elif len(value['secondary']) < SECONDARY_LIMIT:
            value['secondary'].append(row)
        for extra in getattr(exc, 'bochs_secondary', []):
            if len(value['secondary']) < SECONDARY_LIMIT:
                value['secondary'].append(extra)
    def tick():
        nonlocal last
        now = clock()
        need(now >= last and now - started < 5000000000, 'strict finite monotonic cleanup deadline')
        last = now
        return now
    def five(row):
        return tuple(row[k] for k in ('dev', 'ino', 'mode', 'uid', 'gid'))
    def compact(row):
        return [row[k] for k in ('dev', 'ino', 'mode', 'uid', 'gid', 'nlink', 'size', 'mtimeNs', 'ctimeNs')]
    def path_of(role):
        return root if role == 'unit' else root / role
    def snapshot(path, destination):
        destination.update(path=str(path), exists=True, errno=None, identity=None, files={}, children=[])
        value['lastPath'] = str(path)
        try:
            destination['identity'] = kernel._directory(path)
        except FileNotFoundError as exc:
            need(exc.errno == 2, 'actual selected cgroup ENOENT')
            destination.update(exists=False, errno=2)
            return destination
        for name in ('cgroup.procs', 'cgroup.events', 'cgroup.stat'):
            value['lastPath'] = str(path / name)
            destination['files'][name] = kernel._read(path / name, 4096)
        with os.scandir(path) as entries:
            count = 0
            for entry in entries:
                count += 1
                need(count <= 128 and not entry.is_symlink(), 'bounded nonlink cleanup cgroup entry')
                if entry.is_dir(follow_symlinks=False):
                    destination['children'].append(entry.name)
                    need(len(destination['children']) <= len(allowed), 'bounded fixed cleanup children')
        destination['children'].sort()
        need(five(destination['identity']) == five(kernel._directory(path)), 'stable cleanup group identity')
        need(len(canonical(compact_manual_stats(destination))) <= 768, 'bounded selected cleanup sample')
        return destination
    def number(raw, key):
        values = [line.split(' ', 1)[1] for line in raw.splitlines() if line.startswith(key + ' ')]
        need(len(values) == 1 and re.fullmatch(r'0|[1-9][0-9]{0,18}', values[0]),
             'unique canonical cleanup counter ' + key)
        return int(values[0])
    def quiet(row, children):
        need(row['exists'] and row['children'] == children and row['files']['cgroup.procs'] == '' and
             number(row['files']['cgroup.events'], 'populated') == 0 and
             number(row['files']['cgroup.stat'], 'nr_descendants') == len(children),
             'empty selected cleanup group and exact known descendants')
    def check_fd(role):
        path = path_of(role)
        held = identity(os.fstat(fds[role])); named = kernel._directory(path)
        need(five(held) == five(named) == five(value['known'][role]['identity']),
             'exact held/named initial first-five cleanup authority')
        return held, named
    def reserve_whole(current_role, remaining_roles, remaining_samples):
        """Project every remaining row/terminal branch from typed known facts.

        Numeric mutable stat fields are bounded unsigned64 in this route. A
        failure stops mutations, so reserve the maximum of the complete-success
        and first-error-plus-all-close-error branches, never their impossible sum.
        """
        def bounded_stat(row):
            need(all(type(x) is int and 0 <= x <= 2**64 - 1 for x in row.values()),
                 'bounded raw numeric stat projection')
            return {**row, 'nlink': 2**64 - 1, 'size': 2**64 - 1,
                    'mtimeNs': 2**64 - 1, 'ctimeNs': 2**64 - 1}
        def gone(path):
            return {'path': str(path), 'exists': False, 'errno': 2, 'identity': None, 'files': {}, 'children': []}
        def future_group(role, *, dying=False):
            raw = json.loads(canonical(value['before'][role]))
            raw['identity'] = bounded_stat(raw['identity'])
            raw['children'] = []
            raw['files']['cgroup.procs'] = ''
            raw['files']['cgroup.events'] = 'populated 0\nfrozen 0\n'
            raw['files']['cgroup.stat'] = 'nr_descendants 0\nnr_dying_descendants ' + (
                '9999999999999999999' if dying else '0') + '\n'
            return raw
        future = json.loads(canonical(value))
        future['journal'][-1]['after'] = gone(path_of(current_role))
        future['journal'][-1]['childClosed'] = True
        for role in remaining_roles:
            before = future_group(role)
            parent = value['parentIdentity'] if role == 'unit' else value['known']['unit']['identity']
            future['journal'].append({'role': role, 'path': str(path_of(role)), 'before': before,
                'parentHeld': compact(bounded_stat(parent)), 'childHeld': compact(before['identity']),
                'parentNamed': compact(bounded_stat(parent)), 'childNamed': compact(before['identity']),
                'attempted': True, 'after': gone(path_of(role)), 'firstFailure': None, 'childClosed': True})
        for _index in range(remaining_samples):
            future['samples'].append({'ns': started + 4999999999,
                                      'root': future_group('unit', dying=True)})
        future.update(after=gone(root), parentIdentityAfter=bounded_stat(value['parentIdentity']),
                      endedNs=started + 4999999999, complete=True)
        success_bytes = len(canonical({**base, 'manual': compact_manual_stats(future), 'after': gone(root)})) + node_reserve
        # A cgroup error has a source-fixed <=128-byte path, <=64-byte phase/name
        # and <=512-byte JSON string message; <=1024 bytes per retained error.
        # Current row may duplicate its first error; each held FD closes once.
        # A manual failure leaves outside.after unknown. finish therefore does
        # not enter staged-input removal at all; do not reserve an impossible
        # later Node cleanup in addition to every manual-close failure.
        failure_bytes = len(canonical({**base, 'manual': compact_manual_stats(value)})) + (len(fds) + 3) * 1024 + 1024
        need(max(success_bytes, failure_bytes) <= 16384,
             'complete typed future cleanup/outer/error projection before first effect')
        return max(success_bytes, failure_bytes)
    def remove(role, remaining_roles, remaining_samples):
        path = path_of(role)
        parent_role = 'parent' if role == 'unit' else 'unit'
        parent_path = root.parent if role == 'unit' else root
        row = {'role': role, 'path': str(path), 'before': {}, 'parentHeld': None,
            'childHeld': None, 'parentNamed': None, 'childNamed': None,
            'attempted': False, 'after': None, 'firstFailure': None, 'childClosed': False}
        value['journal'].append(row)
        try:
            snapshot(path, row['before']); quiet(row['before'], [])
            need(number(row['before']['files']['cgroup.stat'], 'nr_dying_descendants') == 0,
                 'no dying selected group before rmdir')
            held, named = check_fd(role)
            parent_held = identity(os.fstat(fds[parent_role])); parent_named = kernel._directory(parent_path)
            expected_parent = value['parentIdentity'] if role == 'unit' else value['known']['unit']['identity']
            need(five(parent_held) == five(parent_named) == five(expected_parent),
                 'exact held/named removal parent first-five')
            row.update(parentHeld=compact(parent_held), childHeld=compact(held),
                       parentNamed=compact(parent_named), childNamed=compact(named))
            need(len(canonical(compact_manual_stats(row))) <= 1536, 'bounded complete removal row before mutation')
            tick()
            reserve_whole(role, remaining_roles, remaining_samples)
            row['attempted'] = True
            os.rmdir(path.name, dir_fd=fds[parent_role])
            row['after'] = {}; snapshot(path, row['after'])
            need(row['after']['exists'] is False, 'actual removed selected group absence')
        except BaseException as exc:
            row['firstFailure'] = failure(exc, 'owned-cgroup-rmdir', path=str(path))
            raise
        finally:
            # Release a removed leaf's reference before waiting for kernel dying
            # descendants to settle; retain any close error, never retry it.
            if row['attempted'] and row['after'] is not None and row['after'].get('exists') is False:
                fd = fds.pop(role)
                try:
                    os.close(fd); row['childClosed'] = True
                except BaseException as exc:
                    issue(exc, 'owned-cgroup-removed-close')
    try:
        if inner is not None and type(inner.get('resources')) is dict:
            before = inner['resources'].get('before')
            if type(before) is dict and before.get('schema') == 'bw.bochs-ring3.resources.v2':
                for role, key in (('unit', 'unitRoot'), ('controller', 'controller')):
                    row = before[key]
                    need(row['path'] == str(path_of(role)), 'source-bound initial cleanup role path')
                    value['known'][role] = {'path': str(path_of(role)), 'identity': row['directory']}
            for process in inner.get('phases', []):
                role, group = process.get('name'), process.get('cgroupBefore')
                if role in allowed and type(group) is dict and type(group.get('identity')) is dict:
                    need(group['path'] == str(path_of(role)), 'source-bound child cleanup path')
                    value['known'][role] = {'path': str(path_of(role)), 'identity': group['identity']}
        value['before']['unit'] = {}; snapshot(root, value['before']['unit'])
        top = value['before']['unit']
        if not top['exists']:
            value['after'] = dict(top)
        else:
            names = top['children']
            need('unit' in value['known'] and set(names) <= allowed and set(names) <= set(value['known']),
                 'no unknown selected cleanup role')
            quiet(top, names)
            value['parentIdentity'] = kernel._directory(root.parent)
            fds['parent'] = os.open(root.parent, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC)
            need(five(identity(os.fstat(fds['parent']))) == five(value['parentIdentity']), 'held fixed global parent')
            fds['unit'] = os.open(root.name, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC,
                                  dir_fd=fds['parent'])
            check_fd('unit')
            for role in names:
                fds[role] = os.open(role, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC,
                                    dir_fd=fds['unit'])
                check_fd(role)
                value['before'][role] = {}; snapshot(path_of(role), value['before'][role])
                quiet(value['before'][role], [])
                need(number(value['before'][role]['files']['cgroup.stat'], 'nr_dying_descendants') == 0,
                     'known child has no dying descendants before any removal')
            order = sorted(names)
            for index, role in enumerate(order):
                remove(role, [*order[index + 1:], 'unit'], 6)
                need(value['firstFailure'] is None, 'removed child close uncertainty stops further mutations')
            settled = False
            targets = (0, 100000000, 400000000, 1000000000, 2500000000, 4500000000)
            previous = tick()
            for target in targets:
                now = tick()
                if now < started + target:
                    sleep((started + target - now) / 1000000000)
                sample = {'ns': tick(), 'root': {}}
                value['samples'].append(sample)
                check_fd('unit'); snapshot(root, sample['root']); quiet(sample['root'], [])
                need(sample['ns'] >= previous and len(canonical(compact_manual_stats(sample))) <= 768,
                     'bounded ordered post-leaf root sample')
                previous = tick()
                if number(sample['root']['files']['cgroup.stat'], 'nr_dying_descendants') == 0:
                    settled = True; break
            need(settled, 'dying descendants remain at finite post-leaf limit')
            remove('unit', [], 0)
            value['after'] = {}; snapshot(root, value['after'])
            need(value['after']['exists'] is False, 'complete selected unit root absent')
    except BaseException as exc:
        issue(exc, 'owned-cgroup-cleanup')
    finally:
        if 'parent' in fds:
            try:
                value['parentIdentityAfter'] = identity(os.fstat(fds['parent']))
                need(five(value['parentIdentityAfter']) == five(value['parentIdentity']) ==
                     five(kernel._directory(root.parent)), 'held/named fixed parent after cleanup')
            except BaseException as exc:
                issue(exc, 'owned-cgroup-final-parent')
        for role in reversed(tuple(fds)):
            try:
                os.close(fds[role])
            except BaseException as exc:
                issue(exc, 'owned-cgroup-final-close-' + role)
        try:
            value['endedNs'] = tick()
        except BaseException as exc:
            value['endedNs'] = last; issue(exc, 'owned-cgroup-terminal-clock')
        if len(canonical({**base, 'manual': compact_manual_stats(value)})) + node_reserve > 16384:
            issue(Refusal('final complete cleanup envelope cap'), 'owned-cgroup-final-wire')
    value['complete'] = value['firstFailure'] is None and not value['secondary']
    return compact_manual_stats(value)


RESOURCE_FILES = ('cpu.max', 'memory.max', 'memory.swap.max', 'pids.max',
                  'cgroup.procs', 'cgroup.events', 'cgroup.stat', 'cpu.stat')



class HostRuntimeStage:
    """Transient root-owned selected library bodies; artifacts retain facts only."""
    def __init__(self, route, env, selected, structural):
        paths = route_paths(route, env)
        self.path = paths['work'].with_name(paths['work'].name.removesuffix('-work') + '-host-runtime')
        self.library = self.path / 'lib'
        self.route, self.selected, self.structural = route, selected, structural
        self.attempted = False
        self.facts = {'schema': 'bw.bochs-ring3.host-runtime-stage.v1', 'route': route,
            'path': str(self.path), 'metadataFields': list(CLEANUP_STAT_FIELDS),
            'selected': selected, 'selectedSha256': sha256(canonical(selected)), 'created': [],
            'parentBefore': None, 'parentAfter': None, 'directoryInitial': None,
            'libraryDirectoryInitial': None, 'directory': None, 'libraryDirectory': None,
            'files': {}, 'checkedAfter': None, 'lastOperation': None, 'failurePartial': None,
            'firstFailure': None, 'secondary': [], 'complete': False}
    @staticmethod
    def metadata(info):
        return [identity(info)[key] for key in CLEANUP_STAT_FIELDS]
    def error(self, exc, phase, path):
        item = failure(exc, phase, path=str(path))
        if self.facts['firstFailure'] is None:
            self.facts['firstFailure'] = item
        elif len(self.facts['secondary']) < SECONDARY_LIMIT:
            self.facts['secondary'].append(item)
        for item in getattr(exc, 'bochs_secondary', []):
            if len(self.facts['secondary']) < SECONDARY_LIMIT:
                self.facts['secondary'].append(item)
    def _directory(self, path, mode):
        row = safe_root_directory(path, mode=mode)
        return [row[key] for key in CLEANUP_STAT_FIELDS]
    def _raise(self):
        error = Refusal(self.facts['firstFailure']['message'])
        error.bochs_first = self.facts['firstFailure']
        error.bochs_secondary = self.facts['secondary']
        error.bochs_partial = {'hostRuntime': self.facts}
        raise error
    def copy(self):
        need(not self.attempted, 'host runtime staging consumed; no copy replay')
        self.attempted = True
        current = self.path
        try:
            need(os.getresuid() == os.getresgid() == (0, 0, 0), 'root-only immutable library staging')
            need(type(self.selected) is dict and 1 <= len(self.selected) <= 128 and
                 sum(row['bytes'] for row in self.selected.values()) <= 268435456,
                 'finite selected transient library extent')
            names = {}
            for source, row in self.selected.items():
                selected_tool_path(source)
                need(source in self.structural['files'] and row['uid'] == row['gid'] == 0 and
                     row['mode'] & 0o022 == 0 and row['bytes'] >= 64 and
                     self.structural['files'][source]['fileBytes'] == row['bytes'] and
                     self.structural['files'][source]['fileSha256'] == row['sha256'],
                     'source-selected library structural and full-file projection')
                structure = self.structural['files'][source]['structure']
                name = structure['soname'] or Path(source).name
                if Path(source).name.startswith('ld-linux-x86-64'):
                    name = 'ld-linux-x86-64.so.2'
                need(type(name) is str and re.fullmatch(r'[A-Za-z0-9+_.-]{1,255}', name) and
                     name not in ('.', '..') and name not in names, 'one unique safe staged library SONAME')
                names[name] = source
            self.facts['parentBefore'] = self._directory(Path('/run'), 0o755)
            os.mkdir(self.path, 0o700); self.facts['created'].append(str(self.path))
            self.facts['directoryInitial'] = self._directory(self.path, 0o700)
            os.mkdir(self.library, 0o700); self.facts['created'].append(str(self.library))
            self.facts['libraryDirectoryInitial'] = self._directory(self.library, 0o700)
            for name, source in sorted(names.items()):
                current = self.library / name
                self.facts['lastOperation'] = {'operation': 'source-read', 'path': source}
                raw, observed = read_regular(source, 134217728, minimum=64)
                chosen = self.selected[source]
                need(len(raw) == chosen['bytes'] and sha256(raw) == chosen['sha256'] and
                     observed['before']['mode'] == chosen['mode'], 'actual library source bytes equal selection')
                value = {'sourcePath': source, 'member': str(current),
                    'sourceBefore': [observed['before'][key] for key in CLEANUP_STAT_FIELDS],
                    'sourceAfter': [observed['after'][key] for key in CLEANUP_STAT_FIELDS],
                    'sourceNamed': [observed['named'][key] for key in CLEANUP_STAT_FIELDS],
                    'bytesCopied': 0, 'copiedSha256': None, 'readback': None,
                    'publicationAttempted': False, 'published': None, 'named': None,
                    'targetAfterFailure': None, 'structure': None, 'firstFailure': None, 'secondary': []}
                self.facts['files'][source] = value
                self.facts['lastOperation'] = {'operation': 'exclusive-copy', 'path': str(current)}
                fd = None
                primary = None
                try:
                    fd = os.open(current, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW | os.O_CLOEXEC, 0o600)
                    self.facts['created'].append(str(current))
                    os.fchmod(fd, 0o600)
                    before = os.fstat(fd)
                    need(stat.S_ISREG(before.st_mode) and before.st_uid == before.st_gid == 0 and
                         before.st_nlink == 1 and before.st_size == 0, 'new private single-link library target')
                    for offset in range(0, len(raw), 65536):
                        part = raw[offset:offset + 65536]
                        count = os.write(fd, part)
                        need(type(count) is int and 0 <= count <= len(part), 'bounded library copy count')
                        value['bytesCopied'] += count
                        need(count == len(part), 'library short write refuses publication')
                    os.fsync(fd)
                    value['copiedSha256'] = sha256(raw)
                except BaseException as exc:
                    primary = exc
                    value['firstFailure'] = failure(exc, 'host-library-copy', path=str(current))
                    if fd is not None:
                        try:
                            value['targetAfterFailure'] = self.metadata(os.fstat(fd))
                        except BaseException as extra:
                            value['secondary'].append(failure(extra, 'host-library-failed-stat'))
                finally:
                    if fd is not None:
                        try:
                            os.close(fd)
                        except BaseException as exc:
                            if primary is None:
                                primary = exc; value['firstFailure'] = failure(exc, 'host-library-copy-close')
                            else:
                                value['secondary'].append(failure(exc, 'host-library-copy-close'))
                if primary is not None:
                    primary.bochs_secondary = value['secondary']
                    raise primary
                again, reopened = read_regular(current, 134217728, minimum=64)
                need(again == raw and sha256(again) == chosen['sha256'], 'independent full staged library reopen/hash')
                structural = sparse_elf(again)
                need(structural == self.structural['files'][source], 'exact current staged structural ranges')
                value['structure'] = structural['structure']
                value['readback'] = {'bytes': len(again), 'sha256': sha256(again),
                    **{key: [reopened[key][field] for field in CLEANUP_STAT_FIELDS]
                       for key in ('before', 'after', 'named')}}
                value['publicationAttempted'] = True
                self.facts['lastOperation'] = {'operation': 'readonly-publication', 'path': str(current)}
                publish_root_mode(current, 0o555 if name == 'ld-linux-x86-64.so.2' else 0o444)
                value['published'] = self.metadata(os.lstat(current))
                value['named'] = self.metadata(os.stat(current, follow_symlinks=False))
                need(value['published'] == value['named'] and value['published'][:2] ==
                     value['readback']['before'][:2], 'same immutable library after publication')
            publish_root_mode(self.library, 0o555, directory=True)
            self.facts['libraryDirectory'] = self._directory(self.library, 0o555)
            publish_root_mode(self.path, 0o555, directory=True)
            self.facts['directory'] = self._directory(self.path, 0o555)
            self.facts['parentAfter'] = self._directory(Path('/run'), 0o755)
            need(self.facts['parentBefore'][:5] == self.facts['parentAfter'][:5] and
                 len(canonical(self.facts)) <= 1048576, 'bounded host runtime stage and fixed parent')
            self.facts['complete'] = True
        except BaseException as exc:
            self.facts['failurePartial'] = getattr(exc, 'bochs_partial', None)
            self.error(exc, 'host-runtime-staging', (self.facts['lastOperation'] or {}).get('path', current))
            if current != self.path and str(current) in self.facts['created']:
                try:
                    target = self.metadata(os.lstat(current))
                    for row in self.facts['files'].values():
                        if row['member'] == str(current):
                            row['targetAfterFailure'] = target
                except BaseException as extra:
                    self.error(extra, 'host-runtime-failed-target-stat', current)
        if self.facts['firstFailure'] is not None:
            self._raise()
        return self.facts
    def verify_after(self):
        need(self.facts['complete'], 'complete immutable host library stage before after-check')
        checks = {}
        self.facts['checkedAfter'] = checks
        current = self.path
        try:
            for source, row in self.facts['files'].items():
                current = Path(row['member'])
                self.facts['lastOperation'] = {'operation': 'after-full-readback', 'path': str(current)}
                raw, observed = read_regular(current, 134217728, minimum=64)
                need(len(raw) == self.selected[source]['bytes'] and sha256(raw) == self.selected[source]['sha256'] and
                     [observed['before'][key] for key in CLEANUP_STAT_FIELDS] == row['published'],
                     'same fully hashed immutable library after work')
                structure = sparse_elf(raw)
                need(structure == self.structural['files'][source], 'same exact structural library after work')
                checks[source] = {'bytes': len(raw), 'sha256': sha256(raw),
                    **{key: [observed[key][field] for field in CLEANUP_STAT_FIELDS]
                       for key in ('before', 'after', 'named')}, 'structure': structure['structure']}
            need(self._directory(self.path, 0o555)[:5] == self.facts['directory'][:5] and
                 self._directory(self.library, 0o555)[:5] == self.facts['libraryDirectory'][:5],
                 'same host runtime staging directories after work')
        except BaseException as exc:
            self.facts['failurePartial'] = getattr(exc, 'bochs_partial', None)
            self.error(exc, 'host-runtime-after-readback', current)
            self.facts['complete'] = False
            self._raise()
        return self.facts



def host_runtime_path(route, env):
    work = route_paths(route, env)['work']
    return work.with_name(work.name.removesuffix('-work') + '-host-runtime')


def plan_host_runtime_cleanup(stage, route, env):
    """Read-only exact directory/member plan before ANY cleanup mutation."""
    root = host_runtime_path(route, env); library = root / 'lib'
    need(type(stage) is dict and stage.get('schema') == 'bw.bochs-ring3.host-runtime-stage.v1' and
         stage.get('route') == route and stage.get('path') == str(root) and
         stage.get('complete') is True and stage.get('firstFailure') is None and not stage.get('secondary'),
         'complete bound host runtime stage for cleanup plan')
    need(type(stage['files']) is dict and 1 <= len(stage['files']) <= 128 and
         type(stage['checkedAfter']) is dict and set(stage['checkedAfter']) == set(stage['files']),
         'complete staged after-readback roster')
    def meta(info): return HostRuntimeStage.metadata(info)
    def close_readonly_plan_fd(fd, primary):
        try:
            os.close(fd)
        except BaseException as exc:
            if primary is None:
                raise
            primary.bochs_secondary = [*getattr(primary, 'bochs_secondary', []),
                failure(exc, 'host-runtime-plan-close')][:SECONDARY_LIMIT]
    def check_dir(path, expected):
        fd = os.open(path, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC)
        primary = None
        try:
            held, named = meta(os.fstat(fd)), meta(os.lstat(path))
            need(held == named == expected and held[2:5] == [stat.S_IFDIR | 0o555, 0, 0],
                 'exact readonly held/named library directory plan')
            return held
        except BaseException as exc:
            primary = exc
            raise
        finally:
            close_readonly_plan_fd(fd, primary)
    root_row = check_dir(root, stage['directory'])
    lib_row = check_dir(library, stage['libraryDirectory'])
    with os.scandir(root) as entries:
        names = []
        for entry in entries:
            names.append(entry.name)
            need(names == ['lib'] and entry.is_dir(follow_symlinks=False) and not entry.is_symlink(),
                 'only known library child directory in staged root')
    expected = {Path(row['member']).name for row in stage['files'].values()}
    need(len(expected) == len(stage['files']), 'unique source-derived staged file names')
    with os.scandir(library) as entries:
        found = set()
        for entry in entries:
            need(entry.name in expected and entry.name not in found and not entry.is_symlink(),
                 'no unknown or linked staged library member')
            found.add(entry.name)
            need(len(found) <= 128, 'bounded staged cleanup member census')
    need(found == expected, 'complete staged member census before any effect')
    members = {}
    for source, row in stage['files'].items():
        path = Path(row['member'])
        need(path.parent == library and path.name not in ('.', '..') and
             re.fullmatch(r'[A-Za-z0-9+_.-]{1,255}', path.name), 'fixed safe staged member path')
        fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC)
        primary = None
        try:
            held, named = meta(os.fstat(fd)), meta(os.lstat(path))
            need(held == named == row['published'] and held[3:7] == [0, 0, 1, stage['selected'][source]['bytes']] and
                 held[2] == stat.S_IFREG | (0o555 if path.name == 'ld-linux-x86-64.so.2' else 0o444),
                 'exact owned readonly file identity before cleanup')
            members[source] = {'member': str(path), 'identity': held}
        except BaseException as exc:
            primary = exc
            raise
        finally:
            close_readonly_plan_fd(fd, primary)
    plan = {'schema': 'bw.bochs-ring3.host-runtime-cleanup-plan.v1', 'route': route,
        'path': str(root), 'stageSha256': sha256(canonical(stage)),
        'parent': [safe_root_directory('/run')[key] for key in CLEANUP_STAT_FIELDS],
        'directory': root_row, 'libraryDirectory': lib_row, 'members': members,
        'cleanupReservedBytes': 0, 'roleReservedBytes': 0}
    # Each before-row is checked <=1536 bytes. An after-stat/absence or one
    # <=1024-byte encoded effect error fits a4096-byte row. Reserve8192 more
    # for top primary, at most four held-FD close errors and terminal fields.
    # This is a separate <=1MiB data role; only its fixed hash ref enters16KiB.
    plan['cleanupReservedBytes'] = len(canonical(plan)) + (len(members) + 4) * 4096 + 8192
    plan['roleReservedBytes'] = len(canonical({'schema': 'bw.bochs-ring3.host-runtime-original.v1',
                                              'stage': stage, 'cleanup': None})) + plan['cleanupReservedBytes']
    need(plan['roleReservedBytes'] <= 1048576, 'whole host runtime stage/cleanup role reserve')
    return plan


def cleanup_host_runtime(stage, plan, route, env):
    root = host_runtime_path(route, env); library = root / 'lib'
    need(plan['path'] == str(root) and plan['stageSha256'] == sha256(canonical(stage)),
         'bound readonly host runtime cleanup plan')
    value = {'schema': 'bw.bochs-ring3.host-runtime-cleanup.v1', 'route': route,
        'path': str(root), 'plan': plan, 'journal': [], 'after': None,
        'parentAfter': None, 'firstFailure': None, 'secondary': [], 'complete': False}
    fds = {}
    def meta(info): return HostRuntimeStage.metadata(info)
    def issue(exc, phase):
        item = failure(exc, phase)
        if value['firstFailure'] is None: value['firstFailure'] = item
        elif len(value['secondary']) < SECONDARY_LIMIT: value['secondary'].append(item)
    def named(name, parent_fd):
        return meta(os.stat(name, dir_fd=parent_fd, follow_symlinks=False))
    def check(role, name, parent, expected):
        held, entry = meta(os.fstat(fds[role])), named(name, fds[parent])
        need(held[:5] == entry[:5] == expected[:5], 'same held/named cleanup first-five')
        return held, entry
    def effect(operation, path, before, action, after):
        row = {'operation': operation, 'path': str(path), 'before': before, 'attempted': False,
               'after': None, 'firstFailure': None}
        value['journal'].append(row)
        need(len(canonical(row)) <= 1536 and
             len(canonical(value)) + (len(stage['files']) + 4 - len(value['journal'])) * 4096 + 8192
             <= plan['cleanupReservedBytes'], 'whole remaining host cleanup witness before mutation')
        row['attempted'] = True
        try:
            action(); row['after'] = after()
        except BaseException as exc:
            row['firstFailure'] = failure(exc, 'host-runtime-cleanup-' + operation, path=str(path))
            raise
    def absent(path):
        try: os.lstat(path)
        except FileNotFoundError as exc:
            need(exc.errno == 2, 'actual staged input ENOENT')
            return {'exists': False, 'errno': 2}
        raise Refusal('removed staged library input remains named')
    try:
        fds['parent'] = os.open('/run', os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC)
        need(meta(os.fstat(fds['parent']))[:5] == plan['parent'][:5] and
             meta(os.lstat('/run'))[:5] == plan['parent'][:5], 'held fixed host-input parent')
        fds['root'] = os.open(root.name, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC,
                              dir_fd=fds['parent'])
        check('root', root.name, 'parent', plan['directory'])
        fds['lib'] = os.open('lib', os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC,
                             dir_fd=fds['root'])
        check('lib', 'lib', 'root', plan['libraryDirectory'])
        for role, path, parent, name, expected in (
                ('root', root, 'parent', root.name, plan['directory']),
                ('lib', library, 'root', 'lib', plan['libraryDirectory'])):
            held, entry = check(role, name, parent, expected)
            effect('chmod-private', path, {'held': held, 'named': entry},
                   lambda role=role: os.fchmod(fds[role], 0o700),
                   lambda role=role: meta(os.fstat(fds[role])))
        private_root = meta(os.fstat(fds['root'])); private_lib = meta(os.fstat(fds['lib']))
        need(private_root[2:5] == private_lib[2:5] == [stat.S_IFDIR | 0o700, 0, 0],
             'same privately writable owned staged directories')
        for source, item in sorted(plan['members'].items()):
            path = Path(item['member']); fd = None
            try:
                check('lib', 'lib', 'root', private_lib)
                fd = os.open(path.name, os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC, dir_fd=fds['lib'])
                held, entry = meta(os.fstat(fd)), named(path.name, fds['lib'])
                need(held == entry == item['identity'], 'same exact known library before unlink')
                effect('unlink', path, {'held': held, 'named': entry,
                    'parentHeld': meta(os.fstat(fds['lib'])), 'parentNamed': named('lib', fds['root'])},
                    lambda path=path: os.unlink(path.name, dir_fd=fds['lib']), lambda path=path: absent(path))
            except BaseException as exc:
                # Record the effect/read failure before closing its held FD.
                # A close failure is secondary even when both edges fail.
                issue(exc, 'host-runtime-cleanup')
                exc.bochs_host_retained = True
                raise
            finally:
                if fd is not None:
                    try: os.close(fd)
                    except BaseException as exc: issue(exc, 'host-runtime-member-close')
            need(value['firstFailure'] is None, 'input close uncertainty stops later deletion')
        for role, path, parent, name, expected in (
                ('lib', library, 'root', 'lib', private_lib),
                ('root', root, 'parent', root.name, private_root)):
            held, entry = check(role, name, parent, expected)
            with os.scandir(path) as entries:
                need(next(entries, None) is None, 'empty known staged directory before rmdir')
            effect('rmdir', path, {'held': held, 'named': entry,
                'parentHeld': meta(os.fstat(fds[parent])), 'parentNamed': meta(os.lstat(path.parent))},
                lambda name=name, parent=parent: os.rmdir(name, dir_fd=fds[parent]), lambda path=path: absent(path))
            fd = fds.pop(role)
            try: os.close(fd)
            except BaseException as exc: issue(exc, 'host-runtime-directory-close')
            need(value['firstFailure'] is None, 'directory close uncertainty stops later removal')
        value['after'] = absent(root)
        value['parentAfter'] = meta(os.fstat(fds['parent']))
        need(value['parentAfter'][:5] == plan['parent'][:5] == meta(os.lstat('/run'))[:5],
             'fixed staged-input parent after cleanup')
    except BaseException as exc:
        if not getattr(exc, 'bochs_host_retained', False):
            issue(exc, 'host-runtime-cleanup')
    finally:
        for role in reversed(tuple(fds)):
            try: os.close(fds[role])
            except BaseException as exc: issue(exc, 'host-runtime-final-close-' + role)
    if len(canonical(value)) > plan['cleanupReservedBytes']:
        issue(Refusal('final host runtime cleanup wire overflow'), 'host-runtime-cleanup-wire')
    value['complete'] = value['firstFailure'] is None and not value['secondary']
    return value


class LiveOps:
    """Source-owned ordinary/kernel edges. No observed tool is a metadata probe.

    Construction does not read kernel state; admitted source/context precedes
    every call. Compiler/reference methods are connected separately below.
    """
    def __init__(self, route, context, paths):
        self.route, self.context, self.paths = route, context, paths
        self.env = context['env']
        self.invoker = context['invoker']
        self.started_ns = time.monotonic_ns()
        self.unit_path = Path('/sys/fs/cgroup/system.slice') / paths['unit']
        self.child = None
        if route in ('build', 'reference'):
            self.child = ChildProcessProvider(route, {
                'PATH': '/usr/bin:/bin', 'LANG': 'C', 'LC_ALL': 'C',
                'HOME': str(paths['work'] / 'home'), 'TMPDIR': str(paths['work'] / 'tmp'),
                'CC': TOOL_PATHS['gcc'], 'CXX': TOOL_PATHS['g++'], 'CFLAGS': '-O2', 'CXXFLAGS': '-O2'},
                self.invoker['uid'], self.invoker['gid'], paths['work'], self.unit_path)
            self.kernel = self.child.kernel
        else:
            self.kernel = ChildKernel(self.unit_path, paths['work'])
        self.stage = None
        self.host_stage = None
        self.current_structural = None
        self.last_graph = None
        self.upstream_record = None
    def source(self, selected, env):
        return observe_source(self.context['sourceRoot'], selected, env, self.context['workflowRoot'])
    def read(self, path, cap, **kwargs):
        return read_regular(path, cap, **kwargs)
    def _group(self, path):
        before = self.kernel._directory(path)
        files = {name: self.kernel._read(path / name, 4096) for name in RESOURCE_FILES}
        children = []
        with os.scandir(path) as entries:
            count = 0
            for entry in entries:
                count += 1
                need(count <= 128 and not entry.is_symlink(), 'bounded ordinary cgroup entries')
                if entry.is_dir(follow_symlinks=False):
                    children.append(entry.name)
                    need(len(children) <= 5, 'finite fixed cgroup children')
        need(self.kernel._first_five(before) == self.kernel._first_five(self.kernel._directory(path)),
             'resource cgroup directory first-five identity')
        return {'path': str(path), 'directory': before, 'files': files, 'children': sorted(children)}
    def resources(self, route):
        need(route == self.route, 'source-selected resource route')
        pid = os.getpid()
        need(os.getresuid() == os.getresgid() == (0, 0, 0), 'root service actual credentials')
        limits = LIMITS[route]
        expected = {'cpu.max': '100000 100000\n', 'memory.max': str(limits['memoryBytes']) + '\n',
                    'memory.swap.max': '0\n', 'pids.max': str(limits['tasks']) + '\n'}
        # Read the actual selected unit envelope before enabling controllers or
        # touching observed tool/cache/source inputs.
        for name, text in expected.items():
            need(self.kernel._read(self.unit_path / name, 4096) == text,
                 'actual selected finite root unit limit ' + name)
        if self.kernel.delegation is None:
            self.kernel.prepare_delegation(pid)
        parent = self.kernel.parent_control()
        root = self._group(self.unit_path)
        control = self._group(self.unit_path / 'controller')
        allowed = {'controller'} | (set() if self.child is None else self.child.used)
        need(set(root['children']) <= allowed and 'controller' in root['children'] and
             not control['children'] and root['files']['cgroup.procs'] == '' and
             control['files']['cgroup.procs'] == str(pid) + '\n', 'fixed unit/controller membership')
        need(all(root['files'][name] == text for name, text in expected.items()),
             'held actual unit resource limits')
        raw_cgroup = self.kernel._read(Path('/proc') / str(pid) / 'cgroup', 16384)
        need(raw_cgroup == '0::/system.slice/' + self.paths['unit'] + '/controller\n',
             'actual root observer controller membership')
        return {'schema': 'bw.bochs-ring3.resources.v2', 'unit': self.paths['unit'],
            'pid': pid, 'uid': os.getuid(), 'gid': os.getgid(), 'unitRoot': root, 'controller': control,
            'procCgroup': raw_cgroup,
            'procStat': self.kernel._read(Path('/proc') / str(pid) / 'stat', 16384),
            'procStatus': self.kernel._read(Path('/proc') / str(pid) / 'status', 16384),
            'parentControl': parent}
    def node_stage(self):
        for name in ('home', 'tmp'):
            caller_directory(self.paths['work'] / name, self.invoker['uid'], self.invoker['gid'])
        need(self.stage is None, 'source-owned one Node stage')
        stage_type = NodeStageCopy if self.route == 'toolchain' else NodeStageCopyV2
        extra = {} if self.route == 'toolchain' else {'bootstrap': self.context['bootstrapCredentials']}
        self.stage = stage_type(self.route, self.env, (self.invoker['uid'], self.invoker['gid']), **extra)
        return self.stage.copy()
    def node_after(self, *, full_hash):
        need(self.stage is not None, 'Node stage exists before after-readback')
        return self.stage.verify_after(full_hash=full_hash)
    def toolchain(self):
        need(self.stage is not None and self.stage.facts['elf'] is not None,
             'verified staged Node before selected tool data inventory')
        self.last_graph = observe_toolchain(node_elf=self.stage.facts['elf'])
        return self.last_graph
    def elf_metadata(self, graph):
        need(self.stage is not None and self.stage.sparse_node is not None,
             'actual staged Node structural input before library metadata')
        result = {'schema': 'bw.bochs-ring3.runtime-elf-metadata.v1',
                  'files': {NODE_PATH: self.stage.sparse_node}, 'rawBytes': 0}
        self.structural_file_bytes_read = 0
        for path in sorted(runtime_elf_candidates(graph)):
            raw, _observed = read_regular(path, 134217728, minimum=64)
            self.structural_file_bytes_read += len(raw)
            need(len(raw) == graph['files'][path]['bytes'] and sha256(raw) == graph['files'][path]['sha256'],
                 'current selected system library full-file readback before sparse capture')
            result['files'][path] = sparse_elf(raw)
        result['rawBytes'] = sum(row['bytes'] for value in result['files'].values() for row in value['ranges'])
        self.current_structural = admit_runtime_elf_metadata(result, graph, self.stage.facts)
        return self.current_structural
    def host_runtime_stage(self, graph, structural):
        need(self.host_stage is None, 'one transient host runtime stage')
        projected = expected_graph(graph)
        selected = {path: projected['files'][path] for path in runtime_elf_candidates(graph)}
        self.host_stage = HostRuntimeStage(self.route, self.env, selected, structural)
        return self.host_stage.copy()
    def host_runtime_after(self):
        need(self.host_stage is not None, 'current host runtime stage before after-check')
        return self.host_stage.verify_after()
    def runtime_bundle(self, request, upstream):
        need(self.host_stage is not None and self.host_stage.facts['complete'] and
             self.current_structural is not None, 'verified transient library input before packaging')
        root = self.paths['work'] / 'selected-source' / 'bochs'
        binary, _observed = read_regular(root / 'bochs', 33554432, minimum=64,
            owner=self.invoker['uid'], group=self.invoker['gid'])
        rom, fixture = authored_inputs()
        files = self.upstream_payloads
        notices = {
            'notices/bochs-selected-corresponding-source.tar.gz': upstream['sourceArchive'],
            'notices/vgabios-corresponding-source.tar.gz': upstream['correspondingSourceRaw']}
        for name in ('COPYING', 'README', 'config.guess', 'config.sub'):
            path = 'bochs/' + name
            need(path in files and files[path], 'selected Bochs source/component notice ' + path)
            notices['notices/bochs/' + name] = files[path]
        notices['notices/vgabios/README'] = files['bochs/bios/VGABIOS-lgpl-README']
        with tarfile.open(fileobj=io.BytesIO(upstream['correspondingSourceRaw']), mode='r:gz') as archive:
            for name in ('COPYING', 'README'):
                member = archive.getmember('vgabios-0.8a/' + name)
                need(member.isreg() and 1 <= member.size <= 262144, 'bounded reviewed VGA notice')
                handle = archive.extractfile(member)
                need(handle is not None, 'retained corresponding-source notice handle')
                with handle:
                    data = handle.read(262145)
                need(len(data) == member.size, 'complete corresponding-source notice')
                notices['notices/vgabios/source-' + name] = data
        for path, (_canonical_path, raw) in self.notices().items():
            notices['notices/runtime/' + path.lstrip('/').replace('/', '_')] = raw
        return assemble_runtime_v2(request['source'], binary, rom, fixture, files[VGA_PATH],
            host_node=node_expectation(self.stage.facts), selected=expected_graph(self.last_graph),
            structural=self.current_structural, notices=notices)
    def notices(self):
        need(self.last_graph is not None, 'notice identities selected by current tool graph')
        result = {}
        for source_path in NOTICE_PATHS:
            aliases, directories = {}, {}
            path = resolve_tool(source_path, aliases, directories)
            raw, _record = read_regular(path, 262144, minimum=1)
            selected = self.last_graph['files'].get(path)
            need(selected is not None and selected['bytes'] == len(raw) and selected['sha256'] == sha256(raw),
                 'notice raw bytes equal observed selected graph')
            result[source_path] = (path, raw)
        return result
    def observer(self, value):
        function = observer_facts_v2 if self.route == 'toolchain-v2' else observer_facts
        extra = {'invoker': self.invoker, 'bootstrap': self.context['bootstrapCredentials']} if self.route == 'toolchain-v2' else {}
        return function(value, self.env, pid=os.getpid(), uid=os.getuid(), gid=os.getgid(),
                        started_ns=self.started_ns, ended_ns=time.monotonic_ns(), **extra)
    def _selected_upstream_readback(self):
        result = {}
        for row in self.selected_rows['rows']:
            if not row['included']:
                continue
            path = self.paths['work'] / 'selected-source' / row['path']
            raw, observed = read_regular(path, 16777216, minimum=0,
                owner=self.invoker['uid'], group=self.invoker['gid'])
            need(len(raw) == row['bytes'] and
                 hashlib.sha1(b'blob ' + str(len(raw)).encode() + b'\0' + raw).hexdigest() == row['gitBlob'] and
                 stat.S_IMODE(observed['before']['mode']) == int(row['mode'], 8) & 0o777,
                 'current selected upstream Git/data readback ' + row['path'])
            result[row['path']] = {'mode': row['mode'], 'gitBlob': row['gitBlob'],
                'bytes': len(raw), 'sha256': sha256(raw), 'observation': observed}
        return {'schema': 'bw.bochs-ring3.upstream-source.v1', 'repository': UPSTREAM,
            'commit': UPSTREAM_COMMIT, 'tree': UPSTREAM_TREE,
            'sourceSelectionSha256': SOURCE_SELECTION_SHA256, 'files': result}
    def upstream(self, selected):
        need(self.upstream_record is None, 'selected source acquisition once')
        # A source-owned durable marker precedes every source payload acquisition.
        sealed_write(self.paths['work'] / 'source-attempt.original.json', canonical({
            'schema': 'bw.bochs-ring3.source-attempt.v1', 'commit': UPSTREAM_COMMIT,
            'tree': UPSTREAM_TREE, 'selectionSha256': SOURCE_SELECTION_SHA256}), 4096)
        tree_raw = source_http('https://api.github.com/repos/' + UPSTREAM + '/git/trees/' +
                               UPSTREAM_TREE + '?recursive=1', 4194304)
        tree = raw_object(tree_raw, 4194304)
        self.selected_rows = selected_source_rows(tree)
        root = self.paths['work'] / 'selected-source'
        caller_directory(root, self.invoker['uid'], self.invoker['gid'])
        directories = {root}
        files, modes = {}, {}
        aggregate = 0
        for row in self.selected_rows['rows']:
            if not row['included']:
                continue  # No payload request or extraction for excluded firmware/tools.
            raw = source_http('https://raw.githubusercontent.com/' + UPSTREAM + '/' +
                              UPSTREAM_COMMIT + '/' + row['path'], 16777216, minimum=0)
            aggregate += len(raw)
            need(aggregate <= 33554432 and len(raw) == row['bytes'] and
                 hashlib.sha1(b'blob ' + str(len(raw)).encode() + b'\0' + raw).hexdigest() == row['gitBlob'],
                 'exact included Git blob bytes ' + row['path'])
            target = root / row['path']
            for parent in reversed(target.parents):
                if parent == root or root in parent.parents:
                    if parent not in directories:
                        caller_directory(parent, self.invoker['uid'], self.invoker['gid'])
                        directories.add(parent)
            mode = int(row['mode'], 8) & 0o777
            caller_file(target, raw, mode, self.invoker['uid'], self.invoker['gid'])
            files[row['path']], modes[row['path']] = raw, mode
        need(len(files[VGA_PATH]) == VGA_BYTES and sha256(files[VGA_PATH]) == VGA_SHA256,
             'selected LGPL VGA bytes equal corresponding-source reviewed resource')
        source_raw = source_http(VGA_SOURCE_URL, VGA_SOURCE_BYTES)
        need(len(source_raw) == VGA_SOURCE_BYTES and sha256(source_raw) == VGA_SOURCE_SHA256,
             'exact reviewed complete corresponding-source archive')
        selected_vga = copying = None
        with tarfile.open(fileobj=io.BytesIO(source_raw), mode='r:gz') as archive:
            members = archive.getmembers()
            need(len(members) == 31 and sum(x.size for x in members) <= 1048576 and
                 all(x.isdir() or x.isreg() for x in members) and
                 len({x.name for x in members}) == len(members), 'bounded reviewed source TAR census')
            for member in members:
                member_name(member.name.rstrip('/'))
                if member.name in ('vgabios-0.8a/VGABIOS-lgpl-latest.bin', 'vgabios-0.8a/COPYING'):
                    handle = archive.extractfile(member)
                    need(handle is not None, 'selected corresponding-source regular member')
                    try:
                        data = handle.read(1048577)
                    finally:
                        handle.close()
                    need(len(data) == member.size <= 1048576, 'bounded complete selected source member')
                    if member.name.endswith('/COPYING'):
                        copying = data
                    else:
                        selected_vga = data
        need(selected_vga == files[VGA_PATH] and copying is not None and
             sha256(copying) == VGA_LICENSE_SHA256, 'exact source correspondence and retained LGPL notice')
        archive_raw = source_archive(files, modes)
        before = self._selected_upstream_readback()
        self.upstream_record = {'tree': tree, 'before': before,
            'correspondingSource': selected['vga']['correspondingSource'],
            'sourceArchive': archive_raw, 'correspondingSourceRaw': source_raw}
        self.upstream_payloads = files
        return self.upstream_record
    def upstream_after(self):
        need(self.upstream_record is not None, 'acquired source before final readback')
        return self._selected_upstream_readback()
    def generated_headers(self):
        root = self.paths['work'] / 'selected-source' / 'bochs'
        config = read_regular(root / 'config.h', 1048576, minimum=1,
            owner=self.invoker['uid'], group=self.invoker['gid'])[0]
        version = read_regular(root / 'bxversion.h', 16384, minimum=1,
            owner=self.invoker['uid'], group=self.invoker['gid'])[0]
        return config, version
    def acquire_build(self, selected, *, pull_request):
        need(self.route == 'reference' and not getattr(self, 'build_intake_attempted', False),
             'one Reference-only Build intake')
        self.build_intake_attempted = True
        token = os.environ.get('GH_TOKEN')
        need(type(token) is str and token, 'trusted secret-only owned Build intake credential')
        base = 'https://api.github.com/repos/' + REPOSITORY + '/actions/'
        self.build_intake_partial = {'schema': 'bw.bochs-ring3.build-intake-partial.v1',
            'selected': selected, 'completedMetadata': {}, 'lastMetadata': None,
            'archiveAttempted': False, 'complete': False}
        def metadata(name):
            self.build_intake_partial['lastMetadata'] = name
            raw = source_http(base + name, 1048576, token=token)
            # Retain each completed byte witness even if the next metadata read
            # refuses. Response bodies/redirect URLs and token values stay out.
            self.build_intake_partial['completedMetadata'][name] = {
                'bytes': len(raw), 'sha256': sha256(raw)}
            need(token.encode('utf-8') not in raw, 'secret value absent from retained API facts')
            return raw_object(raw, 1048576)
        # API metadata precedes the sole archive GET. The independently selected
        # request/log/digest remains the external authority; this is readback.
        run = metadata('runs/' + selected['runId'])
        job = metadata('jobs/' + str(selected['jobId']))
        artifact = metadata('artifacts/' + str(selected['artifactId']))
        listing = metadata('runs/' + selected['runId'] + '/artifacts?per_page=100')
        need(token not in canonical([run, job, artifact, listing]).decode('utf-8'),
             'secret value is never retained from API data')
        repository, head_repository = run['repository'], run['head_repository']
        integer(repository['id'], 1, 2 ** 63 - 1, 'official positive repository identity')
        integer(head_repository['id'], 1, 2 ** 63 - 1, 'official positive head-repository identity')
        need(repository['full_name'] == head_repository['full_name'] == REPOSITORY and
             repository['fork'] is False and head_repository['fork'] is False and
             repository['id'] == head_repository['id'], 'owned nonfork Build repository/head-repository readback')
        integer(pull_request, 1, 1000000, 'source-bound selected PR identity')
        prs = run['pull_requests']
        need(type(prs) is list and len(prs) == 1 and type(prs[0]['number']) is int and
             prs[0]['number'] == pull_request and prs[0]['head']['sha'] == selected['checkoutHead'] and
             prs[0]['base']['ref'] == 'master' and
             type(prs[0]['head']['repo']['id']) is int and type(prs[0]['base']['repo']['id']) is int and
             prs[0]['head']['repo']['id'] == prs[0]['base']['repo']['id'] == repository['id'],
             'sole source-bound same-repository Build PR/master')
        need(type(listing['total_count']) is int and listing['total_count'] == 1 and
             type(listing['artifacts']) is list and len(listing['artifacts']) == 1 and
             listing['artifacts'][0]['id'] == selected['artifactId'], 'sole official selected Build artifact')
        need(type(run['id']) is int and str(run['id']) == selected['runId'] and
             run['run_attempt'] == 1 and run['event'] == 'pull_request' and
             run['actor']['login'] == OWNER and run['head_sha'] == selected['checkoutHead'] and
             run['path'] == WORKFLOW and run['status'] == 'completed' and run['conclusion'] == 'success',
             'selected completed owner Build workflow readback')
        need(job['id'] == selected['jobId'] and job['run_id'] == run['id'] and job['run_attempt'] == 1 and
             job['head_sha'] == selected['checkoutHead'] and job['name'] == ROUTES['build'][0] and
             job['status'] == 'completed' and job['conclusion'] == 'success', 'selected completed Build job readback')
        names = ('Checkout selected producer source', 'Checkout executing workflow source',
            'Admit Bochs build source and request', 'Prepare pinned Node input cache',
            'Build pinned Bochs CPU3 and retain originals', 'Retain Bochs build originals')
        steps = job['steps']
        need(type(steps) is list and 6 <= len(steps) <= 32 and
             all(type(row['number']) is int and row['status'] == 'completed' and
                 row['conclusion'] == 'success' for row in steps) and
             len({row['number'] for row in steps}) == len(steps) and
             [row['number'] for row in steps] == sorted(row['number'] for row in steps),
             'all terminal successful unique ordered Build job steps')
        positions = []
        for name in names:
            indices = [index for index, row in enumerate(steps) if row['name'] == name]
            need(len(indices) == 1, 'unique source-bound producing Build step')
            positions.append(indices[0])
        need(positions == sorted(positions), 'exact Build producing-step order')
        need(artifact['id'] == selected['artifactId'] and artifact['name'] == selected['name'] and
             artifact['expired'] is False and artifact['size_in_bytes'] == selected['bytes'] and
             artifact['digest'] == 'sha256:' + selected['sha256'] and
             artifact['workflow_run']['id'] == run['id'] and
             artifact['workflow_run']['head_sha'] == selected['checkoutHead'] and
             type(artifact['workflow_run']['repository_id']) is int and
             type(artifact['workflow_run']['head_repository_id']) is int and
             artifact['workflow_run']['repository_id'] == artifact['workflow_run']['head_repository_id'] == repository['id'],
             'selected official artifact digest/repository readback')
        sealed_write(self.paths['work'] / 'build-intake-attempt.original.json', canonical({
            'schema': 'bw.bochs-ring3.build-intake-attempt.v1', 'runId': selected['runId'],
            'jobId': selected['jobId'], 'artifactId': selected['artifactId'],
            'archiveBytes': selected['bytes'], 'archiveSha256': selected['sha256']}), 4096)
        self.build_intake_partial['archiveAttempted'] = True
        raw = source_http(base + 'artifacts/' + str(selected['artifactId']) + '/zip',
                          selected['bytes'], token=token)
        need(len(raw) == selected['bytes'] and sha256(raw) == selected['sha256'], 'sole acquired official Build archive bytes')
        return raw, {'schema': 'bw.bochs-ring3.build-intake.v1', 'selected': selected,
            'readback': {'runId': run['id'], 'runAttempt': run['run_attempt'], 'event': run['event'],
                'actor': run['actor']['login'], 'head': run['head_sha'], 'workflowPath': run['path'],
                'repository': {key: repository[key] for key in ('id', 'full_name', 'fork')},
                'headRepository': {key: head_repository[key] for key in ('id', 'full_name', 'fork')},
                'pullRequest': {'number': prs[0]['number'], 'head': prs[0]['head']['sha'],
                    'baseRef': prs[0]['base']['ref'], 'headRepositoryId': prs[0]['head']['repo']['id'],
                    'baseRepositoryId': prs[0]['base']['repo']['id']},
                'jobId': job['id'], 'jobName': job['name'], 'steps': [
                    {key: row[key] for key in ('number', 'name', 'status', 'conclusion')} for row in steps],
                'artifactId': artifact['id'], 'artifactName': artifact['name'],
                'artifactRepositoryId': artifact['workflow_run']['repository_id'],
                'artifactHeadRepositoryId': artifact['workflow_run']['head_repository_id'],
                'archiveBytes': len(raw), 'archiveSha256': sha256(raw)}, 'officialAuthenticatedByReader': False}
    def prepare_reference(self, built):
        need(self.route == 'reference' and self.host_stage is not None and self.stage is not None,
             'verified staged inputs before owned Reference preparation')
        root = self.paths['work'] / 'runtime'
        os.mkdir(root, 0o700)
        publish_root_mode(root, 0o755, directory=True)
        files = built['runtime']
        directories = {root}
        for name in files:
            member_name(name)
            directories.update((root / name).parents)
        directories = {path for path in directories if path == root or root in path.parents}
        for path in sorted(directories - {root}, key=lambda item: len(item.parts)):
            os.mkdir(path, 0o700)
            publish_root_mode(path, 0o755, directory=True)
        for name, raw in sorted(files.items()):
            target = root / name
            sealed_write(target, raw, 33554432)
            if name == 'bin/bochs':
                publish_root_mode(target, 0o555)
        output = root / 'outputs'
        need(output not in directories and not any(name.startswith('outputs/') for name in files),
             'no acquired output-directory collision')
        caller_directory(output, self.invoker['uid'], self.invoker['gid'], mode=0o700)
        # Absolute source-fixed paths, no request-provided commands or URLs.
        config = BOCHSRC_TEMPLATE.replace(b'@ROOT@', str(root).encode('ascii'))
        sealed_write(self.paths['work'] / 'bochsrc.original', config, 16384)
        driver = reference_js_driver(self.context['sourceRoot'], root)
        sealed_write(self.paths['work'] / 'js-driver.mjs', driver, 16384)
        for path in sorted(directories, key=lambda item: len(item.parts), reverse=True):
            publish_root_mode(path, 0o555, directory=True)
        self.reference_runtime = root
        self.reference_files = files
        return config
    def reference_argv(self, name):
        need(self.route == 'reference' and name in ('js', 'bochs') and self.host_stage is not None,
             'closed source-owned Reference child argv')
        files = self.host_stage.facts['files']
        loader = [row['member'] for row in files.values() if Path(row['member']).name == 'ld-linux-x86-64.so.2']
        need(len(loader) == 1, 'one verified staged loader')
        prefix = [loader[0], '--inhibit-cache', '--library-path', str(self.host_stage.library)]
        if name == 'js':
            return prefix + [self.stage.facts['stagePath'], '--max-old-space-size=512',
                             str(self.paths['work'] / 'js-driver.mjs')]
        return prefix + [str(self.reference_runtime / 'bin/bochs'), '-q', '-f',
                         str(self.paths['work'] / 'bochsrc.original')]
    def runtime_after(self, built):
        need(self.route == 'reference' and self.reference_files == built['runtime'], 'fixed previously extracted runtime')
        result = {}
        for name, expected in sorted(self.reference_files.items()):
            raw, facts = read_regular(self.reference_runtime / name, max(1, len(expected)), minimum=len(expected))
            need(raw == expected and facts['before']['mode'] == built['modes'][name], 'same immutable extracted input bytes/mode')
            result[name] = facts
        return result
    def js_outputs(self):
        need(not getattr(self, 'js_output_attempted', False), 'one bounded JS output intake')
        self.js_output_attempted = True
        self.js_output_partial = {}
        names = {'report.json': 131072, 'observations.json': 1048576, 'writes.json': 1048576,
                 'memory.before.bin': 1048576, 'memory.after.bin': 1048576}
        result = {}
        for name, cap in names.items():
            raw, _facts = read_regular(self.reference_runtime / 'outputs' / name, cap,
                minimum=1048576 if name.endswith('.bin') else 1,
                owner=self.invoker['uid'], group=self.invoker['gid'])
            result['js/' + name] = raw
            self.js_output_partial['js/' + name] = raw
        return result
    def bochs_log(self):
        need(not getattr(self, 'bochs_log_attempted', False), 'one bounded Bochs log intake')
        self.bochs_log_attempted = True
        return read_regular(self.reference_runtime / 'outputs' / 'bochs.log', 4194304,
            minimum=1, owner=self.invoker['uid'], group=self.invoker['gid'])[0]
    def reference_output_census(self):
        limits = {'report.json': 131072, 'observations.json': 1048576, 'writes.json': 1048576,
                  'memory.before.bin': 1048576, 'memory.after.bin': 1048576, 'bochs.log': 4194304}
        root = self.reference_runtime / 'outputs'
        initial = identity(os.lstat(root))
        need(initial['mode'] == stat.S_IFDIR | 0o700 and
             initial['uid'] == self.invoker['uid'] and initial['gid'] == self.invoker['gid'],
             'fixed private invoker output directory')
        rows = {}
        with os.scandir(root) as entries:
            for entry in entries:
                need(entry.name in limits and entry.name not in rows and len(rows) < 6 and
                     not entry.is_symlink(), 'bounded exact known Reference output census')
                row = identity(os.lstat(root / entry.name))
                need(stat.S_ISREG(row['mode']) and row['mode'] & 0o022 == 0 and row['nlink'] == 1 and
                     row['uid'] == self.invoker['uid'] and row['gid'] == self.invoker['gid'] and
                     1 <= row['size'] <= limits[entry.name], 'typed finite source-authored output file')
                rows[entry.name] = row
        need(set(rows) == set(limits) and initial == identity(os.lstat(root)),
             'complete stable Reference output-directory census')
        return {'path': str(root), 'directory': initial, 'files': rows,
                'aggregateBytes': sum(row['size'] for row in rows.values()), 'quotaEnforced': False}
    def process(self, name, argv, **kwargs):
        need(self.child is not None, 'no observed executable in toolchain metadata')
        return self.child.process(name, argv, **kwargs)
    def unit(self, unit):
        need(unit == self.paths['unit'], 'fixed owned outside unit')
        try:
            row = self.kernel._directory(self.unit_path)
        except FileNotFoundError as exc:
            need(exc.errno == 2, 'actual absent selected unit')
            return {'path': str(self.unit_path), 'exists': False, 'errno': 2,
                    'identity': None, 'files': {}, 'children': []}
        facts = self._group(self.unit_path)
        return {'path': str(self.unit_path), 'exists': True, 'errno': None,
                'identity': row, 'files': facts['files'], 'children': facts['children']}
    def prepare_host_cleanup(self, inner, roles):
        need(self.route in ('build', 'reference'), 'library cleanup only on executing routes')
        raw = roles['host-runtime.original.json']
        value = raw_object(raw, 1048576)
        closed(value, ('schema', 'stage', 'cleanup'), 'closed protected work host runtime role')
        need(canonical(value) == raw and value['schema'] == 'bw.bochs-ring3.host-runtime-original.v1' and
             value['cleanup'] is None, 'immutable work stage before cleanup')
        stage = value['stage']
        need(inner['observations']['hostRuntime'] == {'stageBytes': len(canonical(stage)),
             'stageSha256': sha256(canonical(stage))}, 'inner observation pins exact staged-library facts')
        self.host_cleanup_stage = stage
        self.host_cleanup_plan = plan_host_runtime_cleanup(stage, self.route, self.env)
        plan = self.host_cleanup_plan
        return {'hostRuntimePlan': {'stageSha256': plan['stageSha256'],
                    'planSha256': sha256(canonical(plan)), 'roleReservedBytes': plan['roleReservedBytes']},
                'hostRuntimeCleanup': {'role': 'host-runtime.original.json',
                    'bytes': plan['roleReservedBytes'], 'sha256': 'f' * 64}}
    def cleanup(self, inner=None, *, outer=None):
        use_v2 = self.route=='toolchain-v2' or (type(stage_facts_v2(inner)) is dict and stage_facts_v2(inner).get('schema')=='bw.bochs-ring3.node-stage.v2')
        plan=(node_cleanup_wire_plan_v2 if use_v2 else node_cleanup_wire_plan)(self.route,self.env,inner)
        self.node_cleanup_plan=plan
        if self.route in ('build', 'reference'):
            need(getattr(self, 'host_cleanup_plan', None) is not None and
                 outer is not None and outer.get('hostRuntimePlan') is not None,
                 'complete read-only library plan before ANY cleanup effect')
        return cleanup_owned_cgroups(self.route, self.env, inner, self.kernel, outer_base=outer,
            input_plan=plan, following_error_bytes=1024 if self.route in ('build', 'reference') else 0)
    def host_cleanup(self):
        stage, plan = self.host_cleanup_stage, self.host_cleanup_plan
        result = cleanup_host_runtime(stage, plan, self.route, self.env)
        raw = canonical({'schema': 'bw.bochs-ring3.host-runtime-original.v1',
                         'stage': stage, 'cleanup': result})
        need(len(raw) <= plan['roleReservedBytes'] <= 1048576, 'final host runtime original bound')
        return raw
    def node_cleanup(self, inner):
        if self.route=='toolchain-v2' or (type(stage_facts_v2(inner)) is dict and stage_facts_v2(inner).get('schema')=='bw.bochs-ring3.node-stage.v2'):
            need(getattr(self,'node_cleanup_plan',None) is not None, 'V2 plan reserved before any cleanup effect')
            return cleanup_node_stage_v2(self.route,self.env,inner,self.node_cleanup_plan)
        return cleanup_node_stage(self.route, self.env, inner)
    def close(self):
        if self.stage is not None:
            self.stage.close()
            if self.stage.facts['firstFailure'] is not None:
                error = Refusal(self.stage.facts['firstFailure']['message'])
                error.bochs_first = self.stage.facts['firstFailure']
                error.bochs_secondary = self.stage.facts['secondary']
                error.bochs_partial = {'nodeStage': self.stage.facts}
                raise error


def parse_exit(text):
    if text == 'unknown':
        return None
    need(re.fullmatch(r'0|[1-9][0-9]{0,2}', text), 'canonical retained exit argument')
    value = int(text)
    integer(value, 0, 255, 'bounded retained exit argument')
    return value


# V2 DATA provider identity is independent of protected bootstrap caller IDs.
NODE_CACHE_UID_V2 = 1001
NODE_CACHE_GID_V2 = 1000

def admitted_request_v2(route, raw, event_raw, env):
    need(route == 'toolchain-v2', 'distinct metadata V2 route')
    value = request_object(raw)
    closed(value, ('schema','repository','pullRequest','source','policySha256','limits'), 'closed V2 metadata request')
    need(value['schema'] == 'bw.bochs-ring3.toolchain-request.v2' and
         value['repository'] == REPOSITORY and HEX.fullmatch(value['policySha256']), 'V2 request identity')
    need(canonical(value['limits']) == canonical(LIMITS[route]), 'unchanged V2 metadata bounds')
    admit_source_shape(value['source'])
    admit_event(route, value, raw, event_raw, env)
    return value

def selected_request(route, raw, event_raw, env, *, current=False):
    if current and route in ('build','reference'):
        value = admitted_request(route, raw, event_raw, env)
        (admit_build_inputs_v2 if route == 'build' else admit_reference_inputs_v2)(value)
        return value
    return (admitted_request_v2 if route == 'toolchain-v2' else admitted_request)(route, raw, event_raw, env)

def route_original_schema(route):
    return 'bw.bochs-ring3.toolchain-original.v2' if route == 'toolchain-v2' else 'bw.bochs-ring3.' + route + '-original.v1'

def check_current_node_stage(facts, route, env, *, after=False):
    if type(facts) is dict and facts.get('schema') == 'bw.bochs-ring3.node-stage.v2':
        return check_node_stage_v2(facts, route, env, after=after)
    return check_node_stage(facts, route, env, after=after)

def observer_facts_v2(value, env, *, pid, uid, gid, started_ns, ended_ns, invoker, bootstrap):
    observed = observer_facts(value, env, pid=pid, uid=uid, gid=gid, started_ns=started_ns, ended_ns=ended_ns)
    closed(invoker, ('uid','gid'), 'protected actual bootstrap caller')
    integer(invoker['uid'],1,65534,'bootstrap caller UID')
    integer(invoker['gid'],1,65534,'bootstrap caller GID')
    observed['schema'] = 'bw.bochs-ring3.toolchain-observer.v2'
    bootstrap_caller_scalars(bootstrap, invoker)
    observed['invoker'] = dict(invoker)
    observed['bootstrapCredentials'] = dict(bootstrap)
    return observed

class NodeStageCopyV2:
    """Adapted from the held MIT NodeStageCopy: cache DATA never executes.

    Exactly one copy, exclusive private root destination, full independent
    reopen/hash, then readonly publication. No actual copy runs in controls.
    """
    def __init__(self, route, env, invoker, bootstrap):
        self.path = route_paths(route, env)['node']
        bootstrap_caller_scalars(bootstrap, {'uid':invoker[0], 'gid':invoker[1]})
        self.invoker = tuple(invoker)
        need(len(self.invoker) == 2 and all(type(x) is int and 1 <= x < 2 ** 31 for x in self.invoker),
             'source-authenticated nonroot Node cache invoker identity')
        self.fds, self.bindings = {}, {}
        self.sparse_node = None
        self.attempted = False
        self.facts = {'bootstrapCredentials': dict(bootstrap), 'schema': 'bw.bochs-ring3.node-stage.v2', 'sourcePath': NODE_PATH,
            'stagePath': str(self.path / 'node'), 'recordPath': str(self.path / 'stage.json'),
            'invoker': {'uid': invoker[0], 'gid': invoker[1]},
            'metadataFields': list(NODE_METADATA_FIELDS), 'created': [],
            'sourceBefore': None, 'sourceAfter': None, 'sourceNamedAfter': None,
            'sourceBytesRead': 0, 'bytesCopied': 0, 'writeUncertain': False,
            'copiedSha256': None, 'readbackBytes': 0, 'readbackSha256': None,
            'elfReadBytes': 0, 'elf': None, 'fileBeforePublication': None,
            'parents': {}, 'directoryInitial': None, 'fileInitial': None,
            'targetAfterFailure': None, 'directoryAfterFailure': None,
            'lastOperation': None,
            'file': None, 'fileNamed': None, 'directoryBeforePublication': None,
            'directory': None, 'directoryNamed': None,
            'filePublicationAttempted': False, 'directoryPublicationAttempted': False,
            'filePublished': False, 'directoryPublished': False, 'record': None,
            'checkedAfter': None,
            'firstFailure': None, 'secondary': []}
    @staticmethod
    def metadata(info):
        return [getattr(info, 'st_' + name) for name in NODE_METADATA_FIELDS]
    def error(self, exc, phase):
        current = self.facts['lastOperation'] or {}
        item = failure(exc, phase, current.get('role'), current.get('path'))
        if self.facts['firstFailure'] is None:
            self.facts['firstFailure'] = item
        elif len(self.facts['secondary']) < SECONDARY_LIMIT:
            self.facts['secondary'].append(item)
    def directory(self, path):
        self.facts['lastOperation'] = {'role': 'node-stage-directory', 'path': str(path), 'operation': 'open/readback'}
        parent = self.fds.get(path.parent)
        fd = os.open(path if parent is None else path.name,
                     os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_NONBLOCK | os.O_CLOEXEC,
                     **({} if parent is None else {'dir_fd': parent}))
        self.fds[path] = fd
        held, named = self.metadata(os.fstat(fd)), self.metadata(path.lstat())
        need(path.resolve(strict=True) == path and held == named and stat.S_ISDIR(held[2]) and
             held[3:5] == [0, 0] and held[2] & 0o022 == 0, 'held root-owned Node-stage directory')
        self.bindings[path] = held
        if path == self.path:
            self.facts['directoryInitial'] = held
        else:
            self.facts['parents'][str(path)] = {'before': held, 'namedBefore': named,
                                               'after': None, 'namedAfter': None}
        return fd
    def recheck(self):
        for path, fd in self.fds.items():
            self.facts['lastOperation'] = {'role': 'node-stage-directory', 'path': str(path), 'operation': 'held/named readback'}
            held, named = self.metadata(os.fstat(fd)), self.metadata(path.lstat())
            need(held[:5] == named[:5] == self.bindings[path][:5] and
                 path.resolve(strict=True) == path, 'Node-stage parent first-five identity')
            if str(path) in self.facts['parents']:
                self.facts['parents'][str(path)]['after'] = held
                self.facts['parents'][str(path)]['namedAfter'] = named
    def close_fd(self, fd, phase, role=None, path=None):
        if fd is not None:
            self.facts['lastOperation'] = {'role': role, 'path': path, 'operation': 'close-held'}
            try:
                os.close(fd)
            except BaseException as exc:
                self.error(exc, phase)
    def copy(self):
        need(not self.attempted, 'Node stage consumed; no copy retry')
        try:
            return self._copy()
        except BaseException as exc:
            if self.facts['firstFailure'] is None:
                self.error(exc, 'node-stage')
            exc.bochs_partial = {'nodeStage': self.facts}
            exc.bochs_first = self.facts['firstFailure']
            exc.bochs_secondary = self.facts['secondary']
            raise
    def _copy(self):
        need(not self.attempted, 'Node stage consumed; no copy retry')
        self.attempted = True
        source_fd = target_fd = None
        try:
            need(os.getresuid() == (0, 0, 0) and os.getresgid() == (0, 0, 0), 'root-only Node data staging')
            self.directory(Path('/'))
            parent = self.directory(Path('/run'))
            self.recheck()
            os.mkdir(self.path.name, 0o700, dir_fd=parent)
            self.facts['created'].append(str(self.path))
            directory = self.directory(self.path)
            need(stat.S_IMODE(self.bindings[self.path][2]) == 0o700, 'private unpublished Node stage')
            source = Path(NODE_PATH)
            self.facts['lastOperation'] = {'role': 'node-cache-data', 'path': NODE_PATH, 'operation': 'open/readback'}
            need(source.resolve(strict=True) == source, 'canonical fixed Node cache DATA path')
            source_fd = os.open(NODE_PATH, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK | os.O_CLOEXEC)
            before = self.metadata(os.fstat(source_fd))
            self.facts['sourceBefore'] = before
            need(before == self.metadata(source.lstat()) and stat.S_ISREG(before[2]) and
                 before[5] == 1 and before[6] == NODE_BYTES and before[2] & 0o6000 == 0 and
                 before[2:5] == [stat.S_IFREG | 0o777, NODE_CACHE_UID_V2, NODE_CACHE_GID_V2],
                 'bounded single-link Node cache DATA, not executable authority')
            self.facts['lastOperation'] = {'role': 'node-staged-executable', 'path': str(self.path / 'node'), 'operation': 'exclusive create'}
            target_fd = os.open('node', os.O_RDWR | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW |
                                os.O_NONBLOCK | os.O_CLOEXEC, 0o600, dir_fd=directory)
            self.facts['created'].append(str(self.path / 'node'))
            first = self.metadata(os.fstat(target_fd))
            self.facts['fileInitial'] = first
            need(stat.S_ISREG(first[2]) and stat.S_IMODE(first[2]) == 0o600 and
                 first[3:7] == [0, 0, 1, 0], 'fresh nonexecutable root Node output')
            digest = hashlib.sha256()
            prefix = b''
            while True:
                self.facts['lastOperation'] = {'role': 'node-cache-data', 'path': NODE_PATH, 'operation': 'bounded read'}
                chunk = os.read(source_fd, min(65536, NODE_BYTES + 1 - self.facts['sourceBytesRead']))
                if not chunk:
                    break
                self.facts['sourceBytesRead'] += len(chunk)
                need(self.facts['sourceBytesRead'] <= NODE_BYTES, 'fixed Node data copy cap')
                digest.update(chunk)
                prefix = (prefix + chunk)[:4]
                try:
                    self.facts['lastOperation'] = {'role': 'node-staged-executable', 'path': str(self.path / 'node'), 'operation': 'once-only chunk write'}
                    written = os.write(target_fd, chunk)
                except BaseException:
                    self.facts['writeUncertain'] = True
                    raise
                need(type(written) is int and 0 <= written <= len(chunk), 'bounded Node chunk write')
                self.facts['bytesCopied'] += written
                need(written == len(chunk), 'complete once-only Node chunk write')
            self.facts['copiedSha256'] = digest.hexdigest()
            self.facts['lastOperation'] = {'role': 'node-cache-data', 'path': NODE_PATH, 'operation': 'held/named after readback'}
            self.facts['sourceAfter'] = self.metadata(os.fstat(source_fd))
            self.facts['sourceNamedAfter'] = self.metadata(source.lstat())
            need(self.facts['sourceBytesRead'] == self.facts['bytesCopied'] == NODE_BYTES and
                 digest.hexdigest() == NODE_SHA256 and prefix == b'\x7fELF' and
                 before == self.facts['sourceAfter'] == self.facts['sourceNamedAfter'] and
                 source.resolve(strict=True) == source, 'fixed Node bytes and source held/named stability')
            need(self.metadata(os.fstat(target_fd))[3:7] == [0, 0, 1, NODE_BYTES], 'complete private Node output')
            self.facts['lastOperation'] = {'role': 'node-staged-executable', 'path': str(self.path / 'node'), 'operation': 'fsync'}
            os.fsync(target_fd)
        except BaseException as exc:
            self.error(exc, 'node-copy')
            for key, observe in (
                ('sourceAfter', lambda: os.fstat(source_fd) if source_fd is not None else None),
                ('sourceNamedAfter', lambda: Path(NODE_PATH).lstat() if source_fd is not None else None),
                ('targetAfterFailure', lambda: os.fstat(target_fd) if target_fd is not None else None),
                ('directoryAfterFailure', lambda: os.fstat(self.fds[self.path]) if self.path in self.fds else None)):
                try:
                    info = observe()
                    if info is not None:
                        self.facts[key] = self.metadata(info)
                except BaseException as extra:
                    self.error(extra, 'node-copy-failure-stat')
        finally:
            self.close_fd(target_fd, 'node-copy-target-close', 'node-staged-executable', str(self.path / 'node'))
            self.close_fd(source_fd, 'node-copy-source-close', 'node-cache-data', NODE_PATH)
        if self.facts['firstFailure'] is not None:
            error = Refusal(self.facts['firstFailure']['message'])
            error.bochs_partial = {'nodeStage': self.facts}
            raise error
        self.recheck()
        directory = self.fds[self.path]
        fd = None
        try:
            self.facts['lastOperation'] = {'role': 'node-staged-executable', 'path': str(self.path / 'node'), 'operation': 'independent reopen/hash'}
            fd = os.open('node', os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK | os.O_CLOEXEC,
                         dir_fd=directory)
            before = self.metadata(os.fstat(fd))
            need(before == self.metadata(os.stat('node', dir_fd=directory, follow_symlinks=False)) and
                 stat.S_ISREG(before[2]) and stat.S_IMODE(before[2]) == 0o600 and
                 before[3:7] == [0, 0, 1, NODE_BYTES], 'independent root Node reopen')
            self.facts['fileBeforePublication'] = before
            digest = hashlib.sha256()
            while True:
                chunk = os.read(fd, min(65536, NODE_BYTES + 1 - self.facts['readbackBytes']))
                if not chunk:
                    break
                self.facts['readbackBytes'] += len(chunk)
                need(self.facts['readbackBytes'] <= NODE_BYTES, 'independent Node readback cap')
                digest.update(chunk)
            self.facts['readbackSha256'] = digest.hexdigest()
            need(self.facts['readbackBytes'] == NODE_BYTES and digest.hexdigest() == NODE_SHA256 and
                 before == self.metadata(os.fstat(fd)) ==
                 self.metadata(os.stat('node', dir_fd=directory, follow_symlinks=False)),
                 'independent complete Node bytes before executable publication')
            def read_at(offset, count):
                self.facts['elfReadBytes'] += count
                need(self.facts['elfReadBytes'] <= 2097152, 'bounded staged Node ELF range reads')
                return os.pread(fd, count, offset)
            self.sparse_node = sparse_elf_from_reader(NODE_BYTES, read_at, self.facts['readbackSha256'])
            self.facts['elf'] = {key: value for key, value in self.sparse_node['structure'].items()
                                 if key != 'soname'}
            need(self.facts['elf']['rpath'] is None and self.facts['elf']['runpath'] is None,
                 'staged Node has no RPATH/RUNPATH')
            self.facts['filePublicationAttempted'] = True
            os.fchmod(fd, 0o555)
            self.facts['file'] = self.metadata(os.fstat(fd))
            self.facts['fileNamed'] = self.metadata(os.stat('node', dir_fd=directory, follow_symlinks=False))
            need(stat.S_IMODE(self.facts['file'][2]) == 0o555 and
                 self.facts['file'][3:7] == [0, 0, 1, NODE_BYTES] and
                 self.facts['file'][:2] == before[:2] and self.facts['file'] == self.facts['fileNamed'],
                 'readonly root Node file publication')
            self.facts['filePublished'] = True
        except BaseException as exc:
            self.error(exc, 'node-readback-publication')
            if fd is not None:
                try:
                    self.facts['targetAfterFailure'] = self.metadata(os.fstat(fd))
                except BaseException as extra:
                    self.error(extra, 'node-publication-failed-stat')
        finally:
            self.close_fd(fd, 'node-readback-close', 'node-staged-executable', str(self.path / 'node'))
        if self.facts['firstFailure'] is not None:
            error = Refusal(self.facts['firstFailure']['message'])
            error.bochs_partial = {'nodeStage': self.facts}
            raise error
        self.recheck()
        record = canonical({'schema': 'bw.bochs-ring3.node-installation.v2', 'sourcePath': NODE_PATH,
                            'stagePath': self.facts['stagePath'], 'bytes': NODE_BYTES,
                            'sha256': NODE_SHA256, 'uid': 0, 'gid': 0, 'mode': stat.S_IFREG | 0o555})
        fd = None
        try:
            self.facts['lastOperation'] = {'role': 'node-stage-record', 'path': str(self.path / 'stage.json'), 'operation': 'exclusive create/readback'}
            fd = os.open('stage.json', os.O_RDWR | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW |
                         os.O_NONBLOCK | os.O_CLOEXEC, 0o600, dir_fd=directory)
            self.facts['created'].append(str(self.path / 'stage.json'))
            need(os.write(fd, record) == len(record), 'once-only Node installation record write')
            os.fchmod(fd, 0o444)
            os.lseek(fd, 0, os.SEEK_SET)
            before = self.metadata(os.fstat(fd))
            need(stat.S_ISREG(before[2]) and stat.S_IMODE(before[2]) == 0o444 and
                 before[3:7] == [0, 0, 1, len(record)] and os.read(fd, len(record) + 1) == record and
                 before == self.metadata(os.fstat(fd)) ==
                 self.metadata(os.stat('stage.json', dir_fd=directory, follow_symlinks=False)),
                 'root readonly exact Node installation record')
            self.facts['record'] = {'bytes': len(record), 'sha256': sha256(record),
                                    'metadata': before, 'text': record.decode('utf-8')}
        except BaseException as exc:
            self.error(exc, 'node-record')
        finally:
            self.close_fd(fd, 'node-record-close', 'node-stage-record', str(self.path / 'stage.json'))
        if self.facts['firstFailure'] is None:
            try:
                self.recheck()
                self.facts['directoryBeforePublication'] = self.metadata(os.fstat(directory))
                self.facts['directoryPublicationAttempted'] = True
                self.facts['lastOperation'] = {'role': 'node-stage-directory', 'path': str(self.path), 'operation': 'readonly publication'}
                os.fchmod(directory, 0o555)
                self.facts['directory'] = self.metadata(os.fstat(directory))
                self.facts['directoryNamed'] = self.metadata(self.path.lstat())
                need(stat.S_IMODE(self.facts['directory'][2]) == 0o555 and
                     self.facts['directory'][3:5] == [0, 0] and
                     self.facts['directory'][:2] == self.bindings[self.path][:2] and
                     self.facts['directory'] == self.facts['directoryNamed'],
                     'root readonly Node directory publication')
                self.bindings[self.path] = self.facts['directory']
                self.facts['directoryPublished'] = True
                self.recheck()
            except BaseException as exc:
                self.error(exc, 'node-directory-publication')
                try:
                    self.facts['directoryAfterFailure'] = self.metadata(os.fstat(directory))
                except BaseException as extra:
                    self.error(extra, 'node-directory-failed-stat')
        if self.facts['firstFailure'] is not None:
            error = Refusal(self.facts['firstFailure']['message'])
            error.bochs_partial = {'nodeStage': self.facts}
            raise error
        return self.facts
    def verify_after(self, *, full_hash):
        """No Node invocation in inventory: immutable identity check suffices there.

        Build/reference reread the full staged executable after work. Neither
        copies nor executes the mutable original-cache pathname again.
        """
        need(self.facts['firstFailure'] is None and self.facts['filePublished'] and
             self.facts['directoryPublished'], 'successful Node publication before verification')
        self.recheck()
        fd = None
        observed = {'hashRead': full_hash, 'bytesRead': 0, 'sha256': None,
                    'before': None, 'after': None, 'named': None, 'elf': None, 'elfReadBytes': 0}
        try:
            directory = self.fds[self.path]
            fd = os.open('node', os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK | os.O_CLOEXEC,
                         dir_fd=directory)
            observed['before'] = self.metadata(os.fstat(fd))
            need(observed['before'] == self.facts['file'], 'same readonly staged Node before after-check')
            if full_hash:
                digest = hashlib.sha256()
                while True:
                    chunk = os.read(fd, min(65536, NODE_BYTES + 1 - observed['bytesRead']))
                    if not chunk:
                        break
                    observed['bytesRead'] += len(chunk)
                    need(observed['bytesRead'] <= NODE_BYTES, 'staged Node after-read cap')
                    digest.update(chunk)
                observed['sha256'] = digest.hexdigest()
                need(observed['bytesRead'] == NODE_BYTES and digest.hexdigest() == NODE_SHA256,
                     'complete staged Node after-execution byte identity')
                def read_at(offset, count):
                    observed['elfReadBytes'] += count
                    need(observed['elfReadBytes'] <= 2097152, 'bounded Node after ELF range reads')
                    return os.pread(fd, count, offset)
                sparse_after = sparse_elf_from_reader(NODE_BYTES, read_at, observed['sha256'])
                need(sparse_after == self.sparse_node, 'same staged Node exact structural range readback')
                observed['elf'] = {key: value for key, value in sparse_after['structure'].items()
                                   if key != 'soname'}
                need(observed['elf'] == self.facts['elf'], 'staged Node after ELF identity')
            observed['after'] = self.metadata(os.fstat(fd))
            observed['named'] = self.metadata(os.stat('node', dir_fd=directory, follow_symlinks=False))
            need(observed['before'] == observed['after'] == observed['named'],
                 'staged Node complete held/named after-check')
        except BaseException as exc:
            self.error(exc, 'node-after-verification')
        finally:
            self.close_fd(fd, 'node-after-verification-close', 'node-staged-executable', str(self.path / 'node'))
            self.facts['checkedAfter'] = observed
        if self.facts['firstFailure'] is not None:
            error = Refusal(self.facts['firstFailure']['message'])
            error.bochs_partial = {'nodeStage': self.facts}
            raise error
        return self.facts
    def close(self):
        fds = list(reversed(list(self.fds.items())))
        self.fds = {}
        for path, fd in fds:
            self.close_fd(fd, 'node-stage-parent-close', 'node-stage-directory', str(path))


def check_node_stage_v2(facts, route, env, *, after=False):
    need(type(facts) is dict and facts.get('schema') == 'bw.bochs-ring3.node-stage.v2',
         'typed cache-DATA/readonly-executable Node stage')
    path = route_paths(route, env)['node']
    need(facts['sourcePath'] == NODE_PATH and facts['stagePath'] == str(path / 'node') and
         facts['recordPath'] == str(path / 'stage.json') and
         facts['metadataFields'] == list(NODE_METADATA_FIELDS), 'source-derived Node role paths')
    def meta(row):
        need(type(row) is list and len(row) == 9 and
             all(type(value) is int and value >= 0 for value in row) and row[1] > 0,
             'typed nine-field Node identity')
        return row
    invoker = facts['invoker']
    closed(invoker, ('uid', 'gid'), 'source-authenticated Node invoker')
    integer(invoker['uid'], 1, 2 ** 31 - 1, 'Node invoker UID')
    integer(invoker['gid'], 1, 2 ** 31 - 1, 'Node invoker GID')
    bootstrap_caller_scalars(facts['bootstrapCredentials'], invoker)
    source = meta(facts['sourceBefore'])
    need(source == meta(facts['sourceAfter']) == meta(facts['sourceNamedAfter']) and
         stat.S_ISREG(source[2]) and source[2] & 0o6000 == 0 and source[5:7] == [1, NODE_BYTES] and
         source[2:5] == [stat.S_IFREG | 0o777, NODE_CACHE_UID_V2, NODE_CACHE_GID_V2],
         'bounded fixed Node cache DATA identity (not executable permission)')
    initial, before, final = meta(facts['fileInitial']), meta(facts['fileBeforePublication']), meta(facts['file'])
    need(initial[2:7] == [stat.S_IFREG | 0o600, 0, 0, 1, 0] and
         before[2:7] == [stat.S_IFREG | 0o600, 0, 0, 1, NODE_BYTES] and
         final[2:7] == [stat.S_IFREG | 0o555, 0, 0, 1, NODE_BYTES] and
         initial[:2] == before[:2] == final[:2] and final == meta(facts['fileNamed']),
         'fresh root0600 copy becomes same readonly0555 executable')
    first_dir = meta(facts['directoryInitial'])
    before_dir, final_dir = meta(facts['directoryBeforePublication']), meta(facts['directory'])
    need(first_dir[2:5] == before_dir[2:5] == [stat.S_IFDIR | 0o700, 0, 0] and
         final_dir[2:5] == [stat.S_IFDIR | 0o555, 0, 0] and
         first_dir[:2] == before_dir[:2] == final_dir[:2] and
         final_dir == meta(facts['directoryNamed']), 'fresh private root directory readonly publication')
    need(set(facts['parents']) == {'/', '/run'}, 'closed Node-stage parent roster')
    for row in facts['parents'].values():
        closed(row, ('before', 'namedBefore', 'after', 'namedAfter'), 'Node parent raw readbacks')
        snapshots = [meta(row[key]) for key in ('before', 'namedBefore', 'after', 'namedAfter')]
        need(all(snap[:5] == snapshots[0][:5] for snap in snapshots) and
             stat.S_ISDIR(snapshots[0][2]) and snapshots[0][3:5] == [0, 0] and
             snapshots[0][2] & 0o022 == 0, 'held/named root-parent first-five continuity')
    need(facts['created'] == [str(path), str(path / 'node'), str(path / 'stage.json')] and
         facts['sourceBytesRead'] == facts['bytesCopied'] == facts['readbackBytes'] == NODE_BYTES and
         facts['copiedSha256'] == facts['readbackSha256'] == NODE_SHA256 and
         facts['writeUncertain'] is False and facts['filePublicationAttempted'] is True and
         facts['directoryPublicationAttempted'] is True and facts['filePublished'] is True and
         facts['directoryPublished'] is True and facts['firstFailure'] is None and facts['secondary'] == [],
         'once-only complete independent Node hash/publication observations')
    integer(facts['elfReadBytes'], 1, 2097152, 'bounded staged Node ELF range reads')
    need(type(facts['elf']) is dict and facts['elf']['class'] == 'ELF64' and
         facts['elf']['machine'] == 'x86-64' and facts['elf']['rpath'] is None and
         facts['elf']['runpath'] is None, 'source-observed staged Node ELF')
    record = facts['record']
    closed(record, ('bytes', 'sha256', 'metadata', 'text'), 'closed readonly Node installation record')
    expected = canonical({'schema': 'bw.bochs-ring3.node-installation.v2', 'sourcePath': NODE_PATH,
                          'stagePath': str(path / 'node'), 'bytes': NODE_BYTES,
                          'sha256': NODE_SHA256, 'uid': 0, 'gid': 0, 'mode': stat.S_IFREG | 0o555})
    need(record['text'].encode('utf-8') == expected and record['bytes'] == len(expected) and
         record['sha256'] == sha256(expected) and
         meta(record['metadata'])[2:7] == [stat.S_IFREG | 0o444, 0, 0, 1, len(expected)],
         'exact readonly source-bound Node record bytes')
    if after:
        checked = facts['checkedAfter']
        closed(checked, ('hashRead', 'bytesRead', 'sha256', 'before', 'after', 'named', 'elf', 'elfReadBytes'),
               'Node after-use observations')
        need(meta(checked['before']) == meta(checked['after']) == meta(checked['named']) == final,
             'same immutable staged Node after work')
        if route == 'toolchain-v2':
            need(checked['hashRead'] is False and checked['bytesRead'] == 0 and
                 checked['sha256'] is None and checked['elf'] is None and checked['elfReadBytes'] == 0,
                 'metadata route does not claim an unperformed after hash or Node execution')
        else:
            need(checked['hashRead'] is True and checked['bytesRead'] == NODE_BYTES and
                 checked['sha256'] == NODE_SHA256 and checked['elf'] == facts['elf'],
                 'actual staged Node after-execution complete hash/ELF')
            integer(checked['elfReadBytes'], 1, 2097152, 'bounded Node after ELF range-read count')
    return facts


def collect_toolchain_v2(request_raw, event_raw, env, ops):
    """Connected no-tool-execution metadata producer; ops owns OS/data edges."""
    request = admitted_request_v2('toolchain-v2', request_raw, event_raw, env)
    value = original('toolchain', request_raw, event_raw)
    value['schema'] = 'bw.bochs-ring3.toolchain-original.v2'
    observations = {'inventoryBefore': None, 'inventoryAfter': None, 'status': None,
                    'sourceSelection': SOURCE_SELECTION_SHA256, 'reportedReadbackOnly': True,
                    'notices': None, 'nodeStage': None, 'runtimeElfMetadata': None}
    value['observations'] = observations
    roles = {'request.original.json': request_raw, 'event.original.json': event_raw}
    phase = 'source-before'
    try:
        value['sourceBefore'] = ops.source(request['source'], env)
        roles['source.before.json'] = canonical(value['sourceBefore'])
        phase = 'resource-before'
        value['resources'] = {'before': ops.resources('toolchain-v2'), 'after': None}
        phase = 'node-cache-data-staging'
        observations['nodeStage'] = ops.node_stage()
        check_node_stage_v2(observations['nodeStage'], 'toolchain-v2', env)
        roles['node-stage.original.json'] = canonical(observations['nodeStage'])
        phase = 'toolchain-inventory-before'
        observations['inventoryBefore'] = ops.toolchain()
        roles['inventory.before.json'] = canonical(observations['inventoryBefore'])
        phase = 'runtime-elf-structural-metadata'
        structural = admit_runtime_elf_metadata(ops.elf_metadata(observations['inventoryBefore']),
                                               observations['inventoryBefore'], observations['nodeStage'])
        roles['runtime-elf-ranges.original.json'] = canonical(structural)
        observations['runtimeElfMetadata'] = bytes_ref('runtime-elf-ranges.original.json',
                                                       roles['runtime-elf-ranges.original.json'])
        phase = 'selected-toolchain-notices'
        notices = ops.notices()
        need(type(notices) is dict and set(notices) == set(NOTICE_PATHS),
             'all seven selected licence notice files')
        observations['notices'] = {}
        notice_bytes = 0
        for source_path, (path, raw) in notices.items():
            need(path in observations['inventoryBefore']['files'] and
                 observations['inventoryBefore']['files'][path]['bytes'] == len(raw) and
                 observations['inventoryBefore']['files'][path]['sha256'] == sha256(raw) and
                 1 <= len(raw) <= 262144, 'notice exact selected file readback')
            notice_bytes += len(raw)
            need(notice_bytes <= 524288, 'aggregate retained licence notice text cap')
            observations['notices'][source_path] = {'path': path, 'bytes': len(raw),
                                                   'sha256': sha256(raw), 'text': raw.decode('utf-8')}
        roles['notices.original.json'] = canonical(observations['notices'])
        phase = 'debian-status'
        raw, record = ops.read('/var/lib/dpkg/status', 4 * 1024 * 1024, minimum=1, owner=0)
        roles['dpkg-status.original'] = raw
        observations['status'] = {'bytes': len(raw), 'sha256': sha256(raw),
                                  'packages': debian_status(raw), 'observation': record}
        phase = 'toolchain-inventory-after'
        observations['inventoryAfter'] = ops.toolchain()
        roles['inventory.after.json'] = canonical(observations['inventoryAfter'])
        need(observations['inventoryBefore'] == observations['inventoryAfter'],
             'held inventory before/after complete identity')
        observations['nodeStage'] = ops.node_after(full_hash=False)
        check_node_stage_v2(observations['nodeStage'], 'toolchain-v2', env, after=True)
        roles['node-stage.original.json'] = canonical(observations['nodeStage'])
        need(sum(row['bytes'] for row in observations['inventoryBefore']['files'].values()) * 2 +
             observations['nodeStage']['sourceBytesRead'] + observations['nodeStage']['readbackBytes'] +
             observations['nodeStage']['elfReadBytes'] + notice_bytes +
             sum(row['fileBytes'] for path, row in structural['files'].items() if path != NODE_PATH)
             <= LIMITS['toolchain-v2']['totalReadBytes'],
             'actual selected tool/Node/notice read budget')
    except BaseException as exc:
        original_error(value, exc, phase)
    finally:
        if value['sourceBefore'] is not None:
            try:
                value['sourceAfter'] = ops.source(request['source'], env)
                roles['source.after.json'] = canonical(value['sourceAfter'])
                need(value['sourceBefore'] == value['sourceAfter'], 'source before/after equality')
            except BaseException as exc:
                original_error(value, exc, 'source-after')
        if value['resources'] is not None:
            try:
                value['resources']['after'] = ops.resources('toolchain-v2')
            except BaseException as exc:
                original_error(value, exc, 'resource-after')
        close_provider(ops, value, roles)
        if value['sourceBefore'] is not None:
            try:
                roles['process.original.json'] = canonical(ops.observer(value))
            except BaseException as exc:
                original_error(value, exc, 'observer-process')
    value['complete'] = value['firstFailure'] is None and not value['secondary']
    roles['original.json'] = canonical(value)
    roles['manifest.json'] = canonical(original_manifest(roles))
    return value, roles


def bootstrap_caller_scalars(value, invoker):
    closed(value, ('schema','uidArgument','gidArgument','sudoUid','sudoGid'), 'source-bound bootstrap scalar observation')
    need(value['schema'] == 'bw.bochs-ring3.bootstrap-caller.v1' and
         value['uidArgument'] == value['sudoUid'] == str(invoker['uid']) and
         value['gidArgument'] == value['sudoGid'] == str(invoker['gid']), 'protected bootstrap IDs independent of DATA owner')
    integer(invoker['uid'],1,65534,'bootstrap caller UID')
    integer(invoker['gid'],1,65534,'bootstrap caller GID')
    return value


def metadata_v2_identity(value):
    closed(value, ('schema','jobName','version'), 'explicit selected metadata V2 identity')
    need(value == {'schema':'bw.bochs-ring3.toolchain-inventory-reference.v2',
         'jobName':'bochs-ring3-toolchain-inventory-v2','version':2} and type(value['version']) is int,
         'source-fixed metadata V2, no V1 downgrade')
    return value

def admit_build_inputs_v2(request):
    selected = request['toolchain']['inventory']
    names = ('runId','jobId','artifactId','archiveBytes','archiveSha256','requestSha256',
             'reportSha256','sourceHead','sourceTree','workflowCommit')
    closed(selected, (*names,'schema','jobName','version'), 'current Build explicit metadata V2 reference')
    metadata_v2_identity({key:selected[key] for key in ('schema','jobName','version')})
    legacy = {**request, 'toolchain': {**request['toolchain'],
        'inventory': {key:selected[key] for key in names}}}
    admit_build_inputs(legacy)

def admit_reference_inputs_v2(request):
    selected = request['build']
    names = ('runId','jobId','artifactId','name','bytes','sha256','checkoutHead','checkoutTree',
             'workflowCommit','workflowFileSha256','compactManifest','buildLog')
    closed(selected, (*names,'metadata'), 'current Reference explicit metadata V2 identity')
    metadata_v2_identity(selected['metadata'])
    admit_reference_inputs({**request,'build':{key:selected[key] for key in names}})
    return selected


def collect_build_v2(request_raw, event_raw, env, ops):
    request = admitted_request('build', request_raw, event_raw, env)
    admit_build_inputs_v2(request)
    value = original('build', request_raw, event_raw)
    observations = {name: None for name in ('upstream', 'sourceSelection', 'toolchainBefore',
        'toolchainAfter', 'configure', 'configHeader', 'compilerCommands', 'binary',
        'runtimeManifest', 'notices', 'compactManifest', 'correspondingSource', 'nodeStage',
        'runtimeElfMetadata', 'hostRuntime')}
    value['observations'] = observations
    roles = {'request.original.json': request_raw, 'event.original.json': event_raw}
    phase = 'source-before'
    manifest = None
    runtime_raw = None
    try:
        value['sourceBefore'] = ops.source(request['source'], env)
        roles['source.before.json'] = canonical(value['sourceBefore'])
        value['resources'] = {'before': ops.resources('build'), 'after': None}
        phase = 'node-cache-data-staging'
        observations['nodeStage'] = ops.node_stage()
        check_node_stage_v2(observations['nodeStage'], 'build', env)
        roles['node-stage.original.json'] = canonical(observations['nodeStage'])
        phase = 'build-toolchain-before'
        observations['toolchainBefore'] = ops.toolchain()
        roles['toolchain.before.json'] = canonical(observations['toolchainBefore'])
        selected = {name: request['toolchain'][name] for name in ('files', 'aliases', 'directoryAliases')}
        match_expected_graph(observations['toolchainBefore'], selected)
        need(node_expectation(observations['nodeStage']) == request['toolchain']['node'],
             'current staged Node equals independent inventory selection')
        phase = 'current-runtime-structural-metadata'
        structural = admit_runtime_elf_metadata(ops.elf_metadata(observations['toolchainBefore']),
            observations['toolchainBefore'], observations['nodeStage'])
        roles['runtime-elf-ranges.original.json'] = canonical(structural)
        observations['runtimeElfMetadata'] = bytes_ref('runtime-elf-ranges.original.json',
            roles['runtime-elf-ranges.original.json'])
        phase = 'readonly-current-host-runtime'
        staged = ops.host_runtime_stage(observations['toolchainBefore'], structural)
        observations['hostRuntime'] = {'stageBytes': len(canonical(staged)),
                                     'stageSha256': sha256(canonical(staged))}
        roles['host-runtime.original.json'] = canonical({'schema': 'bw.bochs-ring3.host-runtime-original.v1',
                                                         'stage': staged, 'cleanup': None})
        phase = 'source-payload-acquisition'
        upstream = ops.upstream(request['bochs'])
        observations['sourceSelection'] = selected_source_rows(upstream['tree'])
        observations['upstream'] = upstream['before']
        observations['correspondingSource'] = upstream['correspondingSource']
        roles['upstream.tree.original.json'] = canonical(upstream['tree'])
        roles['source-selection.original.json'] = canonical(observations['sourceSelection'])
        roles['upstream.before.json'] = canonical(upstream['before'])
        roles['source-selected.original.tar.gz'] = upstream['sourceArchive']
        roles['notices/vgabios-corresponding-source.tar.gz'] = upstream['correspondingSourceRaw']
        need(len(upstream['correspondingSourceRaw']) == VGA_SOURCE_BYTES and
             sha256(upstream['correspondingSourceRaw']) == VGA_SOURCE_SHA256,
             'exact complete corresponding source original')
        phase = 'configure'
        value['authority']['compilerExecuted'] = None
        process, streams, _stop = run_phase(ops, value, roles, 'configure', CONFIGURE_ARGV,
                                           wall_seconds=900)
        config_raw, version_raw = ops.generated_headers()
        observations['configure'] = configure_facts(config_raw, version_raw)
        observations['configHeader'] = bytes_ref('config.h.original', config_raw)
        roles['config.h.original'], roles['bxversion.h.original'] = config_raw, version_raw
        phase = 'make'
        _process, streams, _stop = run_phase(ops, value, roles, 'make', MAKE_ARGV, wall_seconds=900)
        commands = [line for line in streams['stdout'].decode('utf-8').splitlines()
                    if TOOL_PATHS['gcc'] in line or TOOL_PATHS['g++'] in line]
        need(1 <= len(commands) <= 8192 and all(len(line) <= 8192 for line in commands),
             'bounded retained actual compiler commands')
        need(len(canonical(commands)) <= 1048576, 'compiler command summary budget within original cap')
        observations['compilerCommands'] = commands
        phase = 'static-build-assets'
        assembled = ops.runtime_bundle(request, upstream)
        runtime_files = assembled['files']
        need('asset-manifest.json' in runtime_files and 'bin/bochs' in runtime_files,
             'closed retained runtime assets')
        binary = runtime_files['bin/bochs']
        binary_facts = {key: item for key, item in sparse_elf(binary)['structure'].items() if key != 'soname'}
        need(binary_facts['rpath'] is None and binary_facts['runpath'] is None,
             'built Bochs has no RPATH/RUNPATH')
        observations['binary'] = {**bytes_ref('bin/bochs', binary), 'elf': binary_facts}
        value['authority']['compilerExecuted'] = True
        runtime_raw = pack_zip(runtime_files, archive_cap=33554432, expanded_cap=67108864,
                               member_cap=256, modes=assembled['modes'])
        roles['runtime.original.zip'] = runtime_raw
        observations['runtimeManifest'] = raw_object(runtime_files['asset-manifest.json'], 4194304)
        observations['notices'] = assembled['notices']
        need(observations['runtimeManifest']['schema'] == 'bw.bochs-ring3.runtime-assets.v2' and
             not any(name.startswith('lib/') for name in runtime_files),
             'current asset-v2, no distributed host library body')
        phase = 'current-host-runtime-after'
        staged = ops.host_runtime_after()
        observations['hostRuntime'] = {'stageBytes': len(canonical(staged)),
                                      'stageSha256': sha256(canonical(staged))}
        roles['host-runtime.original.json'] = canonical({'schema': 'bw.bochs-ring3.host-runtime-original.v1',
                                                         'stage': staged, 'cleanup': None})
        phase = 'upstream-source-after'
        after = ops.upstream_after()
        roles['upstream.after.json'] = canonical(after)
        need(after == upstream['before'], 'selected upstream complete source before/after equality')
        phase = 'build-toolchain-after'
        observations['toolchainAfter'] = ops.toolchain()
        roles['toolchain.after.json'] = canonical(observations['toolchainAfter'])
        match_expected_graph(observations['toolchainAfter'], selected)
        need(observations['toolchainBefore'] == observations['toolchainAfter'],
             'held local tool graph before/after full identity')
        observations['nodeStage'] = ops.node_after(full_hash=True)
        check_node_stage_v2(observations['nodeStage'], 'build', env, after=True)
        roles['node-stage.original.json'] = canonical(observations['nodeStage'])
        manifest = {'schema': 'bw.bochs-ring3.build-manifest.v1', 'source': request['source'],
            'bochsSource': upstream['before'],
            'sourceInventory': {'selection': observations['sourceSelection'],
                'before': upstream['before'], 'after': after,
                'archive': bytes_ref('source-selected.original.tar.gz', upstream['sourceArchive'])},
            'toolchainInventory': {'selected': request['toolchain'],
                'before': observations['toolchainBefore'], 'after': observations['toolchainAfter']},
            'configure': {'argv': CONFIGURE_ARGV, 'makeArgv': MAKE_ARGV,
                'facts': observations['configure'],
                'versionHeader': bytes_ref('bxversion.h.original', version_raw)},
            'configHeader': observations['configHeader'],
            'compilerCommands': commands, 'elf': binary_facts,
            'runtimeMembers': runtime_rows(runtime_files, assembled['modes']),
            'notices': assembled['notices'], 'sourceAfter': None,
            'firstFailure': None, 'secondary': [],
            'buildCompleted': True, 'guestExecuted': False}
    except BaseException as exc:
        original_error(value, exc, phase)
    finally:
        if value['sourceBefore'] is not None:
            try:
                value['sourceAfter'] = ops.source(request['source'], env)
                roles['source.after.json'] = canonical(value['sourceAfter'])
                need(value['sourceBefore'] == value['sourceAfter'], 'Build source before/after equality')
            except BaseException as exc:
                original_error(value, exc, 'source-after')
        if value['resources'] is not None:
            try:
                value['resources']['after'] = ops.resources('build')
            except BaseException as exc:
                original_error(value, exc, 'resource-after')
        close_provider(ops, value, roles)
    value['complete'] = value['firstFailure'] is None and not value['secondary']
    if value['complete']:
        try:
            manifest['sourceAfter'] = value['sourceAfter']
            manifest_raw = canonical(manifest)
            need(len(manifest_raw) <= 4194304, 'bounded full build manifest')
            roles['build-manifest.json'] = manifest_raw
            observations['compactManifest'] = compact_build_manifest(request, manifest_raw, runtime_raw, manifest)
            roles['compact-manifest.json'] = canonical(observations['compactManifest'])
        except BaseException as exc:
            original_error(value, exc, 'build-manifest')
            value['complete'] = False
    roles['build.original.json'] = canonical(value)
    roles['manifest.json'] = canonical(original_manifest(roles))
    return value, roles

def selected_build_bytes_v2(request, raw):
    """Recheck the sole acquired byte copy; official authentication stays external."""
    selected = admit_reference_inputs_v2(request)
    need(type(raw) is bytes and len(raw) == selected['bytes'] and sha256(raw) == selected['sha256'],
         'sole selected Build archive exact bytes')
    files = unpack_zip(raw, archive_cap=67108864, expanded_cap=268435456, member_cap=4096)
    required = set(('request.original.json event.original.json source.before.json source.after.json '
        'node-stage.original.json upstream.tree.original.json source-selection.original.json '
        'upstream.before.json upstream.after.json toolchain.before.json toolchain.after.json '
        'build.original.json build-manifest.json compact-manifest.json runtime.original.zip '
        'source-selected.original.tar.gz config.h.original bxversion.h.original configure.stdout '
        'configure.stderr configure.process.json make.stdout make.stderr make.process.json '
        'notices/vgabios-corresponding-source.tar.gz manifest.json outside.original.json '
        'service-status.original.json cleanup.original.json runtime-elf-ranges.original.json '
        'host-runtime.original.json').split())
    need(set(files) == required, 'complete closed31-role Build original')
    need(raw_object(files['manifest.json'], 4194304) == original_manifest(
        {name: body for name, body in files.items() if name != 'manifest.json'}), 'complete nested Build delivery manifest')
    compact = raw_object(files['compact-manifest.json'], 16384)
    need(compact == selected['compactManifest'], 'retained compact equals pre-download selected log manifest')
    for key, name in (('fullManifest', 'build-manifest.json'), ('runtimeZip', 'runtime.original.zip'),
                      ('configHeader', 'config.h.original')):
        need(compact[key] == {'bytes': len(files[name]), 'sha256': sha256(files[name])},
             'nested compact reference actual bytes')
    build_request = request_object(files['request.original.json'])
    need(build_request['schema'] == 'bw.bochs-ring3.build-request.v1' and
         build_request['repository'] == REPOSITORY and build_request['pullRequest'] == request['pullRequest'] and
         build_request['policySha256'] == compact['policySha256'] and
         build_request['source'] == request['source'], 'Build and Reference same PR, policy and exact source12 graph')
    admit_build_inputs_v2(build_request)
    need({key:build_request['toolchain']['inventory'][key] for key in ('schema','jobName','version')} ==
         selected['metadata'], 'nested Build explicit selected metadata V2 identity')
    stage = raw_object(files['node-stage.original.json'], 65536)
    check_node_stage_v2(stage, 'build', {'GITHUB_RUN_ID': selected['runId'], 'GITHUB_RUN_ATTEMPT':'1'}, after=True)
    inner = raw_object(files['build.original.json'], 4194304)
    outside = raw_object(files['outside.original.json'], 16384)
    before = raw_object(files['source.before.json'], 1048576)
    after = raw_object(files['source.after.json'], 1048576)
    closed(before, ('head', 'tree', 'files', 'workflowCommit', 'workflowTree', 'workflowFileSha256'),
           'closed retained actual Build source observation')
    need(before == after == inner['sourceBefore'] == inner['sourceAfter'] and
         {key: before[key] for key in ('head', 'tree', 'files')} == request['source'] and
         before['workflowCommit'] == selected['workflowCommit'] and
         before['workflowFileSha256'] == selected['workflowFileSha256'] and
         GIT_HEX.fullmatch(before['workflowTree']), 'actual Build H and frozen executing W/source byte join')
    need(inner['schema'] == 'bw.bochs-ring3.build-original.v1' and inner['complete'] is True and
         inner['firstFailure'] is None and not inner['secondary'] and
         inner['requestSha256'] == sha256(files['request.original.json']) and
         inner['eventSha256'] == sha256(files['event.original.json']) and
         inner['authority'] == {'compilerExecuted': True, 'guestExecuted': False,
             'actualRunApproved': False, 'guestApproved': False, 'wholeHostAttested': False, 'physicalTimingProved': False} and
         outside['serviceExitCode'] == outside['clientExitCode'] == outside['cleanupExitCode'] == 0 and
         outside['firstFailure'] is None and not outside['secondary'] and outside['innerComplete'] is True and
         outside['innerFirstFailure'] is None and outside['after']['exists'] is False and
         outside['after']['errno'] == 2, 'complete actual Build and terminal cleanup originals')
    manifest = raw_object(files['build-manifest.json'], 4194304)
    need(manifest['source'] == request['source'] and manifest['buildCompleted'] is True and
         manifest['guestExecuted'] is False and manifest['firstFailure'] is None and not manifest['secondary'] and
         sha256(canonical(manifest['runtimeMembers'])) == compact['runtimeMembersSha256'] and
         sha256(canonical(manifest['notices'])) == compact['noticesSha256'], 'selected full Build manifest facts')
    runtime = unpack_zip(files['runtime.original.zip'], archive_cap=33554432,
                         expanded_cap=67108864, member_cap=256)
    with zipfile.ZipFile(io.BytesIO(files['runtime.original.zip'])) as archive:
        modes = {item.filename: item.external_attr >> 16 for item in archive.infolist()}
    need(manifest['runtimeMembers'] == runtime_rows(runtime,
         {name: stat.S_IMODE(mode) for name, mode in modes.items()}), 'every exact runtime member/mode/hash')
    asset = raw_object(runtime['asset-manifest.json'], 4194304)
    closed(asset, ('schema', 'source', 'bochsSource', 'hostNode', 'hostRuntime', 'files'), 'current asset-v2 keys')
    need(asset['schema'] == 'bw.bochs-ring3.runtime-assets.v2' and
         not any(name.startswith('lib/') for name in runtime) and
         asset['source'] == {'head': request['source']['head'], 'tree': request['source']['tree'],
            'filesSha256': sha256(canonical(request['source']['files']))} and
         asset['hostNode'] == build_request['toolchain']['node'] and
         asset['files'] == [row for row in manifest['runtimeMembers'] if row['path'] != 'asset-manifest.json'],
         'selected runtime distribution graph, no library bodies')
    need(compact['binary'] == {'bytes': len(runtime['bin/bochs']), 'sha256': sha256(runtime['bin/bochs'])},
         'selected compiled binary exact bytes')
    rom, fixture = authored_inputs()
    need(runtime['inputs/fixture.rom'] == rom and runtime['inputs/fixture.json'] == fixture and
         runtime['config/bochsrc.template'] == BOCHSRC_TEMPLATE and
         len(runtime['resources/vgabios.bin']) == VGA_BYTES and sha256(runtime['resources/vgabios.bin']) == VGA_SHA256,
         'unchanged authored inputs, config and selected VGA resource')
    expanded = sum(map(len, files.values())) + sum(map(len, runtime.values()))
    need(len(raw) + expanded + 16 * 1024 * 1024 <= LIMITS['reference']['expandedBytes'],
         'cumulative nested Build/runtime plus bounded Reference-original reservation')
    return {'files': files, 'runtime': runtime, 'modes': modes, 'manifest': manifest,
            'asset': asset, 'request': build_request, 'nestedExpandedBytes': expanded}

def collect_reference_v2(request_raw, event_raw, env, ops):
    request = admitted_request('reference', request_raw, event_raw, env)
    admit_reference_inputs_v2(request)
    value = original('reference', request_raw, event_raw)
    observations = {name: None for name in ('build', 'assetsBefore', 'assetsAfter', 'fixture',
        'config', 'js', 'bochs', 'stop', 'outside', 'cleanup', 'nodeStage', 'runtimeElfMetadata', 'hostRuntime')}
    value['observations'] = observations
    roles = {'request.original.json': request_raw, 'event.original.json': event_raw}
    phase = 'source-before'
    try:
        value['sourceBefore'] = ops.source(request['source'], env)
        roles['source.before.json'] = canonical(value['sourceBefore'])
        value['resources'] = {'before': ops.resources('reference'), 'after': None}
        phase = 'sole-selected-build-intake'
        try:
            archive, official = ops.acquire_build(request['build'], pull_request=request['pullRequest'])
        except BaseException:
            observations['build'] = getattr(ops, 'build_intake_partial', None)
            raise
        roles['inputs/build.original.zip'] = archive
        observations['build'] = official
        built = selected_build_bytes_v2(request, archive)
        phase = 'node-cache-data-staging'
        observations['nodeStage'] = ops.node_stage()
        check_node_stage_v2(observations['nodeStage'], 'reference', env)
        need(node_expectation(observations['nodeStage']) == built['asset']['hostNode'], 'same selected current staged Node')
        phase = 'current-host-runtime'
        graph = ops.toolchain()
        match_expected_graph(graph, {key: built['request']['toolchain'][key]
                                    for key in ('files', 'aliases', 'directoryAliases')})
        structural = admit_runtime_elf_metadata(ops.elf_metadata(graph), graph, observations['nodeStage'])
        roles['runtime-elf-ranges.original.json'] = canonical(structural)
        observations['runtimeElfMetadata'] = bytes_ref('runtime-elf-ranges.original.json', roles['runtime-elf-ranges.original.json'])
        need(host_runtime_selection(expected_graph(graph), structural, built['manifest']['elf'],
              observations['nodeStage']['elf']) == built['asset']['hostRuntime'], 'same source-selected runtime closure')
        stage = ops.host_runtime_stage(graph, structural)
        observations['hostRuntime'] = {'stageBytes': len(canonical(stage)), 'stageSha256': sha256(canonical(stage))}
        phase = 'owned-runtime-preparation'
        config = ops.prepare_reference(built)
        observations['config'] = bytes_ref('bochsrc.original', config)
        roles['bochsrc.original'] = config
        for name in ('inputs/fixture.rom', 'inputs/fixture.json'):
            roles[name] = built['runtime'][name]
        observations['fixture'] = {'rom': bytes_ref('inputs/fixture.rom', roles['inputs/fixture.rom']),
            'manifest': bytes_ref('inputs/fixture.json', roles['inputs/fixture.json'])}
        observations['assetsBefore'] = ops.runtime_after(built)
        roles['asset.before.json'] = canonical(observations['assetsBefore'])
        phase = 'fresh-js'
        value['authority']['guestExecuted'] = None
        js_process, js_streams, _stop = ops.process('js', ops.reference_argv('js'),
            wall_seconds=60, stream_cap=131072, checkpoint=False)
        value['phases'].append(js_process)
        roles.update({'js/stdout': js_streams['stdout'], 'js/stderr': js_streams['stderr'],
                      'js/process.json': canonical(js_process)})
        if js_process['firstFailure'] is not None:
            exc = Refusal(js_process['firstFailure']['message'])
            exc.bochs_first, exc.bochs_secondary = js_process['firstFailure'], js_process['secondary']
            raise exc
        need(js_process['firstFailure'] is None and not js_process['secondary'] and js_process['reaped'] and
             js_process['exitCode'] == 0 and js_process['signal'] is None and not js_process['timedOut'],
             'fresh JS complete retained child')
        js = ops.js_outputs()
        roles.update(js)
        report = raw_object(js['js/report.json'], 131072)
        need(report['schema'] == 'bw.ring3.js-probe.v1' and report['finiteRoundTripPass'] is True and
             report['firstFailure'] is None and report['completed'] is True and
             report['fixtureSha256'] == ROM_SHA256 and report['outputSha256'] == sha256(js_streams['stdout']) and
             report['memoryBeforeSha256'] == sha256(js['js/memory.before.bin']) and
             report['memoryAfterSha256'] == sha256(js['js/memory.after.bin']), 'genuine fresh JS probe completion')
        observations['js'] = report
        value['authority']['guestExecuted'] = True
        phase = 'fresh-bochs'
        process, streams, stop = ops.process('bochs', ops.reference_argv('bochs'),
            wall_seconds=60, stream_cap=131072, checkpoint=True)
        value['phases'].append(process)
        roles.update({'bochs/stdout': streams['stdout'], 'bochs/stderr': streams['stderr'],
                      'bochs/process.json': canonical(process)})
        observations['stop'] = stop
        if process['firstFailure'] is not None:
            exc = Refusal(process['firstFailure']['message'])
            exc.bochs_first, exc.bochs_secondary = process['firstFailure'], process['secondary']
            raise exc
        need(process['firstFailure'] is None and not process['secondary'] and process['reaped'] and
             process['signal'] == 15 and process['exitCode'] is None and not process['timedOut'] and
             stop is not None and stop['sent'] is True and stop['signal'] == 15 and
             stop['pid'] == process['pid'] and stop['firstFailure'] is None and not stop['secondary'],
             'complete frame followed by actual owned SIGTERM15 and reap')
        frame = reporter_frame(streams['stdout'])
        roles['bochs/frame.original'] = frame
        roles['bochs/log'] = ops.bochs_log()
        output_census = ops.reference_output_census()
        need(stop['frameSha256'] == sha256(frame), 'actual captured checkpoint frame hash')
        fixture = raw_object(roles['inputs/fixture.json'], 1048576)
        padding_bytes = compare_reference_frames(js_streams['stdout'], frame, fixture)
        observations['bochs'] = {'stdout': bytes_ref('bochs/stdout', streams['stdout']),
            'frame': bytes_ref('bochs/frame.original', frame), 'log': bytes_ref('bochs/log', roles['bochs/log']),
            'definedBytesEqual': True, 'selectorPaddingBytes': padding_bytes, 'outputCensus': output_census}
        phase = 'all-assets-after'
        observations['assetsAfter'] = ops.runtime_after(built)
        roles['asset.after.json'] = canonical(observations['assetsAfter'])
        need(observations['assetsBefore'] == observations['assetsAfter'], 'all retained input asset before/after equality')
        stage = ops.host_runtime_after()
        observations['hostRuntime'] = {'stageBytes': len(canonical(stage)), 'stageSha256': sha256(canonical(stage))}
        roles['host-runtime.original.json'] = canonical({'schema': 'bw.bochs-ring3.host-runtime-original.v1', 'stage': stage, 'cleanup': None})
        observations['nodeStage'] = ops.node_after(full_hash=True)
        check_node_stage_v2(observations['nodeStage'], 'reference', env, after=True)
    except BaseException as exc:
        original_error(value, exc, phase)
        # A failed but reaped child may already have written bounded diagnostic
        # originals. Retain those exact files without another child or intake.
        if phase == 'fresh-js' and value['phases'] and value['phases'][-1].get('reaped') is True:
            try:
                if not getattr(ops, 'js_output_attempted', False) and 'js/report.json' not in roles:
                    roles.update(ops.js_outputs())
            except BaseException as output_error:
                original_error(value, output_error, 'js-failed-output-retention')
            roles.update(getattr(ops, 'js_output_partial', {}))
        if phase == 'fresh-bochs' and value['phases'] and value['phases'][-1].get('reaped') is True:
            try:
                if not getattr(ops, 'bochs_log_attempted', False) and 'bochs/log' not in roles:
                    roles['bochs/log'] = ops.bochs_log()
            except BaseException as output_error:
                original_error(value, output_error, 'bochs-failed-log-retention')
    finally:
        if value['sourceBefore'] is not None:
            try:
                value['sourceAfter'] = ops.source(request['source'], env)
                roles['source.after.json'] = canonical(value['sourceAfter'])
                need(value['sourceBefore'] == value['sourceAfter'], 'Reference source before/after equality')
            except BaseException as exc:
                original_error(value, exc, 'source-after')
        if value['resources'] is not None:
            try:
                value['resources']['after'] = ops.resources('reference')
            except BaseException as exc:
                original_error(value, exc, 'resource-after')
        close_provider(ops, value, roles)
        if observations['nodeStage'] is not None:
            roles['node-stage.original.json'] = canonical(observations['nodeStage'])
    value['complete'] = value['firstFailure'] is None and not value['secondary']
    roles['resources.json'] = canonical(value['resources'])
    if value['complete']:
        try:
            # Cumulative decompression is a single budget, including retained
            # nested archives and every current Reference role/envelope.
            need(sum(map(len, roles.values())) + len(canonical(value)) +
                 len(canonical(original_manifest(roles))) + built['nestedExpandedBytes']
                 <= LIMITS['reference']['expandedBytes'], 'whole cumulative Reference/Build/runtime wire cap')
        except BaseException as exc:
            original_error(value, exc, 'reference-whole-wire')
            value['complete'] = False
    roles['original.json'] = canonical(value)
    roles['manifest.json'] = canonical(original_manifest(roles))
    return value, roles

def stage_facts_v2(inner):
    facts = (inner.get('observations') or {}).get('nodeStage') if type(inner) is dict else None
    if facts is None and type(inner) is dict and type(inner.get('failurePartial')) is dict:
        facts = inner['failurePartial'].get('nodeStage')
    return facts


def node_cleanup_authority_v2(route, env, inner):
    """Readonly no-follow identity and exact census, independent of cache grade."""
    root = route_paths(route, env)['node']
    facts = stage_facts_v2(inner)
    value = {'stageState': None, 'parentHeld': None, 'parentNamed': None,
             'directoryHeld': None, 'directoryNamed': None, 'members': {}, 'names': []}
    parent_fd = directory_fd = None
    first = None
    second = []
    def meta(info):return [getattr(info, 'st_'+key) for key in NODE_METADATA_FIELDS]
    def fixed(raw, directory):
        need(type(raw) is list and len(raw) == 9 and all(type(x) is int and x >= 0 for x in raw), 'typed V2 cleanup stat')
        need((stat.S_ISDIR(raw[2]) if directory else stat.S_ISREG(raw[2])) and
             raw[3:5] == [0,0] and raw[2] & 0o022 == 0, 'V2 cleanup owned immutable identity')
        return raw
    try:
        parent_fd = os.open('/run', os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC)
        value['parentHeld'] = fixed(meta(os.fstat(parent_fd)), True)
        value['parentNamed'] = fixed(meta(os.lstat('/run')), True)
        need(value['parentHeld'][:5] == value['parentNamed'][:5], 'V2 cleanup held/named parent')
        try:
            directory_fd = os.open(root.name, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC, dir_fd=parent_fd)
        except FileNotFoundError as exc:
            need(exc.errno == 2 and (facts is None or facts.get('created') == []), 'only an uncreated stage may be absent')
            value['stageState'] = 'not-created'
        if directory_fd is not None:
            need(type(facts) is dict and facts.get('schema') == 'bw.bochs-ring3.node-stage.v2' and
                 facts.get('stagePath') == str(root/'node') and facts.get('recordPath') == str(root/'stage.json'),
                 'protected source-created V2 stage paths')
            bootstrap_caller_scalars(facts['bootstrapCredentials'], facts['invoker'])
            created = facts.get('created')
            roster = [str(root),str(root/'node'),str(root/'stage.json')]
            need(type(created) is list and created in (roster[:1],roster[:2],roster), 'closed source-created stage prefix')
            expected = facts.get('directory') or facts.get('directoryAfterFailure') or facts.get('directoryInitial')
            value['directoryHeld'] = fixed(meta(os.fstat(directory_fd)), True)
            value['directoryNamed'] = fixed(meta(os.stat(root.name,dir_fd=parent_fd,follow_symlinks=False)), True)
            need(type(expected) is list and len(expected)==9 and value['directoryHeld'][:5] ==
                 value['directoryNamed'][:5] == expected[:5] and
                 stat.S_IMODE(expected[2]) in (0o700,0o555), 'fresh held/named source-created stage identity')
            with os.scandir(directory_fd) as entries:
                for item in entries:
                    need(len(value['names']) < 2 and item.name in ('node','stage.json') and item.name not in value['names'],
                         'finite known V2 stage census before effects')
                    value['names'].append(item.name)
            value['names'].sort()
            need(value['names'] == sorted(Path(x).name for x in created[1:]), 'exact created member census before effects')
            for name in value['names']:
                if name=='node':expected_member=facts.get('file') or facts.get('targetAfterFailure') or facts.get('fileBeforePublication') or facts.get('fileInitial')
                else:expected_member=(facts.get('record') or {}).get('metadata')
                need(type(expected_member) is list and len(expected_member)==9, 'known member identity, never guessed partial creation')
                fd = None
                primary = None
                try:
                    fd=os.open(name,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK|os.O_CLOEXEC,dir_fd=directory_fd)
                    held=fixed(meta(os.fstat(fd)),False)
                    named=fixed(meta(os.stat(name,dir_fd=directory_fd,follow_symlinks=False)),False)
                    need(held==named and held[:5]==expected_member[:5] and held[5]==1 and
                         0<=held[6]<=(NODE_BYTES if name=='node' else 4096), 'fresh held/named known private member')
                    need(stat.S_IMODE(held[2]) in ((0o600,0o555) if name=='node' else (0o444,)), 'exact source-created member permissions')
                    value['members'][name]={'held':held,'named':named}
                except BaseException as exc:primary=exc
                finally:
                    if fd is not None:
                        try:os.close(fd)
                        except BaseException as exc:
                            if primary is None:primary=exc
                            else:primary.bochs_secondary=[*getattr(primary,'bochs_secondary',[]),failure(exc,'node-plan-member-close')]
                if primary is not None:raise primary
            if not value['names']:
                need(stat.S_IMODE(value['directoryHeld'][2])==0o700, 'created empty stage remains private')
                value['stageState']='created-empty'
            elif value['names']==['node']:
                value['stageState']='complete-private-file' if (stat.S_IMODE(value['members']['node']['held'][2])==0o600 and
                    facts.get('sourceBytesRead')==facts.get('bytesCopied')==facts.get('readbackBytes')==NODE_BYTES and
                    facts.get('copiedSha256')==facts.get('readbackSha256')==NODE_SHA256) else 'partial-private-file'
                need(stat.S_IMODE(value['directoryHeld'][2])==0o700, 'partial private stage directory')
            else:
                need(value['names']==['node','stage.json'] and value['directoryHeld'][2]==stat.S_IFDIR|0o555 and
                     value['members']['node']['held'][2]==stat.S_IFREG|0o555 and
                     value['members']['stage.json']['held'][2]==stat.S_IFREG|0o444, 'complete published permission graph')
                value['stageState']='published'
            need(meta(os.fstat(directory_fd))[:5]==meta(os.stat(root.name,dir_fd=parent_fd,follow_symlinks=False))[:5]==value['directoryHeld'][:5],
                 'held/named V2 root after readonly plan census')
    except BaseException as exc:first=exc
    finally:
        for fd in (directory_fd,parent_fd):
            if fd is not None:
                try:os.close(fd)
                except BaseException as exc:
                    if first is None:first=exc
                    else:second.append(failure(exc,'node-plan-held-close'))
    if first is not None:
        first.bochs_secondary=[*getattr(first,'bochs_secondary',[]),*second][:SECONDARY_LIMIT]
        first.bochs_partial={'nodeCleanupAuthority':value}
        raise first
    return value


def node_cleanup_wire_plan_v2(route, env, inner):
    """Plan every bounded result before cgroup/Node/library cleanup effects."""
    facts=stage_facts_v2(inner)
    authority=node_cleanup_authority_v2(route,env,inner)
    root=route_paths(route,env)['node']
    def row(raw):return dict(zip(CLEANUP_STAT_FIELDS,raw))
    def future(value):
        return {**value,'size':max(value['size'],2**64-1),'nlink':max(value['nlink'],2**64-1),
                'mtimeNs':max(value['mtimeNs'],2**96-1),'ctimeNs':max(value['ctimeNs'],2**96-1)}
    gone={'exists':False,'errno':2,'identity':None}
    directory=None if authority['directoryHeld'] is None else row(authority['directoryHeld'])
    parent=future(row(authority['parentHeld']))
    private=None if directory is None else future({**directory,'mode':stat.S_IFDIR|0o700})
    prototype={'schema':'bw.bochs-ring3.node-cleanup.v2','route':route,'path':str(root),
        'stageState':authority['stageState'],'authority':authority,'planSha256':'f'*64,
        'parentBefore':parent,'parentAfter':parent,'before':gone if directory is None else {'exists':True,'errno':None,'identity':directory},
        'members':{name:row(value['held']) for name,value in authority['members'].items()},'journal':[],
        'after':gone,'heldBefore':directory,'heldBeforeRmdir':private,'namedBeforeRmdir':private,
        'complete':True,'firstFailure':None,'secondary':[]}
    if directory is not None:
        prototype['journal'].append({'operation':'chmod-private','path':str(root),'before':directory,'attempted':True,
            'after':{'exists':True,'errno':None,'identity':private},'firstFailure':None})
        for name,value in authority['members'].items():
            prototype['journal'].append({'operation':'unlink','path':str(root/name),'before':row(value['held']),
                'attempted':True,'after':gone,'firstFailure':None})
        prototype['journal'].append({'operation':'rmdir','path':str(root),'before':private,'attempted':True,'after':gone,'firstFailure':None})
    prototype=compact_manual_stats(prototype)
    success=len(canonical(prototype))
    # Mutation failure occupies journal/top-level facts, then an after-read
    # failure and a held-close failure: four bounded facts, at most 3072 bytes
    # for these fixed phases/paths plus 512 for a present after-stat. Record
    # the action at occurrence; its outer catch must not duplicate it again.
    failure_bytes=success+3*1024+512
    reserved=max(success+1024,failure_bytes)
    need(reserved<=16384,'complete V2 Node all-outcome plan under unchanged cap')
    return {'schema':'bw.bochs-ring3.node-cleanup-plan.v2','nodePath':str(root),
        'stageSha256':None if facts is None else sha256(canonical(facts)),
        'stageState':authority['stageState'],'authority':authority,
        'projectionSha256':sha256(canonical(prototype)),'successBytes':success,
        'failureBytes':failure_bytes,'reservedBytes':reserved}


def cleanup_node_stage_v2(route, env, inner, plan):
    """Remove only the exact source-created stage, with a bounded raw journal.

    Unknown names/identity stop before mutation. Partial staging without retained
    file identity remains an honest cleanup refusal, never guessed ownership.
    """
    paths = route_paths(route, env)
    root = paths['node']
    value = {'schema': 'bw.bochs-ring3.node-cleanup.v2', 'route': route,
        'path': str(root), 'parentBefore': None, 'parentAfter': None,
        'before': None, 'members': {}, 'journal': [], 'after': None,
        'heldBefore': None, 'heldBeforeRmdir': None, 'namedBeforeRmdir': None,
        'complete': False, 'firstFailure': None, 'secondary': []}
    value.update(stageState=plan['stageState'],authority=None,planSha256=sha256(canonical(plan)))
    directory_fd = None
    reserved = None
    retained_errors = []
    def issue(exc, phase):
        # Record at occurrence; the outer catch sees the same exception again.
        if any(previous is exc for previous in retained_errors):
            return
        retained_errors.append(exc)
        row = failure(exc, phase, path=str(root))
        if value['firstFailure'] is None:
            value['firstFailure'] = row
        elif len(value['secondary']) < SECONDARY_LIMIT:
            value['secondary'].append(row)
        for extra in getattr(exc, 'bochs_secondary', []):
            if len(value['secondary']) < SECONDARY_LIMIT:
                value['secondary'].append(extra)
    def first_five(row):
        return tuple(row[k] for k in ('dev', 'ino', 'mode', 'uid', 'gid'))
    def meta_row(raw):
        need(type(raw) is list and len(raw) == 9, 'retained staged identity before cleanup')
        return dict(zip(('dev', 'ino', 'mode', 'uid', 'gid', 'nlink', 'size', 'mtimeNs', 'ctimeNs'), raw))
    def absent(path):
        try:
            observed = os.lstat(path)
        except FileNotFoundError as exc:
            need(exc.errno == 2, 'actual ENOENT terminal stage observation')
            return {'exists': False, 'errno': 2, 'identity': None}
        return {'exists': True, 'errno': None, 'identity': identity(observed)}
    def mutation(operation, path, before, action):
        row = {'operation': operation, 'path': str(path), 'before': before,
               'attempted': False, 'after': None, 'firstFailure': None}
        value['journal'].append(row)
        need(reserved is not None and reserved <= 16384 and len(canonical(value)) <= 16384,
             'whole remaining bounded Node cleanup original before mutation')
        row['attempted'] = True
        try:
            action()
            row['after'] = absent(path)
        except BaseException as exc:
            row['firstFailure'] = failure(exc, 'node-cleanup-' + operation, path=str(path))
            issue(exc, 'node-cleanup-' + operation)
            try:
                row['after'] = absent(path)
            except BaseException as extra:
                issue(extra, 'node-cleanup-failed-after')
            raise
    try:
        closed(plan, ('schema','nodePath','stageSha256','stageState','authority','projectionSha256','successBytes','failureBytes','reservedBytes'), 'closed pre-effect V2 Node plan')
        need(plan['schema']=='bw.bochs-ring3.node-cleanup-plan.v2' and plan['nodePath']==str(root), 'same source-derived planned root')
        fresh=node_cleanup_wire_plan_v2(route,env,inner)
        need(fresh==plan, 'fresh held/named/census V2 Node plan before effects')
        value['authority']=fresh['authority']
        reserved=plan['reservedBytes']
        value['parentBefore'] = safe_root_directory('/run')
        facts = None if inner is None else (inner.get('observations') or {}).get('nodeStage')
        if facts is None and inner is not None and type(inner.get('failurePartial')) is dict:
            facts = inner['failurePartial'].get('nodeStage')
        value['before'] = absent(root)
        if not value['before']['exists']:
            need(facts is None or str(root) not in facts.get('created', []),
                 'created staged root may not disappear before owned cleanup')
            value['after'] = value['before']
        else:
            need(type(facts) is dict and facts.get('stagePath') == str(root / 'node') and
                 str(root) in facts.get('created', []), 'bound source-created Node root')
            expected_directory = facts.get('directory') or facts.get('directoryAfterFailure') or facts.get('directoryInitial')
            expected_directory = meta_row(expected_directory)
            need(first_five(value['before']['identity']) == first_five(expected_directory),
                 'exact first-five staged directory before cleanup')
            directory_fd = os.open(root, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC)
            value['heldBefore'] = identity(os.fstat(directory_fd))
            need(first_five(value['heldBefore']) == first_five(expected_directory),
                 'held Node cleanup directory identity')
            names = []
            with os.scandir(root) as entries:
                for entry in entries:
                    names.append(entry.name)
                    need(len(names) <= 2 and entry.name in ('node', 'stage.json'),
                         'no unknown staged Node member')
            expected = {}
            if 'node' in names:
                expected['node'] = meta_row(facts.get('file') or facts.get('targetAfterFailure') or
                                            facts.get('fileBeforePublication') or facts.get('fileInitial'))
            if 'stage.json' in names:
                need(type(facts.get('record')) is dict, 'retained installation-record identity')
                expected['stage.json'] = meta_row(facts['record']['metadata'])
            for name in names:
                observed = identity(os.stat(name, dir_fd=directory_fd, follow_symlinks=False))
                need(stat.S_ISREG(observed['mode']) and observed['uid'] == observed['gid'] == 0 and
                     observed['nlink'] == 1 and first_five(observed) == first_five(expected[name]),
                     'exact owned staged member before any cleanup mutation')
                value['members'][name] = observed
            # Size-only projection, never retained as an observation. Reserve all
            # remaining rows and terminal fields before the first chmod/unlink.
            def future_metadata(row):
                return {**row, 'size': max(row['size'], 2**64 - 1),
                        'mtimeNs': max(row['mtimeNs'], 2**64 - 1),
                        'ctimeNs': max(row['ctimeNs'], 2**64 - 1)}
            private_reserved = future_metadata({**value['before']['identity'], 'mode': stat.S_IFDIR | 0o700})
            future = json.loads(canonical(value))
            future['journal'] = [{'operation': 'chmod-private', 'path': str(root),
                'before': value['before']['identity'], 'attempted': True,
                'after': {'exists': True, 'errno': None, 'identity': private_reserved}, 'firstFailure': None}]
            for name in sorted(names):
                future['journal'].append({'operation': 'unlink', 'path': str(root / name),
                    'before': value['members'][name], 'attempted': True,
                    'after': {'exists': False, 'errno': 2, 'identity': None}, 'firstFailure': None})
            future['journal'].append({'operation': 'rmdir', 'path': str(root), 'before': private_reserved,
                'attempted': True, 'after': {'exists': False, 'errno': 2, 'identity': None}, 'firstFailure': None})
            future.update(parentAfter=future_metadata(value['parentBefore']),
                heldBeforeRmdir=private_reserved, namedBeforeRmdir=private_reserved,
                after={'exists': False, 'errno': 2, 'identity': None}, complete=True)
            need(len(canonical(compact_manual_stats(future)))+512 <= reserved, 'actual Node future fields fit complete pre-first-effect reserve')
            need(reserved <= 16384, 'complete prospective Node cleanup witness and close-error reserve')
            mutation('chmod-private', root, value['before']['identity'],
                     lambda: os.fchmod(directory_fd, 0o700))
            private = identity(os.fstat(directory_fd))
            need(private['mode'] == stat.S_IFDIR | 0o700 and
                 (private['dev'], private['ino'], private['uid'], private['gid']) ==
                 tuple(expected_directory[k] for k in ('dev', 'ino', 'uid', 'gid')),
                 'same privately writable cleanup root')
            for name in sorted(names):
                observed = identity(os.stat(name, dir_fd=directory_fd, follow_symlinks=False))
                need(first_five(observed) == first_five(expected[name]) and
                     first_five(identity(os.fstat(directory_fd))) == first_five(private) and
                     first_five(identity(os.lstat(root))) == first_five(private),
                     'held/named identities before each staged unlink')
                mutation('unlink', root / name, observed,
                         lambda name=name: os.unlink(name, dir_fd=directory_fd))
            with os.scandir(root) as entries:
                need(next(entries, None) is None, 'empty known staged root before rmdir')
            need(first_five(identity(os.lstat(root))) == first_five(private) and
                 first_five(identity(os.fstat(directory_fd))) == first_five(private),
                 'held/named root before final rmdir')
            value['heldBeforeRmdir'] = identity(os.fstat(directory_fd))
            value['namedBeforeRmdir'] = identity(os.lstat(root))
            mutation('rmdir', root, private, lambda: os.rmdir(root))
            value['after'] = absent(root)
            need(value['after']['exists'] is False, 'owned Node root absent after cleanup')
        value['parentAfter'] = safe_root_directory('/run')
        need(first_five(value['parentBefore']) == first_five(value['parentAfter']),
             'fixed root parent first-five after Node cleanup')
    except BaseException as exc:
        issue(exc, 'node-stage-cleanup')
    finally:
        if directory_fd is not None:
            try:
                os.close(directory_fd)
            except BaseException as exc:
                issue(exc, 'node-cleanup-directory-close')
    value['complete'] = value['firstFailure'] is None and not value['secondary']
    if value['complete'] and len(canonical(value)) > 16384:
        issue(Refusal('complete Node cleanup wire cap'), 'node-cleanup-final-wire')
        value['complete'] = False
    value=compact_manual_stats(value)
    need(len(canonical(value)) <= 16384, 'V2 Node final exact wire cap')
    return value

def main(argv=None, *, environment=None, provider_factory=None):
    parser = argparse.ArgumentParser(description=__doc__)
    modes = parser.add_mutually_exclusive_group(required=True)
    for flag in ('admit', 'work', 'run-service', 'capture-service-status', 'finish'):
        modes.add_argument('--' + flag, action='store_true')
    parser.add_argument('--route', choices=tuple(ROUTES), required=True)
    parser.add_argument('--workflow-root')
    parser.add_argument('--invoker-uid', type=int)
    parser.add_argument('--invoker-gid', type=int)
    parser.add_argument('--service-exit', default='unknown')
    parser.add_argument('--client-exit', default='unknown')
    parser.add_argument('--service-status')
    args = parser.parse_args(argv)
    route_enabled(args.route, current=True)  # all modes fail before env/file/kernel edges when false
    env = os.environ if environment is None else environment
    if args.admit:
        need(args.workflow_root is not None and args.invoker_uid is not None and
             args.invoker_gid is not None, 'explicit trusted workflow bootstrap arguments')
        admit_cli(args.route, env, args.workflow_root, args.invoker_uid, args.invoker_gid, current=True)
        return 0
    context, request_raw, event_raw, paths = load_cli_context(args.route, env, current=True)
    if args.run_service:
        process = run_service_cli(args.route, context, paths,
                                  secret=env.get('GH_TOKEN') if args.route == 'reference' else None)
        return 0 if process['firstFailure'] is None and not process['secondary'] and \
            process['reaped'] and process['exitCode'] == 0 else 1
    if args.capture_service_status:
        status = capture_service_status_cli(args.route, context, paths)
        return 0 if status['firstFailure'] is None and not status['secondary'] else 1
    factory = provider_factory if provider_factory is not None else LiveOps
    if args.work:
        value = work_cli(args.route, context, request_raw, event_raw, paths, provider_factory=factory, current=True)
        return 0 if value['complete'] else 1
    need(args.service_status is not None, 'explicit protected service status path')
    outside, roles = finish_cli(args.route, context, request_raw, event_raw, paths,
        provider_factory=factory, service_status=args.service_status,
        claimed_service=parse_exit(args.service_exit), claimed_client=parse_exit(args.client_exit), current=True)
    if outside['cleanupExitCode'] == 0 and args.route == 'build':
        compact = raw_object(roles['compact-manifest.json'], 32768)
        print(COMPACT_MARKER + base64.b64encode(canonical(compact)).decode('ascii'), flush=True)
    return outside['cleanupExitCode']


if __name__ == '__main__':
    try:
        raise SystemExit(main())
    except Exception as exc:
        # No context/env dump, exception args repr or traceback at the secret edge.
        print(type(exc).__name__ + ': ' + str(exc)[:ERROR_LIMIT], file=sys.stderr)
        raise SystemExit(1)
